CREATE SCHEMA smarter_private;CREATE SEQUENCE smarter_private.f06_lifecycle_seq;CREATE FUNCTION smarter_private.f06_new_lifecycle() RETURNS bigint
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ SELECT nextval('smarter_private.f06_lifecycle_seq') $$;

CREATE FUNCTION public.fn_bbj_default_mini_floor() RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  /* Three times the largest ENABLED mini tier, never below 5,000.
     Three because the worst day this jackpot has had cost 2.72 tiers
     (4,075.00 against a 1,500.00 top tier), so three covers it with room;
     the 5,000 floor-under-the-floor keeps today's value exactly where it is
     and stops a club with only small tiers enabled from running a reserve
     too thin to absorb any burst at all. */
  SELECT GREATEST(
    COALESCE((SELECT max(mt.amount) FROM public.bbj_mini_tiers mt WHERE mt.enabled), 0) * 3,
    5000
  );
$$;

CREATE FUNCTION public.fn_ca_current_epoch() RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$ SELECT id FROM public.ca_financial_epochs WHERE is_current LIMIT 1 $$;

CREATE FUNCTION public.fn_ca_house_board_allows_automation(p_club_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- DERIVED FIRST: the platform club is the house board, and always will be, without anybody
  -- remembering to add it to a list. This is the half that cannot rot.
  SELECT COALESCE((SELECT c.is_platform FROM public.clubs c WHERE c.id = p_club_id), false)
     -- LEGACY, AND IT IS DEBT: four chip house boards that predate clubs.is_platform and carry no
     -- flag of their own. Give them one and these four lines delete themselves.
     OR p_club_id = ANY (ARRAY[
          'a41434bb-8d0c-400a-8f0d-e8b3d65afed4'::uuid,   -- Club JAQK
          'a0000000-0000-0000-0000-000000000001'::uuid,   -- SHARK CLUB
          'fade0000-0000-0000-0000-000000000001'::uuid,   -- Midway Union
          '2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid    -- Deep Stack Society
        ]);
$$;

CREATE TABLE public.accounting_agreement_history (
    id bigint NOT NULL,
