    before_terms jsonb,
    after_terms jsonb,
    union_id uuid,
    CONSTRAINT accounting_agreement_history_check CHECK (((before_terms IS NOT NULL) OR (after_terms IS NOT NULL))),
    CONSTRAINT accounting_agreement_history_entity_type_check CHECK ((entity_type = ANY (ARRAY['agents'::text, 'club_members'::text, 'union_clubs'::text, 'unions'::text]))),
    CONSTRAINT accounting_agreement_history_event_type_check CHECK ((event_type = ANY (ARRAY['baseline'::text, 'INSERT'::text, 'UPDATE'::text, 'DELETE'::text]))),
    CONSTRAINT accounting_agreement_history_scope_check CHECK ((((entity_type = 'unions'::text) AND (union_id IS NOT NULL) AND (club_id IS NULL) AND (subject_user_id IS NULL) AND (entity_key = (union_id)::text)) OR ((entity_type <> 'unions'::text) AND (club_id IS NOT NULL) AND (union_id IS NULL))))
);
