    CONSTRAINT tournament_cancellation_receipts_check9 CHECK ((source_seat_count = cardinality(source_seat_ids))),
    CONSTRAINT tournament_cancellation_receipts_closed_table_count_check CHECK ((closed_table_count >= 0)),
