    attempts integer DEFAULT 0 NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    result jsonb DEFAULT '{}'::jsonb NOT NULL,
    standalone_club_id uuid,
    scope_kind text GENERATED ALWAYS AS (
CASE
    WHEN (union_id IS NOT NULL) THEN 'union'::text
    ELSE 'club'::text
END) STORED NOT NULL,
    scope_id uuid GENERATED ALWAYS AS (COALESCE(union_id, standalone_club_id)) STORED NOT NULL,
    last_scheduler_visit_at timestamp with time zone,
    CONSTRAINT accounting_run_has_one_scope CHECK (((union_id IS NULL) <> (standalone_club_id IS NULL))),
    CONSTRAINT union_accounting_runs_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT union_accounting_runs_check CHECK ((isfinite(period_start) AND isfinite(period_end) AND (period_start < period_end))),
    CONSTRAINT union_accounting_runs_last_scheduler_visit_at_check CHECK (((last_scheduler_visit_at IS NULL) OR isfinite(last_scheduler_visit_at))),
    CONSTRAINT union_accounting_runs_status_check CHECK ((status = ANY (ARRAY['running'::text, 'complete'::text, 'failed'::text])))
);
