CREATE TABLE public.union_pnl_cash_outcome_link_resolutions (
    table_id uuid NOT NULL,
    hand_number bigint NOT NULL,
    hand_id uuid NOT NULL,
    outcome_payload_hash text NOT NULL,
    outcome_evidence_md5 text NOT NULL,
    roster_source text NOT NULL,
    manifest_id uuid,
    game_scope jsonb NOT NULL,
    evidence jsonb NOT NULL,
    proof jsonb NOT NULL,
    proof_md5 text NOT NULL,
    reason text NOT NULL,
    resolved_by text DEFAULT SESSION_USER NOT NULL,
    resolved_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT union_pnl_cash_outcome_link_resoluti_outcome_evidence_md5_check CHECK ((outcome_evidence_md5 ~ '^[0-9a-f]{32}$'::text)),
    CONSTRAINT union_pnl_cash_outcome_link_resolutions_check CHECK ((proof_md5 = md5((proof)::text))),
    CONSTRAINT union_pnl_cash_outcome_link_resolutions_check1 CHECK (((roster_source = 'manifest'::text) = (manifest_id IS NOT NULL))),
    CONSTRAINT union_pnl_cash_outcome_link_resolutions_check2 CHECK ((((proof ->> 'status'::text) = 'proven'::text) AND ((proof ->> 'resolution_kind'::text) = 'cash_outcome_provenance_link'::text) AND ((proof ->> 'table_id'::text) = (table_id)::text) AND (((proof ->> 'hand_number'::text))::bigint = hand_number) AND ((proof ->> 'hand_id'::text) = (hand_id)::text) AND ((proof ->> 'outcome_payload_hash'::text) = outcome_payload_hash) AND ((proof ->> 'outcome_evidence_md5'::text) = outcome_evidence_md5) AND ((proof ->> 'roster_source'::text) = roster_source) AND (NOT ((proof ->> 'manifest_id'::text) IS DISTINCT FROM (manifest_id)::text)) AND ((proof -> 'game_scope'::text) = game_scope) AND ((proof -> 'evidence'::text) = evidence) AND ((evidence -> 'game_scope'::text) = game_scope))),
    CONSTRAINT union_pnl_cash_outcome_link_resolutions_evidence_check CHECK (((jsonb_typeof(evidence) = 'object'::text) AND ((evidence ->> 'provenance_link'::text) = 'resolved'::text))),
    CONSTRAINT union_pnl_cash_outcome_link_resolutions_game_scope_check CHECK (((jsonb_typeof(game_scope) = 'object'::text) AND (game_scope ?& ARRAY['game_union_id'::text, 'host_club_id'::text, 'tournament_id'::text, 'is_private'::text, 'asset'::text, 'unit_scale'::text]))),
    CONSTRAINT union_pnl_cash_outcome_link_resolutions_reason_check CHECK ((length(btrim(reason)) >= 20)),
    CONSTRAINT union_pnl_cash_outcome_link_resolutions_roster_source_check CHECK ((roster_source = ANY (ARRAY['manifest'::text, 'seat_inventory'::text])))
);
