    CONSTRAINT union_pnl_inventory_checkpoints_issue_count_check CHECK ((issue_count >= 0)),
    CONSTRAINT union_pnl_inventory_checkpoints_issues_md5_check CHECK ((issues_md5 ~ '^[0-9a-f]{32}$'::text)),
