    transaction_id xid8 NOT NULL,
    operation text NOT NULL,
    before_row jsonb,
    after_row jsonb,
    CONSTRAINT union_pnl_inventory_events_check CHECK (((before_row IS NOT NULL) OR (after_row IS NOT NULL))),
    CONSTRAINT union_pnl_inventory_events_check1 CHECK ((((before_row IS NULL) OR ((jsonb_typeof(before_row) = 'object'::text) AND ((before_row ->> 'id'::text) = (row_id)::text))) IS TRUE)),
    CONSTRAINT union_pnl_inventory_events_check2 CHECK ((((after_row IS NULL) OR ((jsonb_typeof(after_row) = 'object'::text) AND ((after_row ->> 'id'::text) = (row_id)::text))) IS TRUE)),
    CONSTRAINT union_pnl_inventory_events_check3 CHECK ((((operation = ANY (ARRAY['baseline'::text, 'INSERT'::text])) AND (before_row IS NULL) AND (after_row IS NOT NULL)) OR ((operation = 'UPDATE'::text) AND (before_row IS NOT NULL) AND (after_row IS NOT NULL)) OR ((operation = 'DELETE'::text) AND (before_row IS NOT NULL) AND (after_row IS NULL)))),
    CONSTRAINT union_pnl_inventory_events_observed_at_check CHECK (isfinite(observed_at)),
    CONSTRAINT union_pnl_inventory_events_operation_check CHECK ((operation = ANY (ARRAY['baseline'::text, 'INSERT'::text, 'UPDATE'::text, 'DELETE'::text]))),
    CONSTRAINT union_pnl_inventory_events_source_name_check CHECK ((source_name = ANY (ARRAY['union_clubs'::text, 'tables'::text, 'table_seats'::text, 'tournaments'::text, 'tournament_players'::text])))
)
WITH (autovacuum_vacuum_insert_scale_factor='0.0', autovacuum_vacuum_insert_threshold='100000');
