    boundary timestamp with time zone NOT NULL,
    registration_id uuid NOT NULL,
    tournament_id uuid NOT NULL,
    user_id uuid NOT NULL,
    union_id uuid NOT NULL,
    registration_row_md5 text NOT NULL,
    tournament_row_md5 text NOT NULL,
    owning_club_id uuid NOT NULL,
    asset text NOT NULL,
    entries integer NOT NULL,
    entry_amount numeric NOT NULL,
    returned numeric NOT NULL,
    deferred_amount numeric NOT NULL,
    resolution_kind text NOT NULL,
    proof jsonb NOT NULL,
    proof_md5 text NOT NULL,
    reason text NOT NULL,
    resolved_by text DEFAULT SESSION_USER NOT NULL,
    resolved_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT union_pnl_opening_registration_resol_registration_row_md5_check CHECK ((registration_row_md5 ~ '^[0-9a-f]{32}$'::text)),
    CONSTRAINT union_pnl_opening_registration_resolut_tournament_row_md5_check CHECK ((tournament_row_md5 ~ '^[0-9a-f]{32}$'::text)),
    CONSTRAINT union_pnl_opening_registration_resolution_resolution_kind_check CHECK ((resolution_kind = 'opening_registration_entry_from_chip_ledger'::text)),
    CONSTRAINT union_pnl_opening_registration_resolutions_asset_check CHECK ((asset = 'chips'::text)),
    CONSTRAINT union_pnl_opening_registration_resolutions_check CHECK ((deferred_amount = (entry_amount - returned))),
    CONSTRAINT union_pnl_opening_registration_resolutions_check1 CHECK ((proof_md5 = md5((proof)::text))),
    CONSTRAINT union_pnl_opening_registration_resolutions_check2 CHECK (((jsonb_typeof(proof) = 'object'::text) AND ((proof ->> 'status'::text) = 'proven'::text) AND ((proof ->> 'resolution_kind'::text) = resolution_kind) AND (((proof ->> 'boundary'::text))::timestamp with time zone = boundary) AND ((proof ->> 'registration_id'::text) = (registration_id)::text) AND ((proof ->> 'tournament_id'::text) = (tournament_id)::text) AND ((proof ->> 'user_id'::text) = (user_id)::text) AND ((proof ->> 'union_id'::text) = (union_id)::text) AND ((proof ->> 'registration_row_md5'::text) = registration_row_md5) AND ((proof ->> 'tournament_row_md5'::text) = tournament_row_md5) AND ((proof ->> 'owning_club_id'::text) = (owning_club_id)::text) AND ((proof ->> 'instrument'::text) = asset) AND (((proof ->> 'entries'::text))::integer = entries) AND (((proof ->> 'entry_amount'::text))::numeric = entry_amount) AND (((proof ->> 'returned'::text))::numeric = returned) AND (((proof ->> 'deferred_amount'::text))::numeric = deferred_amount))),
    CONSTRAINT union_pnl_opening_registration_resolutions_entries_check CHECK ((entries >= 1)),
    CONSTRAINT union_pnl_opening_registration_resolutions_entry_amount_check CHECK (((entry_amount >= (0)::numeric) AND (entry_amount = round(entry_amount, 2)))),
    CONSTRAINT union_pnl_opening_registration_resolutions_reason_check CHECK ((length(btrim(reason)) >= 20)),
    CONSTRAINT union_pnl_opening_registration_resolutions_returned_check CHECK (((returned >= (0)::numeric) AND (returned = round(returned, 2))))
);
