CREATE FUNCTION public.fn_settlement_floor_refuses_owed_agent_commission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_from   timestamptz;
  v_to     timestamptz := NEW.earliest_period_start;
  v_clubs  uuid[];
  v_cursor timestamptz;
  p record; s record; v_owed record; v_stranded boolean := false;
BEGIN
  v_from := CASE WHEN TG_OP = 'UPDATE' THEN OLD.earliest_period_start ELSE '-infinity'::timestamptz END;
  IF v_to IS NULL OR v_to <= v_from THEN
    RETURN NEW;  -- a floor that does not move up skips nothing
  END IF;
  IF TG_TABLE_NAME = 'union_settlement_floor' THEN
    v_clubs := ARRAY(SELECT c.id FROM public.clubs c WHERE c.union_id = NEW.union_id OR c.id = NEW.union_id ORDER BY 1);
  ELSE
    v_clubs := ARRAY[NEW.club_id];
  END IF;

  -- Per (club, agent) with unsettled commission (the rollup keeps one row for
  -- every such pair): walk its settlement periods across the skipped range and
  -- probe each uncovered gap for an unsettled row, by index range. Measured on
  -- production 2026-10-03: 30 ms for the union's week of 09-21 (all covered),
  -- 1 ms to find the first stranded row below 09-28 before 20261003092151.
  <<pairs>>
  FOR p IN SELECT r.club_id, r.user_id FROM public.agent_commission_unsettled_rollup r
            WHERE r.club_id = ANY(v_clubs) ORDER BY 1, 2 LOOP
    v_cursor := v_from;
    FOR s IN SELECT x.period_start, x.period_end FROM public.agent_commission_settlements x
              WHERE x.club_id = p.club_id AND x.user_id = p.user_id
                AND x.period_end > v_from AND x.period_start < v_to
              ORDER BY x.period_start LOOP
      IF s.period_start > v_cursor THEN
        SELECT a.club_id, a.user_id, a.created_at, a.amount INTO v_owed FROM public.agent_commissions a
         WHERE a.club_id = p.club_id AND a.user_id = p.user_id AND a.settled_at IS NULL
           AND a.created_at >= v_cursor AND a.created_at < s.period_start
         ORDER BY a.created_at LIMIT 1;
        v_stranded := FOUND;
        EXIT pairs WHEN v_stranded;
      END IF;
      v_cursor := greatest(v_cursor, s.period_end);
    END LOOP;
    IF v_cursor < v_to THEN
      SELECT a.club_id, a.user_id, a.created_at, a.amount INTO v_owed FROM public.agent_commissions a
       WHERE a.club_id = p.club_id AND a.user_id = p.user_id AND a.settled_at IS NULL
         AND a.created_at >= v_cursor AND a.created_at < v_to
       ORDER BY a.created_at LIMIT 1;
      v_stranded := FOUND;
      EXIT pairs WHEN v_stranded;
    END IF;
  END LOOP;

  IF v_stranded THEN
    RAISE EXCEPTION 'settlement_floor_would_strand_agent_commission'
      USING ERRCODE = '23514',
            DETAIL = format('Moving the %s floor from %s to %s skips recorded agent commission that is unsettled and covered by no settlement period, e.g. club %s agent %s row of %s (%s). Below the floor no path can ever pay it.',
                            TG_TABLE_NAME, v_from, v_to, v_owed.club_id, v_owed.user_id, v_owed.created_at, v_owed.amount),
            HINT = 'Pay or settle the skipped weeks first (agent_commission_settlements periods, as 20261003092151 did), then move the floor.';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION public.fn_sync_profile_total_hands() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user uuid := COALESCE(NEW.user_id, OLD.user_id);
BEGIN
  IF v_user IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  /* A WRITE THAT LEAVES hands_played WHERE IT WAS DOES NOT TOUCH THE PROFILE
     (2026-10-01). The trigger fires for every UPDATE that names the column,
     and a tournament's rake recognition names it with +0 for every entrant
     (apply_rakeback_player_stats(..., 0, ...)): the sum below cannot move,
     but its UPDATE locked each entrant's profile row, in club order, while
     the horse claims hold profile rows in claim order - and the two
     deadlocked. The same player and the same count leave the same sum. */
  IF TG_OP = 'UPDATE' AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id
     AND NEW.hands_played IS NOT DISTINCT FROM OLD.hands_played THEN
    RETURN NEW;
  END IF;

  /* Recomputed from the table rather than incremented. An increment has to be
     right on every path - insert, update, delete, and the upsert the
     achievement engine uses - and being wrong once is permanent. A SUM over a
     handful of club rows for one player is cheap and cannot drift. */
  UPDATE public.profiles p
     SET total_hands_played = COALESCE((
           SELECT sum(s.hands_played) FROM public.player_stats s WHERE s.user_id = v_user
         ), 0)
   WHERE p.id = v_user;

  RETURN COALESCE(NEW, OLD);
END;
$$;

CREATE FUNCTION public.fn_terminal_tournament_evidence_is_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tournament_id uuid;
  v_status text;
  v_receipted boolean := false;
  v_old_marker timestamptz;
  v_new_marker timestamptz;
BEGIN
  IF TG_OP<>'DELETE' AND public.fn_ca_legacy_fee_resolution_write_is_exact(TG_TABLE_NAME,TG_OP,CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' THEN
    v_tournament_id := NULLIF(to_jsonb(NEW)->>'tournament_id','')::uuid;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NULLIF(to_jsonb(NEW)->>'tournament_id','')::uuid IS DISTINCT FROM
       NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid THEN
      RAISE EXCEPTION '% rows cannot move between tournaments',TG_TABLE_NAME
        USING ERRCODE = '55000';
    END IF;
    v_tournament_id := NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid;
  ELSE
    v_tournament_id := NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid;
  END IF;

  IF v_tournament_id IS NULL THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP <> 'INSERT' AND to_jsonb(OLD) ? 'terminal_closed_at' THEN
    v_old_marker := NULLIF(to_jsonb(OLD)->>'terminal_closed_at','')::timestamptz;
  END IF;
  IF TG_OP <> 'DELETE' AND to_jsonb(NEW) ? 'terminal_closed_at' THEN
    v_new_marker := NULLIF(to_jsonb(NEW)->>'terminal_closed_at','')::timestamptz;
  END IF;
  IF TG_OP = 'INSERT' AND v_new_marker IS NOT NULL THEN
    RAISE EXCEPTION '% rows cannot supply a terminal marker',TG_TABLE_NAME
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' AND v_old_marker IS NOT NULL THEN
    RAISE EXCEPTION 'terminal tournament % has immutable % evidence',
      v_tournament_id,TG_TABLE_NAME USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'UPDATE' AND v_new_marker IS DISTINCT FROM v_old_marker THEN
    IF public.fn_ca_terminal_marker_transition_is_exact(
         to_jsonb(OLD),to_jsonb(NEW),v_tournament_id) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION '% terminal marker transition is not canonical',TG_TABLE_NAME
      USING ERRCODE = '55000';
  END IF;
  -- A journal row is durable testimony from the instant it names a
  -- tournament. Refuse its UPDATE/DELETE without taking a child-to-parent
  -- lock; a row trigger already owns the child tuple at this point. INSERT is
  -- the only operation that takes the root lock, which preserves the
  -- parent-to-child order used by both terminal authorities.
  IF TG_TABLE_NAME = 'chip_ledger' AND TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'tournament chip ledger evidence is append-only'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT upper(COALESCE(t.status::text,'')) INTO v_status
      FROM public.tournaments t
     WHERE t.id = v_tournament_id
     FOR SHARE;
  ELSE
    SELECT upper(COALESCE(t.status::text,'')) INTO v_status
      FROM public.tournaments t
     WHERE t.id = v_tournament_id;
  END IF;
  SELECT EXISTS (
           SELECT 1 FROM public.tournament_terminal_settlements h
            WHERE h.tournament_id = v_tournament_id)
      OR EXISTS (
           SELECT 1 FROM public.tournament_satellite_settlements h
            WHERE h.tournament_id = v_tournament_id)
      OR EXISTS (
           SELECT 1 FROM public.tournament_cancellation_receipts h
            WHERE h.tournament_id = v_tournament_id)
    INTO v_receipted;
  IF v_status IN ('COMPLETED','CANCELLED','CANCELED')
     AND (TG_OP = 'INSERT' OR v_receipted) THEN
    RAISE EXCEPTION
      'terminal tournament % has immutable % evidence',
      v_tournament_id,TG_TABLE_NAME USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.fn_union_close_post_rake_debit(p jsonb) RETURNS TABLE(rw_before numeric, rw_after numeric, cb_before numeric, cb_after numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
 u uuid:=(p->>'union_id')::uuid; sid uuid:=(p->>'settlement_id')::uuid;
 p_from timestamptz:=(p->>'period_start')::timestamptz; p_to timestamptz:=(p->>'period_end')::timestamptz;
 v_total numeric:=(p->>'period_total')::numeric; v_payout numeric:=(p->>'payout_total')::numeric;
 v_retained numeric:=(p->>'retained')::numeric; v_actor uuid:=(p->>'actor')::uuid;
 v_ledger_id uuid; v_prior jsonb; k text;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF u IS NULL OR sid IS NULL OR p_from IS NULL OR p_to IS NULL OR v_total IS NULL OR v_payout IS NULL OR v_retained IS NULL
  OR v_total<=0 OR v_payout<0 OR v_retained<0 OR round(v_payout+v_retained,2)<>round(v_total,2)
  OR jsonb_typeof(p->'clubs') IS DISTINCT FROM 'array'
  OR (SELECT round(COALESCE(sum((c->>'payout')::numeric),0),2) FROM jsonb_array_elements(p->'clubs') c)<>round(v_payout,2)
  OR NOT EXISTS(SELECT 1 FROM public.ca_settlements s WHERE s.id=sid AND s.settlement_type='union_rakeback_close' AND s.union_id=u)
 THEN RAISE EXCEPTION 'union_close_rake_debit_invalid' USING ERRCODE='22023', DETAIL=p::text; END IF;
 SELECT jsonb_object_agg(x,current_setting(x,true)) INTO v_prior FROM unnest(ARRAY[
  'app.ledger_autoskip_clubs','app.ledger_autoskip_union_wallets','app.ledger_category',
  'app.ledger_counterparty','app.ledger_counterparty_entity','app.ledger_settlement'])x;
 PERFORM public.fn_ca_declare_ledger('rakeback','union_wallet',u,sid,NULL,ARRAY['union_wallets','clubs']);
 -- one debit per pot: the treasury pays the whole period; the retained
 -- share moves to the general bank
 UPDATE public.union_wallets
    SET rake_wallet       = rake_wallet - v_total,
        chip_balance      = chip_balance + v_retained,
        total_settlements = COALESCE(total_settlements, 0) + v_payout,
        updated_at        = now()
  WHERE union_id = u AND rake_wallet >= v_total
  RETURNING round(rake_wallet, 2), round(chip_balance, 2) INTO rw_after, cb_after;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'insufficient_rake_treasury' USING ERRCODE='P0001',
   DETAIL=jsonb_build_object('union_id',u,'period_total',v_total,'settlement_id',sid)::text;
 END IF;
 rw_before:=round(rw_after+v_total,2); cb_before:=round(cb_after-v_retained,2);
 INSERT INTO public.union_wallet_transactions
   (union_id, club_id, amount, tx_type, wallet, direction, balance_after, notes)
 SELECT u, (c->>'club_id')::uuid, (c->>'payout')::numeric, 'rakeback', 'rake_wallet', 'debit', rw_after,
        'Weekly rakeback to club at the per-game-type rate (period '
          || to_char(p_from, 'YYYY-MM-DD') || '..' || to_char(p_to, 'YYYY-MM-DD') || ')'
   FROM jsonb_array_elements(p->'clubs') c ORDER BY c->>'club_id';
 IF v_retained > 0 THEN
  INSERT INTO public.union_wallet_transactions
    (union_id, amount, tx_type, wallet, direction, balance_after, notes)
  VALUES
    (u, v_retained, 'rake_hold', 'rake_wallet', 'debit', rw_after,
     'Union retained share + self-club rake, out of the rake treasury (period '
       || to_char(p_from, 'YYYY-MM-DD') || '..' || to_char(p_to, 'YYYY-MM-DD') || ')'),
    (u, v_retained, 'rake_hold', 'chip_balance', 'credit', cb_after,
     'Union retained share + self-club rake, into the general bank (period '
       || to_char(p_from, 'YYYY-MM-DD') || '..' || to_char(p_to, 'YYYY-MM-DD') || ')');
  INSERT INTO public.chip_ledger
    (performed_by, from_type, from_entity_id, to_type, to_entity_id,
     amount, category, union_id, description, idempotency_key, metadata, from_label)
  VALUES
    (v_actor, 'union_wallet', u, 'union_bank', u,
     v_retained, 'treasury_transfer', u,
     'Weekly union close ' || to_char(p_from, 'YYYY-MM-DD') || '..' || to_char(p_to, 'YYYY-MM-DD')
       || ': retained share ' || v_retained || ' of period rake ' || v_total
       || ' moves from the rake treasury to the general bank (clubs paid ' || v_payout || ')',
     'union_close:' || sid::text || ':retained',
     jsonb_build_object('settlement_id', sid, 'period_start', p_from, 'period_end', p_to,
                        'period_rake', v_total, 'payout_total', v_payout,
                        'clubs_paid', (p->>'clubs_paid')::int), 'union_wallets.rake_wallet') RETURNING id INTO v_ledger_id;
  IF NOT EXISTS(SELECT 1 FROM public.settlement_invoices i WHERE i.source_ledger_id=v_ledger_id AND i.status='paid'
    AND i.net_amount=v_retained AND i.chips_transferred AND i.message_sent
    AND EXISTS(SELECT 1 FROM public.accounting_invoice_deliveries d WHERE d.invoice_id=i.id)) THEN
   RAISE EXCEPTION 'union_retained_invoice_receipt_missing' USING ERRCODE='23514';
  END IF;
 END IF;
 FOR k IN SELECT jsonb_object_keys(v_prior) LOOP
  PERFORM set_config(k,COALESCE(v_prior->>k,''),true);
 END LOOP;
 RETURN NEXT;
END
$$;

CREATE FUNCTION public.fn_union_club_invoice(p_union_id uuid, p_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(club_id uuid, club_name text, period_start timestamp with time zone, period_end timestamp with time zone, rake_generated numeric, union_fee_kept numeric, rakeback_due numeric, players_won numeric, player_pnl_net numeric, eco_amount numeric, eco_enabled boolean, presettled numeric, settled_in_chips numeric, outstanding numeric, net_position numeric, direction text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start timestamptz := COALESCE(p_start, fn_union_week_start());
  v_end   timestamptz := COALESCE(p_end, now());
BEGIN
  RETURN QUERY
  WITH eco AS (
    SELECT e.club_id, e.club_name, e.players_won, e.rake_generated,
           e.rake_earned, e.eco_base, e.eco_amount, e.eco_enabled
      FROM fn_union_eco_adjustment(p_union_id, v_start, v_end) e
  ),
  recorded AS (
    /* THE DOCUMENT QUOTES THE RECORD (2026-09-21). fn_union_eco_adjustment is
       a VOLATILE recomputation of the whole week; fn_union_eco_record wrote
       its answer to union_eco_ledger earlier in this same settlement, and a
       second recomputation is a second answer. On 2026-09-14 that cost club
       a41434bb 1.21 of overstated debt on an invoice whose other three
       figures matched the ledger exactly. Read what was recorded. */
    SELECT l.club_id, l.eco_amount
      FROM union_eco_ledger l
     WHERE l.union_id = p_union_id
       AND l.period_start = v_start
       AND l.period_end   = v_end
  ),
  pre AS (
    -- Unapplied cash held against the running balance. Closed out by
    -- applied_settlement_id, never by age: a payment made during a week that
    -- did not settle must still reach the club's next statement.
    SELECT p.club_id, COALESCE(SUM(p.amount), 0) AS amt
      FROM union_presettlements p
     WHERE p.union_id = p_union_id
       AND p.received_at < v_end
       AND p.applied_settlement_id IS NULL
     GROUP BY p.club_id
  ),
  calc AS (
    /* Phase 6 (20260907): rakeback_due IS round 1's payout for the club - the
       same fn_union_club_rake_basis rows, per game type, truncated to the
       cent - not a flat rate applied to a different rake total. */
    SELECT eco.club_id, eco.club_name,
           eco.rake_generated,
           round(eco.rake_generated - eco.rake_earned, 2) AS union_fee_kept,
           eco.rake_earned                                AS rakeback_due,
           eco.players_won,
           round(eco.players_won + eco.rake_generated, 2) AS player_pnl_net,
           /* The recorded ECO when the settlement has recorded one; the live
              figure only for the read-only preview of a week that has not
              been settled yet, which has no record to quote. */
           CASE WHEN eco.eco_enabled
                  THEN COALESCE(rec.eco_amount, eco.eco_amount)
                ELSE 0 END AS eco_amount,
           eco.eco_enabled,
           COALESCE(pre.amt, 0) AS presettled
      FROM eco
      LEFT JOIN recorded rec ON rec.club_id = eco.club_id
      LEFT JOIN pre          ON pre.club_id = eco.club_id
  )
  SELECT calc.club_id, calc.club_name, v_start, v_end,
         calc.rake_generated, calc.union_fee_kept, calc.rakeback_due,
         calc.players_won, calc.player_pnl_net,
         calc.eco_amount, calc.eco_enabled, calc.presettled,
         round(calc.player_pnl_net + calc.rakeback_due, 2) AS settled_in_chips,
         round(calc.eco_amount + calc.presettled, 2)       AS outstanding,
         round(calc.player_pnl_net + calc.rakeback_due
               + calc.eco_amount + calc.presettled, 2)     AS net_position,
         CASE WHEN round(calc.eco_amount + calc.presettled, 2) > 0
                THEN 'union owes club'
              WHEN round(calc.eco_amount + calc.presettled, 2) < 0
                THEN 'club owes union'
              ELSE 'square' END::text
    FROM calc
   ORDER BY calc.club_name;
END;
$$;

CREATE FUNCTION public.fn_union_club_rake_basis(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_live boolean DEFAULT false) RETURNS TABLE(club_id uuid, game_type text, rake_in numeric, rate numeric, payout numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sref text;
BEGIN
  IF p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL OR p_end <= p_start THEN
    RETURN;
  END IF;

  /* THE WITNESS FIRST. A period that has been closed stored the rows it was
     paid from; a statement for that period describes THAT, never a
     recomputation over attribution tables that may since have moved. */
  v_sref := p_union_id::text || ':'
    || to_char(p_start at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') || '..'
    || to_char(p_end   at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');

  IF EXISTS (SELECT 1 FROM public.ca_settlements s
              WHERE s.settlement_type = 'union_rakeback_close' AND s.union_id = p_union_id
                AND s.state = 'final' AND s.external_ref = v_sref
                AND s.totals ? 'basis_detail') THEN
    RETURN QUERY
      SELECT (d->>'club_id')::uuid, d->>'game_type',
             (d->>'rake_in')::numeric, (d->>'rate')::numeric, (d->>'payout')::numeric
        FROM public.ca_settlements s
        CROSS JOIN LATERAL jsonb_array_elements(s.totals->'basis_detail') d
       WHERE s.settlement_type = 'union_rakeback_close' AND s.union_id = p_union_id
         AND s.state = 'final' AND s.external_ref = v_sref;
    RETURN;
  END IF;

  -- Open/current statements and the close read exactly the same certified
  -- source plan. An old hourly projection cannot replace earning contracts.
  RETURN QUERY SELECT (d->>'club_id')::uuid,d->>'game_type',(d->>'rake_in')::numeric,
    (d->>'rate')::numeric,(d->>'payout')::numeric
   FROM jsonb_array_elements(public.fn_accounting_union_earned_plan(p_union_id,p_start,p_end)->'basis_detail')d;
END;
$$;

CREATE FUNCTION public.fn_union_credit_risk_check() RETURNS TABLE(invariant text, severity text, offenders bigint, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 'union_club_no_terms', 'warning', count(*),
         'Member clubs with no union_club_terms row: no security deposit and '
         || 'no stop loss on file, so their losses are carried unsecured'
    FROM union_clubs uc
   WHERE NOT EXISTS (SELECT 1 FROM union_club_terms t
                      WHERE t.union_id = uc.union_id AND t.club_id = uc.club_id)
  HAVING count(*) > 0

  UNION ALL
  SELECT 'union_club_stop_loss_breached', 'critical', count(*),
         'Clubs past their weekly stop loss and still active: '
         || COALESCE(string_agg(x.club_name || ' (exposure ' || x.exposure || ' vs limit '
                                || x.stop_loss_limit || ')', '; '), '')
    FROM (
      SELECT e.club_name, e.exposure, e.stop_loss_limit
        FROM (SELECT DISTINCT t.union_id
                FROM union_club_terms t
               WHERE t.stop_loss_limit IS NOT NULL
                 AND t.status <> 'suspended') u
        CROSS JOIN LATERAL fn_union_club_exposure(u.union_id) e
       WHERE e.breached AND e.status <> 'suspended'
    ) x
  HAVING count(*) > 0

  UNION ALL
  SELECT 'union_eco_not_recorded', 'warning', count(*),
         'Unions with ECO enabled and no union_eco_ledger row for the settlement '
         || 'week that has CLOSED: that week''s win tax / loss rebate is not reproducible. '
         || 'The ledger is written at close, so the week in progress is not asked about'
    FROM unions un
   WHERE COALESCE((un.settings->>'eco_enabled')::boolean, false)
     AND EXISTS (SELECT 1 FROM union_clubs uc WHERE uc.union_id = un.id)
     AND NOT EXISTS (SELECT 1 FROM union_eco_ledger l
                      WHERE l.union_id = un.id
                        AND l.period_start >= fn_union_week_start() - interval '7 days')
     -- A WEEK'S ECO ROW IS WRITTEN AT ITS CLOSE, SO IT IS ASKED FOR ONCE THE
     -- CLOSE IS OWED (2026-10-05). Before the close's run time
     -- (fn_union_accounting_run_at), while an accounting_close_gates row holds
     -- the first attempt for a quiet hour, and while the close is running, the
     -- row cannot exist yet. On 2026-10-05 this filed two ledger_imbalance
     -- incidents at 07:52 for a close gated until 2026-10-06 13:00 by the
     -- coordinator decision of 2026-10-03. A close that is owed and has not
     -- written the row - past its run time, no gate holding it, nothing
     -- running - is still found, and so is a finished close without one.
     -- Migration 20261005113359.
     AND NOT (now() < fn_union_accounting_run_at(fn_union_week_start())
              OR EXISTS (SELECT 1 FROM accounting_close_gates g
                          WHERE g.scope_kind = 'union' AND g.scope_id = un.id
                            AND g.period_end = fn_union_week_start()
                            AND g.gate_until > now()
                            AND NOT EXISTS (SELECT 1 FROM union_accounting_runs r
                                             WHERE r.scope_kind = 'union' AND r.scope_id = un.id
                                               AND r.period_start = g.period_start
                                               AND r.period_end = g.period_end))
              OR EXISTS (SELECT 1 FROM union_accounting_runs q
                          WHERE q.scope_kind = 'union' AND q.scope_id = un.id
                            AND q.period_end = fn_union_week_start()
                            AND q.status = 'running'))
  HAVING count(*) > 0

  UNION ALL
  SELECT 'union_club_stakes_above_cap', 'warning', count(*),
         'Live tables above the club''s agreed stakes cap: '
         || COALESCE(string_agg(y.club_name || ' bb=' || y.big_blind
                                || ' cap=' || y.stakes_cap_bb, '; '), '')
    FROM (
      SELECT c.name AS club_name, tb.big_blind, t.stakes_cap_bb
        FROM union_club_terms t
        JOIN clubs c ON c.id = t.club_id
        JOIN tables tb ON tb.club_id = t.club_id
       WHERE t.stakes_cap_bb IS NOT NULL
         AND tb.big_blind > t.stakes_cap_bb
         AND COALESCE(tb.is_deleted, false) = false
         AND tb.status NOT IN ('closed','deleted')
    ) y
  HAVING count(*) > 0

  UNION ALL
  SELECT * FROM fn_anon_exposure_check();
$$;

CREATE FUNCTION public.fn_union_eco_adjustment(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS TABLE(club_id uuid, club_name text, players_won numeric, rake_generated numeric, cash_players_won numeric, cash_rake numeric, tournament_rake numeric, total_rake_generated numeric, club_commission_rate numeric, rake_earned numeric, eco_base numeric, eco_rate numeric, eco_amount numeric, direction text, union_net_eco numeric, eco_base_mode text, baseline_cash_exact boolean, include_horses boolean, eco_enabled boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE proof jsonb; terms jsonb;
BEGIN
 -- Preserve the existing disclosure authorization before reading evidence.
 IF auth.uid() IS NOT NULL
  AND NOT EXISTS(SELECT 1 FROM unions u WHERE u.id=p_union_id AND u.owner_id=auth.uid())
  AND NOT EXISTS(SELECT 1 FROM union_admins ua WHERE ua.union_id=p_union_id AND ua.user_id=auth.uid())
  AND NOT EXISTS(SELECT 1 FROM union_clubs uc JOIN club_members cm ON cm.club_id=uc.club_id
   WHERE uc.union_id=p_union_id AND cm.user_id=auth.uid() AND cm.role IN('owner','co_owner','admin','super_agent')) THEN
  RAISE EXCEPTION 'not authorized to read union reconciliation' USING ERRCODE='42501'; END IF;
 proof:=public.fn_union_pnl_qualified_clubs(p_union_id,p_start,p_end);
 terms:=proof#>'{eco_commercial_terms_evidence,segments,0,terms}';
 RETURN QUERY WITH rows AS(
  SELECT x,(x->>'club_id')::uuid id,(x->>'eco_amount')::numeric eco FROM jsonb_array_elements(proof->'clubs') x
 ), total AS(SELECT COALESCE(sum(-eco),0) amount FROM rows)
 SELECT r.id,c.name::text,(x->>'realized_net')::numeric+(x->>'stack_delta')::numeric,(x->>'rake_paid')::numeric,
  (x->>'cash_player_pnl')::numeric,(x->>'cash_rake')::numeric,(x->>'tournament_rake')::numeric,(x->>'rake_paid')::numeric,
  CASE WHEN (x->>'rake_paid')::numeric>0 THEN (x->>'rake_earned')::numeric/(x->>'rake_paid')::numeric ELSE NULL END,
  (x->>'rake_earned')::numeric,(x->>'eco_base')::numeric,(terms->>'eco_rate')::numeric,r.eco,
  CASE WHEN r.eco<0 THEN 'club pays union (profitable week)' WHEN r.eco>0 THEN 'union pays club (losing week)' ELSE 'square' END,
  total.amount,terms->>'eco_base_mode',true,true,(terms->>'eco_enabled')::boolean
 FROM rows r LEFT JOIN clubs c ON c.id=r.id CROSS JOIN total ORDER BY r.eco;
END $$;

CREATE FUNCTION public.fn_union_eco_record(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_settlement_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_rows int;
  v_mode text;
BEGIN
  IF v_caller IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM unions u WHERE u.id = p_union_id AND u.owner_id = v_caller)
     AND NOT EXISTS (SELECT 1 FROM union_admins ua
                      WHERE ua.union_id = p_union_id AND ua.user_id = v_caller) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authorized');
  END IF;

  -- Preserve original authorization; refuse before any existing ECO row can be upserted.
  PERFORM public.fn_require_union_pnl_evidence(p_union_id,p_start,p_end);

  SELECT x.eco_base_mode INTO v_mode FROM public.fn_union_eco_adjustment(p_union_id,p_start,p_end) x LIMIT 1;
  INSERT INTO union_eco_ledger (union_id, club_id, period_start, period_end,
                                eco_base, eco_rate, eco_amount, eco_base_mode,
                                cash_players_won, total_rake_generated,
                                rake_earned, club_commission_rate, include_horses,
                                settlement_id)
  SELECT p_union_id, e.club_id, p_start, p_end, e.eco_base, e.eco_rate,
         e.eco_amount, e.eco_base_mode, e.cash_players_won, e.total_rake_generated,
         e.rake_earned, e.club_commission_rate, e.include_horses, p_settlement_id
    FROM fn_union_eco_adjustment(p_union_id, p_start, p_end) e
  ON CONFLICT (union_id, club_id, period_start) DO UPDATE
    SET period_end            = EXCLUDED.period_end,
        eco_base              = EXCLUDED.eco_base,
        eco_rate              = EXCLUDED.eco_rate,
        eco_amount            = EXCLUDED.eco_amount,
        eco_base_mode         = EXCLUDED.eco_base_mode,
        cash_players_won      = EXCLUDED.cash_players_won,
        total_rake_generated  = EXCLUDED.total_rake_generated,
        rake_earned           = EXCLUDED.rake_earned,
        club_commission_rate  = EXCLUDED.club_commission_rate,
        include_horses        = EXCLUDED.include_horses,
        settlement_id         = COALESCE(EXCLUDED.settlement_id, union_eco_ledger.settlement_id),
        computed_at           = now();
  GET DIAGNOSTICS v_rows = ROW_COUNT;

  RETURN jsonb_build_object('success', true, 'clubs', v_rows, 'eco_base_mode', v_mode,
                            'period_start', p_start, 'period_end', p_end);
END;
$$;

CREATE FUNCTION public.fn_union_eco_terms_evidence(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE first_at timestamptz; r record; previous_terms jsonb; seen boolean:=false;
 terms jsonb; rate numeric; issue text; issues jsonb:='[]'; segments jsonb:='[]';
BEGIN
 IF p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end)
  OR p_end<=p_start OR p_end>statement_timestamp() OR p_end-p_start>interval '8 days' THEN
  RETURN jsonb_build_object('status','blocked','issues',jsonb_build_array('invalid_closed_eco_terms_period'));
 END IF;
 SELECT max(observed_at) INTO first_at FROM public.accounting_agreement_history
  WHERE entity_type='unions' AND union_id=p_union_id AND observed_at<=p_start;
 IF first_at IS NULL THEN
  RETURN jsonb_build_object('status','blocked','issues',jsonb_build_array('eco_terms_opening_coverage_missing'));
 END IF;
 FOR r IN
  SELECT h.*,lead(h.observed_at,1,p_end) OVER(ORDER BY h.observed_at,h.id) AS next_at,
   count(*) OVER(PARTITION BY h.observed_at) AS same_time
  FROM public.accounting_agreement_history h
  WHERE h.entity_type='unions' AND h.union_id=p_union_id AND h.observed_at>=first_at AND h.observed_at<p_end
  ORDER BY h.observed_at,h.id
 LOOP
  terms:=r.after_terms; issue:=NULL;
  IF r.same_time<>1 OR NOT isfinite(r.observed_at) THEN issue:='eco_terms_ambiguous_observation';
  ELSIF r.event_type='baseline' AND NOT EXISTS(SELECT 1 FROM public.union_pnl_eco_observations o
   WHERE o.agreement_id=r.id AND o.union_id=r.union_id AND o.observed_from=r.observed_at AND o.observed_from<=p_start)
   THEN issue:='eco_terms_observation_is_not_original_write';
  ELSIF seen AND r.before_terms IS DISTINCT FROM previous_terms THEN issue:='eco_terms_history_discontinuity';
  ELSIF r.event_type='DELETE' OR terms IS NULL THEN issue:='eco_terms_deleted_during_period';
  ELSIF jsonb_typeof(terms) IS DISTINCT FROM 'object'
    OR NOT terms ?& ARRAY['eco_enabled','eco_base_mode','eco_rate','eco_include_horses'] THEN
   issue:='eco_terms_explicit_configuration_missing';
  ELSIF jsonb_typeof(terms->'eco_enabled') IS DISTINCT FROM 'boolean'
    OR jsonb_typeof(terms->'eco_include_horses') IS DISTINCT FROM 'boolean'
    OR jsonb_typeof(terms->'eco_base_mode') IS DISTINCT FROM 'string'
    OR jsonb_typeof(terms->'eco_rate') IS DISTINCT FROM 'number' THEN issue:='eco_terms_invalid_types';
  ELSIF terms->>'eco_base_mode' NOT IN('club_cash_profit','net_invoice_position','winnings_plus_rake','winnings_only') THEN
   issue:='eco_terms_unsupported_mode';
  ELSIF terms->'eco_include_horses' IS DISTINCT FROM 'true'::jsonb THEN
   issue:='eco_terms_excludes_horses';
  ELSE
   rate:=(terms->>'eco_rate')::numeric;
   IF rate::text IN('NaN','Infinity','-Infinity') OR rate<0 OR rate>1 THEN issue:='eco_terms_invalid_rate'; END IF;
  END IF;
  IF issue IS NOT NULL THEN
   issues:=issues||jsonb_build_array(jsonb_build_object('reason',issue,'agreement_id',r.id));
  END IF;
  segments:=segments||jsonb_build_array(jsonb_build_object('agreement_id',r.id,'observed_at',r.observed_at,
   'from',greatest(p_start,r.observed_at),'to',r.next_at,'terms',terms));
  seen:=true; previous_terms:=terms;
 END LOOP;
 RETURN jsonb_build_object('status',CASE WHEN seen AND issues='[]'::jsonb THEN 'ready' ELSE 'blocked' END,
  'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',issues,'segments',segments,
  'scope','observed_commercial_terms_only','payment_authorized',false);
END $$;

CREATE FUNCTION public.fn_union_governance_check() RETURNS TABLE(invariant text, severity text, offenders bigint, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 'club_owned_cash_table_in_union', 'critical', count(*),
         'Open cash tables under a union club with no union_id and not private'
    FROM tables t JOIN union_clubs uc ON uc.club_id = t.club_id
   WHERE t.union_id IS NULL AND COALESCE(t.is_private,false) = false
     AND t.tournament_id IS NULL AND COALESCE(t.is_deleted,false) = false
     AND t.status NOT IN ('closed','deleted')
  HAVING count(*) > 0

  UNION ALL
  SELECT 'club_owned_tournament_in_union', 'critical', count(*),
         'Live non-private tournaments under a union club with no union_id'
    FROM tournaments t JOIN union_clubs uc ON uc.club_id = t.club_id
   WHERE t.union_id IS NULL AND COALESCE(t.is_private,false) = false
     AND t.status IN ('ANNOUNCED','SCHEDULED','REGISTERING','LATE_REG','RUNNING')
  HAVING count(*) > 0

  UNION ALL
  SELECT 'union_game_not_owned_by_union', 'critical', count(*),
         'Live union games whose club_id names a member club instead of the union '
         || '(cash/MTT/SNG/Spin)'
    FROM (
      SELECT id FROM tables
       WHERE union_id IS NOT NULL AND COALESCE(is_private,false) = false
         AND club_id IS DISTINCT FROM union_id
         AND COALESCE(is_deleted,false) = false AND status NOT IN ('closed','deleted')
      UNION ALL
      SELECT id FROM tournaments
       WHERE union_id IS NOT NULL AND COALESCE(is_private,false) = false
         AND club_id IS DISTINCT FROM union_id
         AND status IN ('ANNOUNCED','SCHEDULED','REGISTERING','LATE_REG','RUNNING')
    ) x
  HAVING count(*) > 0

  UNION ALL
  SELECT 'union_lost_a_member_club', 'critical', count(*),
         'Clubs expected in Midway Union that are no longer members'
    FROM (
      SELECT c.id FROM clubs c
       WHERE c.id IN ('a0000000-0000-0000-0000-000000000001',
                      'a41434bb-8d0c-400a-8f0d-e8b3d65afed4')
         AND NOT EXISTS (SELECT 1 FROM union_clubs uc
                          WHERE uc.club_id = c.id
                            AND uc.union_id = 'fade0000-0000-0000-0000-000000000001')
    ) m
  HAVING count(*) > 0

  UNION ALL
  SELECT 'clubs_union_id_mirror_drift', 'critical', count(*),
         'clubs.union_id disagrees with union_clubs'
    FROM union_clubs uc JOIN clubs c ON c.id = uc.club_id
   WHERE c.union_id IS DISTINCT FROM uc.union_id
  HAVING count(*) > 0

  UNION ALL
  SELECT 'private_game_union_visible', 'critical', count(*),
         'Rows flagged private that still carry a union_id'
    FROM (
      SELECT id FROM tables WHERE COALESCE(is_private,false) AND union_id IS NOT NULL
      UNION ALL
      SELECT id FROM tournaments WHERE COALESCE(is_private,false) AND union_id IS NOT NULL
    ) x
  HAVING count(*) > 0

  UNION ALL
  SELECT 'ownership_triggers_missing', 'critical', 5 - count(*),
         'Expected 5 union ownership/mirror triggers'
    FROM pg_trigger
   WHERE tgname IN ('trg_tables_union_ownership','trg_tournaments_union_ownership',
                    'trg_union_clubs_sync_mirror','trg_tables_union_ownership_upd',
                    'trg_tournaments_union_ownership_upd')
  HAVING count(*) < 5

  UNION ALL
  SELECT 'tables_rls_not_private_aware', 'critical', 1,
         'tables SELECT policy no longer considers is_private'
   WHERE NOT EXISTS (
     SELECT 1 FROM pg_policy
      WHERE polrelid = 'public.tables'::regclass AND polcmd = 'r'
        AND pg_get_expr(polqual, polrelid) LIKE '%is_private%')

  UNION ALL
  SELECT 'union_clubs_unreadable_by_members', 'critical', 1,
         'A club member can no longer discover their own union (union_clubs RLS)'
   WHERE NOT EXISTS (
     SELECT 1 FROM pg_policy
      WHERE polrelid = 'public.union_clubs'::regclass AND polcmd = 'r'
        AND pg_get_expr(polqual, polrelid) LIKE '%club_members%')

  UNION ALL
  SELECT 'union_rake_wallet_stale', 'warning', count(*),
         'Union rake wallets holding a balance with no rakeback in 14 days'
    FROM union_wallets uw
   WHERE uw.rake_wallet > 0
     AND NOT EXISTS (
       SELECT 1 FROM union_wallet_transactions t
        WHERE t.union_id = uw.union_id AND t.wallet = 'rake_wallet'
          AND t.direction = 'debit' AND t.created_at > now() - interval '14 days')
  HAVING count(*) > 0

  UNION ALL
  SELECT 'settlement_needs_review', 'warning', count(*),
         'Player P&L periods parked for review and never re-settled'
    FROM union_pnl_settlements WHERE status = 'needs_review'
  HAVING count(*) > 0

  UNION ALL
  SELECT 'settlement_period_overdue_open', 'warning', count(*),
         'settlement_periods still open/processing more than 24h past end_at'
    FROM settlement_periods
   WHERE status IN ('open','processing') AND end_at < now() - interval '24 hours'
  HAVING count(*) > 0

  UNION ALL
  SELECT 'settlement_period_orphan', 'critical', count(*),
         'settlement_periods with NULL club_id AND NULL union_id'
    FROM settlement_periods
   WHERE club_id IS NULL AND union_id IS NULL
  HAVING count(*) > 0

  UNION ALL
  -- 2026-08-20: the rake rollup is a speed cache only (a stale day is
  -- recomputed live), so this is a WARNING, not a correctness alarm: it means
  -- the settlement will do that work inline while holding treasury locks.
  SELECT 'union_rake_rollup_unmaintained', 'warning', count(*),
         'Unions with 3+ missing rake rollup days in the last week - the '
         || 'weekly settlement would recompute them while holding treasury locks'
    FROM (
      SELECT un.id,
             (SELECT count(*)
                FROM generate_series((now() AT TIME ZONE 'UTC')::date - 7,
                                     (now() AT TIME ZONE 'UTC')::date - 1,
                                     interval '1 day') gs
               WHERE NOT EXISTS (SELECT 1 FROM union_rake_rollup_days rd
                                  WHERE rd.union_id = un.id
                                    AND rd.day = gs::date)) AS stale_days
        FROM unions un
       WHERE EXISTS (SELECT 1 FROM union_clubs uc WHERE uc.union_id = un.id)
    ) s
   WHERE s.stale_days >= 3
  HAVING count(*) > 0

  UNION ALL
  SELECT * FROM fn_union_credit_risk_check()
$$;

CREATE FUNCTION public.fn_union_issue_weekly_invoices(p_union_id uuid, p_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end timestamp with time zone DEFAULT NULL::timestamp with time zone, p_notify boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_from timestamptz := COALESCE(p_start, public.fn_union_prev_week_start(now()));
  v_to   timestamptz := COALESCE(p_end,   public.fn_union_week_start(now()));
  v_due  timestamptz;
  v_union_name text;
  r record;
  v_period_id uuid;
  v_invoice_id uuid;
  v_already_sent boolean;
  v_issued int := 0;
  v_notified int := 0;
  v_notified_batch int := 0;
  v_messaged int := 0;
  v_basis_exact boolean;
  v_msg jsonb;
  v_body text;
  v_number text;
  v_out jsonb := '[]'::jsonb;
  v_recorded_eco numeric;
  v_eco_recorded boolean;
  v_recorded_base numeric;
  v_recorded_rate numeric;
BEGIN
  IF v_caller IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM unions u WHERE u.id = p_union_id AND u.owner_id = v_caller)
     AND NOT EXISTS (SELECT 1 FROM union_admins ua
                      WHERE ua.union_id = p_union_id AND ua.user_id = v_caller) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authorized');
  END IF;

  -- Original owner/admin authorization above remains the first disclosure gate.
  PERFORM public.fn_require_union_pnl_evidence(p_union_id,v_from,v_to);

  /* THE GUARDS LIVE HERE, NOT ONLY IN THE CASCADE (Phase 6 verification,
     20260908). The Open Claw safety net calls this function directly. */
  IF EXISTS (SELECT 1 FROM public.union_settlement_floor f
              WHERE f.union_id = p_union_id AND v_from < f.earliest_period_start) THEN
    RETURN jsonb_build_object('success', false, 'error', 'before_settlement_floor',
                              'period_start', v_from, 'period_end', v_to);
  END IF;
  IF public.fn_union_setting(p_union_id, 'weekly_invoices_enabled', 1) <> 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'weekly_invoices_disabled',
                              'period_start', v_from, 'period_end', v_to);
  END IF;
  -- A statement says "rakeback already moved in chips". It is issued only for a
  -- period whose round 1 is final, and then it reads that round's own rows.
  IF NOT EXISTS (SELECT 1 FROM public.ca_settlements s
                  WHERE s.settlement_type = 'union_rakeback_close' AND s.union_id = p_union_id
                    AND s.state = 'final'
                    AND s.external_ref = p_union_id::text || ':'
                      || to_char(v_from at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') || '..'
                      || to_char(v_to   at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')) THEN
    RETURN jsonb_build_object('success', false, 'error', 'period_not_closed',
                              'period_start', v_from, 'period_end', v_to);
  END IF;

  v_due := v_to + interval '3 days';
  SELECT u.name INTO v_union_name FROM unions u WHERE u.id = p_union_id;

  -- Is the seated-stack baseline this week's ECO rests on an exact one?
  SELECT bool_and(COALESCE(e.baseline_cash_exact, false))
    INTO v_basis_exact
    FROM fn_union_eco_adjustment(p_union_id, v_from, v_to) e;
  v_basis_exact := COALESCE(v_basis_exact, false);

  FOR r IN SELECT * FROM fn_union_club_invoice(p_union_id, v_from, v_to) LOOP
    v_msg := NULL;
    v_invoice_id := NULL;
    v_already_sent := false;

    /* THE DOCUMENT QUOTES THE RECORDED ECO (2026-09-21). union_eco_ledger
       is the recorded ECO for this period; fn_union_eco_record wrote it
       earlier in this settlement. fn_union_club_invoice now reads it, so
       this refusal should never fire - it exists because a square-up that
       cannot quote its own record must STOP, not state a number. On
       2026-09-14 a second live recomputation billed club a41434bb 11244.03
       against a recorded -11242.82. With ECO terms disabled nothing is
       recorded and nothing may be stated. */
    SELECT l.eco_amount, l.eco_base, l.eco_rate
      INTO v_recorded_eco, v_recorded_base, v_recorded_rate
      FROM union_eco_ledger l
     WHERE l.union_id = p_union_id AND l.club_id = r.club_id
       AND l.period_start = v_from AND l.period_end = v_to;
    v_eco_recorded := FOUND;
    IF r.eco_enabled AND NOT v_eco_recorded THEN
      RAISE EXCEPTION 'union_squareup_eco_not_recorded' USING ERRCODE = '23514',
        DETAIL = jsonb_build_object('union_id', p_union_id, 'club_id', r.club_id,
          'period_start', v_from, 'period_end', v_to, 'stated_eco', r.eco_amount)::text;
    END IF;
    /* THE RECORD ANSWERS FOR ITS OWN ARITHMETIC (2026-09-25). The
       comparison below it - the document against union_eco_ledger - is
       the record against itself since 20260921040847 taught
       fn_union_club_invoice to RETURN the recorded amount, and a
       rehearsal proved it silent while a recorded value was mutated by
       0.01. The independent basis is IN the record: eco_base, eco_rate
       and eco_amount are stored side by side, all NOT NULL, and the
       producer defines the amount as round(-eco_rate*eco_base,2)
       (fn_union_pnl_evidence_report). Three stored numerics, no
       recomputation of the week, no second snapshot - so this can fire
       without resurrecting the 2026-09-14 overstatement that a second
       VOLATILE recomputation caused. The two arms below it are kept and
       are not weakened: the ECO-disabled arm is the one arm of the old
       comparison that could always fire. */
    IF r.eco_enabled AND v_eco_recorded
       AND (v_recorded_base IS NULL OR v_recorded_rate IS NULL
            OR round(-v_recorded_rate * v_recorded_base, 2)
               IS DISTINCT FROM round(COALESCE(v_recorded_eco, 0), 2)) THEN
      RAISE EXCEPTION 'union_squareup_eco_record_fails_its_own_arithmetic' USING ERRCODE = '23514',
        DETAIL = jsonb_build_object('union_id', p_union_id, 'club_id', r.club_id,
          'period_start', v_from, 'period_end', v_to,
          'recorded_eco', v_recorded_eco, 'recorded_base', v_recorded_base,
          'recorded_rate', v_recorded_rate,
          'base_times_rate', round(-v_recorded_rate * v_recorded_base, 2))::text,
        HINT = 'union_eco_ledger.eco_amount must equal round(-eco_rate*eco_base,2). A record that does not support its own figure cannot be invoiced.';
    END IF;
    IF round(COALESCE(r.eco_amount, 0), 2)
       IS DISTINCT FROM round(COALESCE(v_recorded_eco, 0), 2) THEN
      RAISE EXCEPTION 'union_squareup_eco_disagrees_with_record' USING ERRCODE = '23514',
        DETAIL = jsonb_build_object('union_id', p_union_id, 'club_id', r.club_id,
          'period_start', v_from, 'period_end', v_to,
          'stated_eco', r.eco_amount, 'recorded_eco', v_recorded_eco)::text;
    END IF;
    IF NOT r.eco_enabled AND round(COALESCE(v_recorded_eco, 0), 2) <> 0 THEN
      RAISE EXCEPTION 'union_squareup_eco_disagrees_with_record' USING ERRCODE = '23514',
        DETAIL = jsonb_build_object('union_id', p_union_id, 'club_id', r.club_id,
          'period_start', v_from, 'period_end', v_to,
          'stated_eco', r.eco_amount, 'recorded_eco', v_recorded_eco,
          'eco_enabled', false)::text;
    END IF;

    SELECT sp.id INTO v_period_id
      FROM settlement_periods sp
     WHERE sp.club_id = r.club_id AND sp.union_id = p_union_id
       AND sp.start_at = v_from AND sp.end_at = v_to
     ORDER BY sp.created_at DESC LIMIT 1;

    IF v_period_id IS NULL THEN
      INSERT INTO settlement_periods (club_id, union_id, period_number, year,
                                      start_at, end_at, status)
      VALUES (r.club_id, p_union_id,
              EXTRACT(week FROM v_from)::int, EXTRACT(isoyear FROM v_from)::int,
              v_from, v_to, 'processing')
      RETURNING id INTO v_period_id;
    END IF;

    -- Reuse the number this document already carries. Take a new one ONLY
    -- when there is no document yet: the upsert below may take the ON
    -- CONFLICT path, and a number taken and not used is a gap in the series.
    SELECT si.invoice_number INTO v_number
      FROM settlement_invoices si
     WHERE si.club_id = r.club_id AND si.period_id = v_period_id
       AND si.invoice_type = 'union_weekly_squareup';
    IF NOT FOUND THEN
      v_number := public.fn_next_invoice_number(p_union_id, now());
    END IF;

    INSERT INTO settlement_invoices (
      club_id, period_id, invoice_type, invoice_number,
      from_entity_type, from_entity_id, to_entity_type, to_entity_id,
      gross_amount, net_amount, deductions, breakdown, status,
      chips_transferred, due_at, notes)
    VALUES (
      r.club_id, v_period_id, 'union_weekly_squareup', v_number,
      CASE WHEN r.outstanding >= 0 THEN 'union' ELSE 'club' END,
      CASE WHEN r.outstanding >= 0 THEN p_union_id::text ELSE r.club_id::text END,
      CASE WHEN r.outstanding >= 0 THEN 'club'  ELSE 'union' END,
      CASE WHEN r.outstanding >= 0 THEN r.club_id::text ELSE p_union_id::text END,
      abs(r.outstanding), abs(r.outstanding), 0,
      jsonb_build_object(
        'union_id', p_union_id, 'union_name', v_union_name,
        'club_id', r.club_id, 'club_name', r.club_name,
        'period_start', r.period_start, 'period_end', r.period_end,
        'rake_generated', r.rake_generated,
        'union_fee_kept', r.union_fee_kept,
        'rakeback_due',   r.rakeback_due,
        'players_won',    r.players_won,
        'player_pnl_net', r.player_pnl_net,
        'eco_amount',     r.eco_amount,
        'eco_enabled',    r.eco_enabled,
        'presettled',     r.presettled,
        'settled_in_chips', r.settled_in_chips,
        'outstanding',    r.outstanding,
        'net_position',   r.net_position,
        'direction',      r.direction,
        'baseline_cash_exact', v_basis_exact,
        'computed_at',    now()),
      'generated', false, v_due,
      'Weekly union square-up. settled_in_chips already moved during the week; '
      || 'outstanding is the amount to settle.')
    ON CONFLICT (club_id, period_id, invoice_type)
      WHERE invoice_type = 'union_weekly_squareup'
    DO UPDATE SET
      from_entity_type = EXCLUDED.from_entity_type,
      from_entity_id   = EXCLUDED.from_entity_id,
      to_entity_type   = EXCLUDED.to_entity_type,
      to_entity_id     = EXCLUDED.to_entity_id,
      gross_amount     = EXCLUDED.gross_amount,
      net_amount       = EXCLUDED.net_amount,
      invoice_number   = COALESCE(settlement_invoices.invoice_number, EXCLUDED.invoice_number),
      breakdown        = EXCLUDED.breakdown,
      due_at           = EXCLUDED.due_at,
      updated_at       = now()
    WHERE COALESCE(settlement_invoices.message_sent, false) = false
    RETURNING id, COALESCE(message_sent, false) INTO v_invoice_id, v_already_sent;

    -- The upsert returns nothing when the guard above refused to restate an
    -- already-delivered invoice. That row is the record; read it as it stands.
    IF v_invoice_id IS NULL THEN
      SELECT si.id, COALESCE(si.message_sent, false)
        INTO v_invoice_id, v_already_sent
        FROM settlement_invoices si
       WHERE si.club_id = r.club_id
         AND si.period_id = v_period_id
         AND si.invoice_type = 'union_weekly_squareup';
    END IF;

    v_issued := v_issued + 1;

    -- Delivery is mandatory and shared with every accounting invoice.
    v_msg := public.fn_deliver_accounting_invoice(v_invoice_id);
    v_notified := v_notified + CASE WHEN v_already_sent THEN (v_msg->>'new_deliveries')::int ELSE (v_msg->>'delivered')::int END;
    v_messaged := v_messaged + CASE WHEN v_already_sent THEN (v_msg->>'new_deliveries')::int ELSE (v_msg->>'delivered')::int END;

    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'club_id', r.club_id, 'club_name', r.club_name,
      'invoice_id', v_invoice_id, 'outstanding', r.outstanding,
      'direction', r.direction, 'due_at', v_due,
      'messaged', COALESCE((v_msg->>'delivered')::int, 0),
      'already_sent', v_already_sent));
  END LOOP;

  RETURN jsonb_build_object('success', true, 'union_id', p_union_id,
    'period_start', v_from, 'period_end', v_to, 'due_at', v_due,
    'baseline_cash_exact', v_basis_exact,
    'invoices', v_issued, 'notified', v_notified, 'messenger_deliveries', v_messaged,
    'detail', v_out);
END;
$$;

CREATE FUNCTION public.fn_union_overseer_of_record(p_union_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_union_id IS NOT NULL AND p_user_id IS NOT NULL AND (
       EXISTS (SELECT 1 FROM public.unions u WHERE u.id = p_union_id AND u.owner_id = p_user_id)
    OR EXISTS (SELECT 1 FROM public.union_admins a WHERE a.union_id = p_union_id AND a.user_id = p_user_id)
    OR EXISTS (SELECT 1 FROM public.clubs c
                WHERE c.id = p_union_id AND COALESCE(c.is_union, false) AND c.owner_id = p_user_id)
    OR EXISTS (SELECT 1 FROM public.club_members m
                WHERE m.club_id = p_union_id AND m.user_id = p_user_id
                  AND m.role IN ('owner','co_owner','admin')
                  AND m.status IN ('active','approved'))
  );
$$;

CREATE FUNCTION public.fn_union_pnl_award_owner_resolved(c public.tournament_accounting_credit_receipts, p_union_id uuid, p_start timestamp with time zone, p_resolved uuid[]) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT COALESCE(cardinality(c.entry_receipt_ids),0)=0 AND c.asset='chips' AND c.amount>0 AND c.registration_snapshot->>'id' IS NOT NULL
  AND (SELECT count(*) FROM public.union_pnl_opening_registration_resolutions r
       WHERE r.boundary=p_start AND r.union_id=p_union_id AND r.tournament_id=c.tournament_id AND r.user_id=c.user_id)=1
  AND EXISTS(SELECT 1 FROM public.union_pnl_opening_registration_resolutions r
   JOIN public.chip_ledger l ON l.id=c.ledger_id
   WHERE r.boundary=p_start AND r.union_id=p_union_id AND r.tournament_id=c.tournament_id AND r.user_id=c.user_id
    AND r.registration_id=ANY(p_resolved) AND r.registration_id::text=c.registration_snapshot->>'id'
    AND r.proof_md5=md5(r.proof::text) AND r.owning_club_id=c.credited_club_id
    AND l.status='posted' AND l.category IN ('tournament_prize','bounty') AND l.tournament_id=c.tournament_id
    AND l.from_type='prize_liability' AND l.from_entity_id=c.tournament_id
    AND l.to_type='player_wallet' AND l.to_entity_id=c.user_id
    AND l.amount=c.amount AND l.club_id=c.credited_club_id AND l.row_hash IS NOT NULL)
$$;

CREATE FUNCTION public.fn_union_pnl_award_satellite_owner(c public.tournament_accounting_credit_receipts) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT COALESCE(cardinality(c.entry_receipt_ids),0)=0 AND c.asset='chips' AND c.amount>0 AND c.registration_snapshot->>'id' IS NOT NULL
  AND (SELECT e.after_row->>'user_id' FROM public.union_pnl_inventory_events e WHERE e.source_name='tournament_players'
    AND e.row_id=(c.registration_snapshot->>'id')::uuid ORDER BY e.event_id LIMIT 1)=c.user_id::text
  AND public.fn_union_pnl_satellite_seat_owner((c.registration_snapshot->>'id')::uuid,c.tournament_id) IS NOT NULL
  AND c.credited_club_id = (SELECT l.club_id FROM public.chip_ledger l 
    WHERE l.status='posted' AND l.to_type='prize_liability' AND l.to_entity_id=c.tournament_id
      AND l.metadata->>'registration_id' = c.registration_snapshot->>'id'
      AND ((l.category='tournament_buyin' AND l.from_type='prize_liability' AND l.metadata->>'kind'='satellite_seat_pool_transfer')
        OR (l.category='ticket_redeem' AND l.from_type='escrow' AND l.metadata->>'kind'='tournament_entry_ticket_admission'))
    ORDER BY l.created_at LIMIT 1)
  AND EXISTS(SELECT 1 FROM public.chip_ledger l WHERE l.id=c.ledger_id AND l.status='posted' AND l.category IN ('tournament_prize','bounty')
   AND l.tournament_id=c.tournament_id AND l.from_type='prize_liability' AND l.from_entity_id=c.tournament_id
   AND l.to_type='player_wallet' AND l.to_entity_id=c.user_id AND l.amount=c.amount AND l.club_id=c.credited_club_id AND l.row_hash IS NOT NULL)
$$;

CREATE FUNCTION public.fn_union_pnl_boundary(p_union_id uuid, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE inv jsonb; holdings jsonb:='[]'; issues jsonb:='[]'; s jsonb; t jsonb; f record; tr record;
 lineage jsonb; owned uuid; owners int; initial int; value numeric; entries int; first_op text;
 nonchips boolean; changed boolean; returned numeric; res_club uuid; res_amount numeric; v_proj boolean;
 seat_rows int; seat_value numeric; seat_club uuid; seat_credits int;
BEGIN
 inv:=public.fn_union_pnl_inventory_as_of(p_at);
 IF inv->>'status' IS DISTINCT FROM 'observed' THEN RETURN jsonb_build_object('status','blocked','inventory',inv,'holdings',holdings); END IF;
 FOR s IN SELECT x->'row' FROM jsonb_array_elements(COALESCE(inv#>'{population,table_seats}','[]')) x
  WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(inv#>'{population,tables}','[]')) y
   WHERE y#>>'{row,id}'=x#>>'{row,table_id}' AND y#>>'{row,union_id}'=p_union_id::text) LOOP
  lineage:=public.fn_cash_original_funding_lineage((s->>'user_id')::uuid,(s->>'table_id')::uuid,
   (s->>'id')::uuid,(s->>'occupancy_id')::uuid,(s->>'joined_at')::timestamptz,p_at,true);
  SELECT count(*) FILTER(WHERE r.operation_kind='buyin'),count(DISTINCT (r.funding_club_id,r.funding_union_id,r.asset)),min(r.funding_club_id::text)::uuid
   INTO initial,owners,owned FROM jsonb_array_elements(lineage->'funding_receipts') ref
   JOIN public.cash_participant_funding_receipts r ON r.id=(ref->>'id')::uuid;
  value:=public.fn_pnl_evidence_cents(s->'stack');
  IF lineage->'issues'<>'[]'::jsonb OR initial<>1 OR owners<>1 OR owned IS NULL OR value IS NULL OR value<0 THEN
   issues:=issues||jsonb_build_array(jsonb_build_object('reason','cash_boundary_original_funding_missing_or_ambiguous','seat_id',s->'id'));
  ELSE
   holdings:=holdings||jsonb_build_array(jsonb_build_object('club_id',owned,'user_id',s->'user_id','amount',value,'kind','cash_stack','source_id',s->'id'));
  END IF;
 END LOOP;
 -- Money awaiting the original add-on application is still held for its
 -- original funding account. It must not appear as a poker loss at midnight.
 FOR f IN
  SELECT r.*,r.amount-CASE WHEN COALESCE(af.observed_at,a.applied_at)<p_at THEN a.applied+a.refunded ELSE 0 END AS held
  FROM public.cash_participant_funding_receipts r
  LEFT JOIN public.cash_funding_application_receipts a ON a.funding_receipt_id=r.id
  LEFT JOIN public.union_pnl_transaction_frames rf ON rf.transaction_id=r.transaction_id
  LEFT JOIN public.union_pnl_transaction_frames af ON af.transaction_id=a.transaction_id
  WHERE r.pending_addon_id IS NOT NULL AND COALESCE(rf.observed_at,r.recorded_at)<p_at
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(inv#>'{population,tables}','[]')) y
    WHERE y#>>'{row,id}'=r.table_id::text AND y#>>'{row,union_id}'=p_union_id::text)
 LOOP
  IF f.held<0 OR f.funding_club_id IS NULL THEN
   issues:=issues||jsonb_build_array(jsonb_build_object('reason','pending_funding_boundary_invalid','source_id',f.id));
  ELSIF f.held>0 THEN
   holdings:=holdings||jsonb_build_array(jsonb_build_object('club_id',f.funding_club_id,'user_id',f.user_id,'amount',f.held,'kind','pending_cash_funding','source_id',f.id));
  END IF;
 END LOOP;
 -- Preserve the established realized-settlement rule: original gross entry
 -- less money already returned is deferred while a tournament remains open.
 -- This is not market value, ICM, or a new allocation of the prize pool.
 -- First inventory operations come from union_pnl_inventory_touches once its
 -- backfill is complete (20260929044303), else from the wide events.
 v_proj:=public.fn_union_pnl_projection_ready('inventory_touches');
 FOR t IN SELECT x->'row' FROM jsonb_array_elements(COALESCE(inv#>'{population,tournaments}','[]')) x
  WHERE x#>>'{row,union_id}'=p_union_id::text LOOP
  first_op:=public.fn_union_pnl_first_inventory_operation('tournaments',(t->>'id')::uuid,v_proj);
  -- A tournament captured as the baseline (it existed before the original
  -- inventory capture) is read only when every registration of its original
  -- population carries a valid opening resolution for this boundary
  -- (union_pnl_opening_registration_resolutions: its entry re-proved from the
  -- posted chip ledger, bound to these exact population rows). Otherwise it is
  -- refused exactly as before.
  IF first_op IS DISTINCT FROM 'INSERT' AND (first_op IS DISTINCT FROM 'baseline' OR EXISTS(
    SELECT 1 FROM jsonb_array_elements(COALESCE(inv#>'{population,tournament_players}','[]')) y(x)
    WHERE y.x#>>'{row,tournament_id}'=t->>'id'
     AND public.fn_union_pnl_first_inventory_operation('tournament_players',(y.x#>>'{row,id}')::uuid,v_proj) IS DISTINCT FROM 'INSERT'
     AND NOT EXISTS(SELECT 1 FROM public.fn_union_pnl_opening_registration_resolution(p_union_id,p_at,t,y.x->'row')))) THEN
   issues:=issues||jsonb_build_array(jsonb_build_object('reason','open_tournament_precedes_original_population','tournament_id',t->'id')); CONTINUE;
  END IF;
  -- One set-based read per open tournament (it was four queries per seat,
  -- two of them full scans of every tournament credit): the same original
  -- entry, instrument, owner-change and returned-credit facts, per
  -- registration, in the population's order.
  FOR s,entries,owners,owned,value,nonchips,changed,returned,res_club,res_amount IN
   WITH players AS MATERIALIZED (
    SELECT y.x->'row' s,y.o ord,(y.x#>>'{row,id}')::uuid registration_id,(y.x#>>'{row,user_id}')::uuid user_id
    FROM jsonb_array_elements(COALESCE(inv#>'{population,tournament_players}','[]')) WITH ORDINALITY y(x,o)
    WHERE y.x#>>'{row,tournament_id}'=t->>'id'
   ), credits AS MATERIALIZED (
    -- fn_union_pnl_tournament_returns(t,NULL,NULL,p_at): every credit of this
    -- tournament observed before the boundary; the registration filter that
    -- function applied per call is applied per player below.
    SELECT c.user_id,c.credited_club_id,c.amount,c.entry_receipt_ids,true same_tournament
    FROM public.tournament_accounting_credit_receipts c
    JOIN public.union_pnl_transaction_frames b ON b.transaction_id=c.transaction_id
    WHERE c.tournament_id=(t->>'id')::uuid AND b.observed_at<p_at
    UNION ALL
    SELECT r2.user_id,r2.source_wallet_club_id,r2.amount_paid_now,ARRAY[r.id],false
    FROM public.tournament_refund_tranches r2
    JOIN public.tournament_participant_funding_receipts r ON r.entitlement_id=r2.entitlement_id
    JOIN public.union_pnl_transaction_frames b ON b.transaction_id=r2.transaction_id
    WHERE r2.tournament_id=(t->>'id')::uuid AND b.observed_at<p_at
     AND NOT EXISTS(SELECT 1 FROM public.tournament_accounting_credit_receipts c WHERE c.ledger_id=r2.credit_ledger_id)
   ) SELECT p.s,e.entries,e.owners,e.owned,e.value,
    EXISTS(SELECT 1 FROM public.tournament_participant_funding_receipts r WHERE r.tournament_id=(t->>'id')::uuid AND r.registration_id=p.registration_id AND r.asset<>'chips'),
    k.changed,k.returned,rr.owning_club_id,rr.deferred_amount
   FROM players p
   CROSS JOIN LATERAL (SELECT count(*) entries,count(DISTINCT public.fn_union_pnl_tournament_entry_club_of(r.asset,r.amount,r.funding_club_id,r.ledger_id,r.entitlement_id,r.registration_snapshot)) owners,
     min(public.fn_union_pnl_tournament_entry_club_of(r.asset,r.amount,r.funding_club_id,r.ledger_id,r.entitlement_id,r.registration_snapshot)::text)::uuid owned,sum(r.amount) value
    FROM public.tournament_participant_funding_receipts r
    JOIN public.union_pnl_transaction_frames b ON b.transaction_id=r.transaction_id
    WHERE r.tournament_id=(t->>'id')::uuid AND r.registration_id=p.registration_id AND b.observed_at<p_at AND r.asset='chips') e
   CROSS JOIN LATERAL (SELECT COALESCE(bool_or(c.credited_club_id<>e.owned),false) changed,sum(c.amount) returned
    FROM credits c WHERE c.user_id=p.user_id
     AND EXISTS(SELECT 1 FROM public.tournament_participant_funding_receipts r
      WHERE r.registration_id=p.registration_id AND r.id=ANY(c.entry_receipt_ids)
       AND (NOT c.same_tournament OR r.tournament_id=(t->>'id')::uuid))) k
   LEFT JOIN LATERAL (SELECT q.owning_club_id,q.deferred_amount
    FROM public.fn_union_pnl_opening_registration_resolution(p_union_id,p_at,t,p.s) q WHERE first_op='baseline') rr ON true
   ORDER BY p.ord
  LOOP
   -- In a baseline tournament a resolved registration is carried at its
   -- re-proved original entry less its returns before the boundary.
   IF res_club IS NOT NULL THEN
    holdings:=holdings||jsonb_build_array(jsonb_build_object('club_id',res_club,'user_id',s->'user_id','amount',res_amount,
     'kind','deferred_tournament_result','source_id',s->'id','basis','opening_registration_resolution'));
    CONTINUE;
   END IF;
   -- A satellite-won seat (20261007001000) has no entry receipt: it was
   -- never charged to a wallet. It is held at the value its one funding row
   -- moved into this prize liability, for the club that funded the seat.
   IF entries=0 AND NOT nonchips AND s->>'source_satellite_id' IS NOT NULL THEN
    SELECT count(*),sum(l.amount) INTO seat_rows,seat_value FROM public.chip_ledger l
     WHERE l.status='posted' AND l.row_hash IS NOT NULL AND l.created_at<p_at
      AND l.to_type='prize_liability' AND l.to_entity_id=(t->>'id')::uuid
      AND l.metadata->>'registration_id'=s->>'id' AND l.metadata->>'user_id'=s->>'user_id'
      AND ((l.category='tournament_buyin' AND l.from_type='prize_liability' AND l.from_entity_id=(s->>'source_satellite_id')::uuid
        AND l.metadata->>'kind'='satellite_seat_pool_transfer')
       OR (l.category='ticket_redeem' AND l.from_type='escrow' AND l.metadata->>'kind'='tournament_entry_ticket_admission'
        AND l.metadata->>'source_satellite_id'=s->>'source_satellite_id'));
    seat_club:=public.fn_union_pnl_satellite_seat_owner((s->>'id')::uuid,(t->>'id')::uuid);
    SELECT (SELECT count(*) FROM public.tournament_accounting_credit_receipts c
      JOIN public.union_pnl_transaction_frames b ON b.transaction_id=c.transaction_id
      WHERE c.tournament_id=(t->>'id')::uuid AND c.user_id::text=s->>'user_id' AND b.observed_at<p_at)
     +(SELECT count(*) FROM public.tournament_refund_tranches r2
      JOIN public.union_pnl_transaction_frames b ON b.transaction_id=r2.transaction_id
      WHERE r2.tournament_id=(t->>'id')::uuid AND r2.user_id::text=s->>'user_id' AND b.observed_at<p_at)
     INTO seat_credits;
    IF seat_rows=1 AND seat_value>0 AND seat_club IS NOT NULL AND seat_credits=0 THEN
     holdings:=holdings||jsonb_build_array(jsonb_build_object('club_id',seat_club,'user_id',s->'user_id','amount',seat_value,
      'kind','deferred_tournament_result','source_id',s->'id','basis','satellite_seat'));
     CONTINUE;
    END IF;
   END IF;
   IF entries=0 OR owners<>1 OR owned IS NULL OR nonchips THEN
    issues:=issues||jsonb_build_array(jsonb_build_object('reason','open_tournament_original_instrument_or_earning_club_missing','registration_id',s->'id')); CONTINUE;
   END IF;
   IF changed THEN
    issues:=issues||jsonb_build_array(jsonb_build_object('reason','open_tournament_credit_owner_changed','registration_id',s->'id')); CONTINUE;
   END IF;
   value:=value-COALESCE(returned,0);
   holdings:=holdings||jsonb_build_array(jsonb_build_object('club_id',owned,'user_id',s->'user_id','amount',value,'kind','deferred_tournament_result','source_id',s->'id'));
  END LOOP;
 END LOOP;
 RETURN jsonb_build_object('status',CASE WHEN issues='[]'::jsonb THEN 'ready' ELSE 'blocked' END,'boundary',p_at,
  'inventory',inv,'holdings',holdings,'issues',issues,'tournament_basis','original_realized_settlement_deferred_while_open');
END $$;

CREATE FUNCTION public.fn_union_pnl_cash_outcome_accepted(o public.union_pnl_cash_outcomes) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT o.evidence->'all_players_included' IS NOT DISTINCT FROM 'true'::jsonb
  AND o.evidence->'game_scope' IS NOT DISTINCT FROM o.game_scope
  AND ((o.evidence->>'status' IS NOT DISTINCT FROM 'ready' AND o.evidence->'basis_certified' IS NOT DISTINCT FROM 'true'::jsonb)
   OR EXISTS(SELECT 1 FROM public.union_pnl_cash_outcome_resolutions r WHERE r.table_id=o.table_id AND r.hand_number=o.hand_number
    AND r.hand_id=o.hand_id AND r.outcome_payload_hash=o.payload_hash AND r.outcome_evidence_md5=md5(o.evidence::text)))
$$;

CREATE FUNCTION public.fn_union_pnl_cash_outcome_link(o public.union_pnl_cash_outcomes) RETURNS SETOF public.union_pnl_cash_outcome_link_resolutions
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT r.* FROM public.union_pnl_cash_outcome_link_resolutions r
 WHERE r.table_id=o.table_id AND r.hand_number=o.hand_number AND r.hand_id=o.hand_id
  AND r.outcome_payload_hash=o.payload_hash AND r.outcome_evidence_md5=md5(o.evidence::text) AND r.proof_md5=md5(r.proof::text)
$$;

CREATE FUNCTION public.fn_union_pnl_close_quality(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE evidence jsonb;
BEGIN
 IF p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end)
  OR p_start<'2026-09-07 07:00:00+00'::timestamptz OR p_end<=p_start OR p_end>statement_timestamp()
  OR p_end-p_start>interval '8 days' THEN
  RETURN jsonb_build_object('status','blocked','reason','pnl_requires_closed_supported_period','issues',jsonb_build_array('invalid_pnl_evidence_period'));
 END IF;
 evidence:=public.fn_union_pnl_evidence_report(p_union_id,p_start,p_end);
 IF evidence->'report_version' IS DISTINCT FROM '1'::jsonb
  OR evidence->>'status' IS DISTINCT FROM 'ready' OR evidence->'basis_certified' IS DISTINCT FROM 'true'::jsonb
  OR evidence->'issues' IS DISTINCT FROM '[]'::jsonb THEN
  -- No player identities, source amounts, balances or invoice contents cross
  -- this gate. Callers retain their original authorization before evaluation.
  RETURN jsonb_build_object('status','blocked','reason','union_pnl_basis_uncertified',
   'issues',CASE WHEN jsonb_typeof(evidence->'issues')='array' THEN evidence->'issues'
    ELSE jsonb_build_array('pnl_evidence_contract_missing') END);
 END IF;
 RETURN jsonb_build_object('status','ready','issues','[]'::jsonb);
END $$;

CREATE FUNCTION public.fn_union_pnl_closed_book_barrier(p_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE started timestamptz; book timestamptz;
BEGIN
 IF p_at IS NULL OR NOT isfinite(p_at) OR p_at<>public.fn_union_week_start(p_at) OR p_at>clock_timestamp()
  OR current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'closed_original_book_barrier_required' USING ERRCODE='22023'; END IF;
 SELECT captured_at INTO started FROM public.union_pnl_inventory_capture WHERE singleton;
 IF started IS NULL THEN RAISE EXCEPTION 'original_inventory_capture_missing' USING ERRCODE='55000'; END IF;
 book:=public.fn_union_week_start(started);
 WHILE book<p_at LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('union-pnl-inventory:'||extract(epoch FROM book)::bigint::text,0));
  book:=public.fn_union_week_start(book+interval '8 days');
 END LOOP;
END $$;

CREATE FUNCTION public.fn_union_pnl_evidence_report(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_open jsonb; v_close jsonb; v_issues jsonb:='[]'; v_clubs jsonb; v_eco jsonb; v_terms jsonb;
 v_fence timestamptz; v_bad bigint; v_hands bigint; v_resolved bigint:=0; v_rows bigint; v_cash_reconciled boolean; v_terms_value jsonb; v_cash_rake numeric; v_accepted_rake numeric;
 v_memo_key text; v_memo jsonb; v_report jsonb; v_flows jsonb; v_open_resolved uuid[];
 v_inv boolean; v_cash boolean; v_credit boolean;
 v_cert jsonb;
BEGIN
 IF p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end)
  OR p_start<>public.fn_union_week_start(p_start) OR p_end<>public.fn_union_week_start(p_start+interval '8 days')
  OR p_end>clock_timestamp() THEN RAISE EXCEPTION 'invalid_closed_pnl_evidence_period' USING ERRCODE='22023'; END IF;
 SELECT captured_at INTO v_fence FROM public.union_pnl_weekly_capture WHERE singleton;
 IF v_fence IS NULL OR p_start<=v_fence THEN
  RETURN jsonb_build_object('report_version',1,'status','blocked','basis_certified',false,'payment_authorized',false,
   'issues',jsonb_build_array('week_precedes_complete_original_capture'),'capture_started_at',v_fence,'all_players_included',false);
 END IF;
 -- UNION P&L EVIDENCE MEMO (20260928): one weekly close reaches this report
 -- through preparation (close quality), the cascade (qualified clubs, ECO,
 -- player P&L) and the invoices. Inside a union close attempt
 -- (app.accounting_close_memo='on', set only by fn_weekly_accounting_attempt_begin)
 -- the first complete report of this (union, week) is kept for the rest of
 -- the attempt; attempt_begin and attempt_end clear it and a rolled-back
 -- subtransaction forgets it with its settings. Everywhere else the report is
 -- proved on every call, exactly as before.
 IF current_setting('app.accounting_close_memo',true)='on' THEN
  v_memo_key:=p_union_id::text||'|'||p_start::text||'|'||p_end::text;
  v_memo:=NULLIF(current_setting('app.union_pnl_evidence_memo',true),'')::jsonb;
  IF v_memo ? v_memo_key THEN RETURN v_memo->v_memo_key; END IF;
 END IF;
 -- UNION P&L NARROW READS (20260929044303): the week's registration events,
 -- hands and tournament credits are read through their narrow projections
 -- (union_pnl_inventory_touches, union_pnl_cash_outcome_touches,
 -- union_pnl_credit_touches), each written by its source row's own insert,
 -- once the throttled backfill has proved it complete; until then through
 -- the original wide rows, statement for statement as before.
 v_inv:=public.fn_union_pnl_projection_ready('inventory_touches');
 v_cash:=public.fn_union_pnl_projection_ready('cash_outcome_touches');
 v_credit:=public.fn_union_pnl_projection_ready('credit_touches');
 -- Both readers wait for the original book's in-flight transactions; this
 -- function is VOLATILE so every subsequent query sees their committed facts.
 -- CHUNKED CLOSE CERTIFICATES (20261003): inside a chunked union close attempt
 -- each expensive read below that found nothing wrong is kept, once proved,
 -- in accounting_close_certificates for the rest of that close of this
 -- closed week (fn_accounting_close_certificate / fn_accounting_close_certify;
 -- both do nothing anywhere else). An attempt whose time budget is spent
 -- after a step it had to prove returns 'warming' - not ready, nothing
 -- certified for payment - and the next attempt continues from the kept
 -- steps. A step that found a problem is kept for ONE HOUR (20261012), as
 -- '<kind>_problem' (fn_accounting_close_problem): it is never certified and
 -- never pays, its issues are reported exactly as before, and an attempt
 -- re-proves it once that hour has passed. Re-proving every problem step on
 -- every attempt is what held job 272's transactions for 3 to 5 minutes.
 v_open:=COALESCE(public.fn_accounting_close_certificate('pnl_boundary',p_union_id,p_start,p_start),
  public.fn_accounting_close_problem('pnl_boundary',p_union_id,p_start,p_start));
 IF v_open IS NULL THEN
  v_open:=public.fn_union_pnl_boundary(p_union_id,p_start);
  IF v_open->>'status'='ready' THEN PERFORM public.fn_accounting_close_certify('pnl_boundary',p_union_id,p_start,p_start,v_open);
  ELSE PERFORM public.fn_accounting_close_certify('pnl_boundary_problem',p_union_id,p_start,p_start,v_open); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 -- THE WINDOWS GO FIRST (20261012): the plan's two-hour windows (seconds each)
 -- are proved before the steps below, so an attempt that would otherwise
 -- spend its budget re-reading the boundaries and flows proves windows
 -- instead. Outside a chunked close the advance is NULL and nothing changes.
 IF public.fn_accounting_union_earned_plan_advance(p_union_id,p_start,p_end) IS FALSE THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 v_close:=COALESCE(public.fn_accounting_close_certificate('pnl_boundary',p_union_id,p_end,p_end),
  public.fn_accounting_close_problem('pnl_boundary',p_union_id,p_end,p_end));
 IF v_close IS NULL THEN
  v_close:=public.fn_union_pnl_boundary(p_union_id,p_end);
  IF v_close->>'status'='ready' THEN PERFORM public.fn_accounting_close_certify('pnl_boundary',p_union_id,p_end,p_end,v_close);
  ELSE PERFORM public.fn_accounting_close_certify('pnl_boundary_problem',p_union_id,p_end,p_end,v_close); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 IF v_open->>'status' IS DISTINCT FROM 'ready' THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','opening_basis_incomplete','evidence',v_open)); END IF;
 IF v_close->>'status' IS DISTINCT FROM 'ready' THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','closing_basis_incomplete','evidence',v_close)); END IF;
 -- The registrations the opening boundary carried through a valid opening
 -- resolution (union_pnl_opening_registration_resolutions): each one's
 -- original entry is proved from the posted chip ledger, not a funding receipt.
 v_open_resolved:=ARRAY(SELECT (x->>'source_id')::uuid FROM jsonb_array_elements(COALESCE(v_open->'holdings','[]')) x
  WHERE x->>'kind'='deferred_tournament_result' AND x->>'basis'='opening_registration_resolution');
 -- A blocked outcome counts as accepted only through an immutable resolution
 -- receipt re-proved from primary receipts and bound to this exact outcome
 -- (hand, payload hash, evidence). The outcome row itself is never changed.
 -- Only a hand outside the ready/certified/all-players/same-scope shape can
 -- be refused or resolved: those hands (the predicate of
 -- union_pnl_cash_outcomes_unaccepted), found through the projection's shape
 -- flag and re-checked against their rows, never the whole week's evidence.
 SELECT count(*) FILTER(WHERE NOT public.fn_union_pnl_cash_outcome_accepted(o)),
  count(*) FILTER(WHERE (o.evidence->>'status' IS DISTINCT FROM 'ready' OR o.evidence->'basis_certified' IS DISTINCT FROM 'true'::jsonb)
   AND public.fn_union_pnl_cash_outcome_accepted(o))
 INTO v_bad,v_resolved FROM public.fn_union_pnl_week_shaped_hands(p_union_id,p_start,p_end,v_cash) o;
 -- A hand whose provenance link the engine never recorded (its outcome has no
 -- game scope) counts only through its immutable link resolution
 -- (union_pnl_cash_outcome_link_resolutions), in the Union its re-proved scope
 -- names, and is accepted only when its re-proved evidence is certified.
 SELECT v_bad+count(*) FILTER(WHERE NOT (k.evidence->>'status'='ready' AND k.evidence->'basis_certified'='true'::jsonb
   AND k.evidence->'all_players_included'='true'::jsonb)),
  v_resolved+count(*) FILTER(WHERE k.evidence->>'status'='ready' AND k.evidence->'basis_certified'='true'::jsonb
   AND k.evidence->'all_players_included'='true'::jsonb)
 INTO v_bad,v_resolved FROM public.fn_union_pnl_linked_cash_outcomes(p_union_id,p_start,p_end) k;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','accepted_cash_basis_incomplete','count',v_bad)); END IF;
 -- A missing original game scope cannot silently disappear from every Union.
 SELECT count(*) INTO v_bad FROM public.union_pnl_cash_outcomes WHERE recognized_at>=p_start AND recognized_at<p_end
  AND NOT game_scope ?& ARRAY['game_union_id','host_club_id','tournament_id','is_private','asset','unit_scale']
  AND NOT EXISTS(SELECT 1 FROM public.fn_union_pnl_cash_outcome_link(union_pnl_cash_outcomes));
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','accepted_cash_original_scope_missing','count',v_bad)); END IF;
 SELECT count(*) INTO v_bad FROM public.union_pnl_original_flows WHERE recognized_at>=p_start AND recognized_at<p_end
  AND NOT game_scope ?& ARRAY['game_union_id','host_club_id','tournament_id','is_private','asset','unit_scale'];
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','original_money_flow_scope_missing','count',v_bad)); END IF;
 SELECT count(*) INTO v_bad FROM public.cash_participant_funding_receipts WHERE recorded_at>=v_fence AND recorded_at<p_end AND transaction_id IS NULL;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array('post_capture_funding_transaction_identity_missing'); END IF;
 SELECT count(*) INTO v_bad FROM public.cash_funding_application_receipts WHERE applied_at>=v_fence AND applied_at<p_end AND transaction_id IS NULL;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array('post_capture_application_transaction_identity_missing'); END IF;
 SELECT count(*) INTO v_bad FROM public.cash_hand_provenance_receipts WHERE accepted_at>=v_fence AND accepted_at<p_end AND transaction_id IS NULL;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array('post_capture_hand_transaction_identity_missing'); END IF;
 -- The flow proof is read once; the P&L below reuses these exact rows.
 v_cert:=COALESCE(public.fn_accounting_close_certificate('pnl_flows',p_union_id,p_start,p_end),
  public.fn_accounting_close_problem('pnl_flows',p_union_id,p_start,p_end));
 IF v_cert IS NOT NULL THEN
  v_bad:=(v_cert->>'bad')::bigint; v_flows:=v_cert->'flows';
 ELSE
 SELECT count(*) FILTER(WHERE NOT f.valid),COALESCE(jsonb_agg(to_jsonb(f)),'[]') INTO v_bad,v_flows
  FROM public.fn_union_pnl_original_flow_evidence(p_union_id,p_start,p_end) f;
  IF v_bad=0 THEN PERFORM public.fn_accounting_close_certify('pnl_flows',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad,'flows',v_flows));
  ELSE PERFORM public.fn_accounting_close_certify('pnl_flows_problem',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad,'flows',v_flows)); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','original_money_flow_basis_incomplete','count',v_bad)); END IF;
 -- Every touched tournament registration must have its original chip entry,
 -- including zero-rake players. Historical/current membership is never used.
 -- The week's registration events, each touched tournament's Union proved
 -- once through its own events (t.row_id::text equality kept; the uuid
 -- equality only lets the index find the same rows and is never attempted on
 -- a non-canonical id). The frame test is unchanged; i.observed_at repeats it
 -- because fn_union_pnl_inventory_observe, the only writer of framed events,
 -- stamps each event with its frame's observed_at (both tables immutable), so
 -- the same rows are reached through union_pnl_inventory_events_players_observed.
 -- Both reads (fn_union_pnl_touched_registrations, fn_union_pnl_tournament_in_union)
 -- come from union_pnl_inventory_touches once it is complete: the same keys,
 -- the frame's observed_at copied at capture, without the wide rows.
 v_cert:=COALESCE(public.fn_accounting_close_certificate('pnl_touched',p_union_id,p_start,p_end),
  public.fn_accounting_close_problem('pnl_touched',p_union_id,p_start,p_end));
 IF v_cert IS NOT NULL THEN
  v_bad:=(v_cert->>'bad')::bigint;
 ELSE
 WITH touched AS MATERIALIZED (
  SELECT w.registration_id row_id,w.touched_tournament_id tournament_id
  FROM public.fn_union_pnl_touched_registrations(p_start,p_end,v_inv) w
 ), union_tournaments AS MATERIALIZED (
  SELECT d.tournament_id FROM (SELECT DISTINCT tournament_id FROM touched) d
  WHERE public.fn_union_pnl_tournament_in_union(d.tournament_id,p_union_id,v_inv)
 ), union_touched AS MATERIALIZED (
  SELECT i.row_id FROM touched i WHERE i.tournament_id IN (SELECT tournament_id FROM union_tournaments)
 ), entries AS MATERIALIZED (
  -- the two receipt tests, read once per touched registration (column for
  -- column: a whole-row argument would detoast every receipt's snapshots)
  SELECT r.registration_id,
   bool_or(r.asset='chips' AND public.fn_union_pnl_tournament_entry_club_of(r.asset,r.amount,r.funding_club_id,r.ledger_id,r.entitlement_id,r.registration_snapshot) IS NOT NULL) has_entry,
   bool_or(r.asset<>'chips' OR public.fn_union_pnl_tournament_entry_club_of(r.asset,r.amount,r.funding_club_id,r.ledger_id,r.entitlement_id,r.registration_snapshot) IS NULL) has_other
  FROM public.tournament_participant_funding_receipts r
  WHERE r.registration_id IN (SELECT row_id FROM union_touched)
  GROUP BY r.registration_id
 ) SELECT count(*) INTO v_bad FROM union_touched i LEFT JOIN entries e ON e.registration_id=i.row_id
 WHERE (NOT COALESCE(e.has_entry,false) AND i.row_id<>ALL(v_open_resolved)
   AND public.fn_union_pnl_satellite_seat_owner(i.row_id,NULL) IS NULL)
  OR COALESCE(e.has_other,false);
  IF v_bad=0 THEN PERFORM public.fn_accounting_close_certify('pnl_touched',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad));
  ELSE PERFORM public.fn_accounting_close_certify('pnl_touched_problem',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad)); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','tournament_original_population_or_instrument_incomplete','count',v_bad)); END IF;
 -- An award must return to the original funding club; a changed credited
 -- wallet does not prove a new earning ownership agreement.
 -- The week's credits of this Union (its tournament snapshot's Union, its
 -- frame in the week) come from union_pnl_credit_touches once complete. The
 -- two whole-row resolutions (a whole-row value detoasts every snapshot of
 -- the credit) are asked only of a credit the entry test did not settle: the
 -- same conjunction, in an order the planner may not change.
 SELECT count(*) INTO v_bad FROM public.fn_union_pnl_week_union_credits(p_union_id,p_start,p_end,v_credit) w
 JOIN public.tournament_accounting_credit_receipts c ON c.id=w.credit_id
 WHERE CASE WHEN (cardinality(c.entry_receipt_ids)=0 OR EXISTS(SELECT 1 FROM unnest(c.entry_receipt_ids) original_id(receipt_id)
   LEFT JOIN public.tournament_participant_funding_receipts r ON r.id=original_id.receipt_id
   WHERE r.id IS NULL OR r.asset<>'chips' OR public.fn_union_pnl_tournament_entry_club_of(r.asset,r.amount,r.funding_club_id,r.ledger_id,r.entitlement_id,r.registration_snapshot) IS DISTINCT FROM c.credited_club_id OR r.user_id IS DISTINCT FROM c.user_id))
  THEN NOT public.fn_union_pnl_award_owner_resolved(c,p_union_id,p_start,v_open_resolved)
   AND NOT public.fn_union_pnl_award_satellite_owner(c) ELSE false END;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','tournament_award_original_earning_owner_incomplete','count',v_bad)); END IF;
 v_eco:=public.fn_union_eco_terms_evidence(p_union_id,p_start,p_end);
 IF v_eco->>'status' IS DISTINCT FROM 'ready' THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','eco_commercial_basis_incomplete','evidence',v_eco)); END IF;
 SELECT count(DISTINCT x->'terms') INTO v_bad FROM jsonb_array_elements(COALESCE(v_eco->'segments','[]')) x;
 IF v_bad<>1 THEN v_issues:=v_issues||jsonb_build_array('eco_intraweek_changed_terms_require_original_allocation'); END IF;
 v_terms_value:=v_eco#>'{segments,0,terms}';
 -- Validate every original bank/source leg even when the week has no rows.
 -- CHUNKED CLOSE WINDOWS (20261003): inside a chunked close the plan's
 -- two-hour windows are proved first, a few per attempt; until all are, the
 -- attempt stops warming (fn_accounting_union_earned_plan_advance is NULL,
 -- and this test passes, everywhere else).
 -- (THE WINDOWS GO FIRST, 20261012: the plan's windows are proved above,
 -- right after the opening boundary, before any step that can be re-proved.)
 PERFORM public.fn_accounting_union_earned_plan(p_union_id,p_start,p_end);
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 v_cert:=COALESCE(public.fn_accounting_close_certificate('pnl_clubs',p_union_id,p_start,p_end),
  public.fn_accounting_close_problem('pnl_clubs',p_union_id,p_start,p_end));
 IF v_cert IS NOT NULL THEN
  v_clubs:=v_cert->'clubs'; v_cash_reconciled:=(v_cert->>'cash_reconciled')::boolean; v_rows:=(v_cert->>'rows')::bigint;
  v_cash_rake:=(v_cert->>'cash_rake')::numeric; v_hands:=(v_cert->>'hands')::bigint; v_accepted_rake:=(v_cert->>'accepted_rake')::numeric;
 ELSE
 WITH flows AS MATERIALIZED (SELECT * FROM jsonb_to_recordset(v_flows)
  AS f(ledger_id uuid,club_id uuid,user_id uuid,buyins numeric,cashouts numeric,kind text,valid boolean)),
 -- One read of the week's hands: each (club, player) delta total, and (kind 0)
 -- the hand count and accepted rake that used to cost two more reads.
 outcome_pass AS MATERIALIZED (
  SELECT x.kind,x.club_id,x.user_id,sum(x.delta) delta,count(*) hands,sum(x.rake) rake
  FROM (SELECT h.hand_accepted_rake accepted_rake,h.hand_participants participants
   FROM public.fn_union_pnl_week_hand_lines(p_union_id,p_start,p_end,v_cash) h
   -- with this Union's linked hands, through their link resolutions
   UNION ALL SELECT k.evidence->>'accepted_rake',k.evidence->'participants' FROM public.fn_union_pnl_linked_cash_outcomes(p_union_id,p_start,p_end) k) o CROSS JOIN LATERAL (
   SELECT 0 kind,NULL::uuid club_id,NULL::uuid user_id,NULL::numeric delta,o.accepted_rake::numeric rake
   UNION ALL
   SELECT 1,(p->>'earning_club_id')::uuid,(p->>'user_id')::uuid,(p->>'observed_stack_delta')::numeric,NULL::numeric
   FROM jsonb_array_elements(COALESCE(o.participants,'[]')) p) x
  GROUP BY x.kind,x.club_id,x.user_id
 ), hand_players AS (SELECT club_id,user_id,delta FROM outcome_pass WHERE kind=1
  -- JACKPOT SHARES ON THE FELT (20260929): a Bad Beat Jackpot share credited
  -- to a seat after its hand committed is that player's cash result too.
  UNION ALL SELECT a.club_id,a.user_id,a.amount FROM public.fn_union_pnl_week_bbj_stack_awards(p_union_id,p_start,p_end) a), opening AS (SELECT (x->>'club_id')::uuid club_id,sum((x->>'amount')::numeric) amount,
   sum((x->>'amount')::numeric) FILTER(WHERE x->>'kind'<>'deferred_tournament_result') cash
   FROM jsonb_array_elements(COALESCE(v_open->'holdings','[]')) x GROUP BY 1),
 closing AS (SELECT (x->>'club_id')::uuid club_id,sum((x->>'amount')::numeric) amount,
   sum((x->>'amount')::numeric) FILTER(WHERE x->>'kind'<>'deferred_tournament_result') cash
   FROM jsonb_array_elements(COALESCE(v_close->'holdings','[]')) x GROUP BY 1),
 -- The canonical payout basis excludes retained Union-house rake. Gross
 -- original rake still belongs in the all-player P&L and bank reconciliation.
 rake AS MATERIALIZED (
  SELECT s.club_id,sum(s.rake_credit) generated,COALESCE(k.earned,0) earned,
   sum(s.rake_credit) FILTER(WHERE s.source_type='cash_rake_accrual') cash_rake,
   sum(s.rake_credit) FILTER(WHERE s.source_type='tournament_fee_accrual') tournament_rake
  FROM public.accounting_payable_earning_sources s
  LEFT JOIN (SELECT club_id,sum(payout) earned FROM public.fn_union_club_rake_basis(p_union_id,p_start,p_end) GROUP BY club_id) k ON k.club_id=s.club_id
  WHERE s.union_id=p_union_id AND s.earned_at>=p_start AND s.earned_at<p_end GROUP BY s.club_id,k.earned
 ),
 roster AS (
  SELECT DISTINCT (COALESCE(after_row,before_row)->>'club_id')::uuid club_id FROM public.union_pnl_inventory_events
   WHERE source_name='union_clubs' AND COALESCE(after_row,before_row)->>'union_id'=p_union_id::text AND observed_at<p_end
    AND (observed_at>=p_start OR row_id::text IN(SELECT x#>>'{row,id}' FROM jsonb_array_elements(COALESCE(v_open#>'{inventory,population,union_clubs}','[]')) x))
  UNION SELECT club_id FROM rake UNION SELECT club_id FROM flows UNION SELECT club_id FROM hand_players UNION SELECT club_id FROM opening UNION SELECT club_id FROM closing
 ), movement AS (SELECT club_id,sum(buyins) buyins,sum(cashouts) cashouts,
  sum(cashouts-buyins) FILTER(WHERE kind IN('cash_funding','cash_return')) cash_flow,
  sum(buyins) FILTER(WHERE kind='cash_funding') cash_buyins,sum(cashouts) FILTER(WHERE kind='cash_return') cash_cashouts FROM flows GROUP BY club_id),
 hands AS (SELECT club_id,sum(delta) delta FROM hand_players GROUP BY club_id),
 people AS (SELECT club_id,count(DISTINCT user_id)::int players FROM(SELECT club_id,user_id FROM flows UNION SELECT club_id,user_id FROM hand_players
  UNION SELECT (x->>'club_id')::uuid,(x->>'user_id')::uuid FROM jsonb_array_elements(COALESCE(v_open->'holdings','[]')||COALESCE(v_close->'holdings','[]')) x) q GROUP BY club_id),
 club_rows AS (
  SELECT r.club_id,COALESCE(m.buyins,0) buyins,COALESCE(m.cashouts,0) cashouts,COALESCE(m.cash_buyins,0) cash_buyins,COALESCE(m.cash_cashouts,0) cash_cashouts,
   COALESCE(m.cashouts,0)-COALESCE(m.buyins,0) realized_net,COALESCE(o.amount,0) seated_start,COALESCE(c.amount,0) seated_end,
   COALESCE(o.cash,0) seated_start_cash,COALESCE(c.cash,0) seated_end_cash,
   COALESCE(c.amount,0)-COALESCE(o.amount,0) stack_delta,COALESCE(h.delta,0) cash_player_pnl,
   COALESCE(m.cashouts,0)-COALESCE(m.buyins,0)+COALESCE(c.amount,0)-COALESCE(o.amount,0)-COALESCE(h.delta,0) tournament_player_pnl,
   COALESCE(m.cash_flow,0)+COALESCE(c.cash,0)-COALESCE(o.cash,0)=COALESCE(h.delta,0) cash_reconciled,
   COALESCE(p.players,0) players,COALESCE(k.generated,0) rake_paid,COALESCE(k.earned,0) rake_earned,COALESCE(k.cash_rake,0) cash_rake,COALESCE(k.tournament_rake,0) tournament_rake,
   COALESCE(m.cashouts,0)-COALESCE(m.buyins,0)+COALESCE(c.amount,0)-COALESCE(o.amount,0)+COALESCE(k.generated,0) net
  FROM roster r LEFT JOIN movement m USING(club_id) LEFT JOIN opening o USING(club_id) LEFT JOIN closing c USING(club_id)
  LEFT JOIN hands h USING(club_id) LEFT JOIN people p USING(club_id) LEFT JOIN rake k USING(club_id)
  WHERE r.club_id IS NOT NULL
 ), player_results AS (
  SELECT club_id,user_id,sum(delta) delta FROM (
   SELECT club_id,user_id,cashouts-buyins delta FROM flows
   UNION ALL SELECT (x->>'club_id')::uuid,(x->>'user_id')::uuid,(x->>'amount')::numeric FROM jsonb_array_elements(COALESCE(v_close->'holdings','[]')) x
   UNION ALL SELECT (x->>'club_id')::uuid,(x->>'user_id')::uuid,-(x->>'amount')::numeric FROM jsonb_array_elements(COALESCE(v_open->'holdings','[]')) x
  ) amounts GROUP BY club_id,user_id
 ), wins AS(SELECT club_id,sum(greatest(delta,0)) winnings,sum(greatest(-delta,0)) losses FROM player_results GROUP BY club_id), complete AS (
  SELECT q.*,COALESCE(w.winnings,0) winnings,COALESCE(w.losses,0) losses,
   CASE v_terms_value->>'eco_base_mode'
    WHEN 'club_cash_profit' THEN rake_earned-cash_player_pnl
    WHEN 'net_invoice_position' THEN realized_net+stack_delta+rake_paid+rake_earned
    WHEN 'winnings_plus_rake' THEN realized_net+stack_delta+rake_paid
    WHEN 'winnings_only' THEN realized_net+stack_delta END eco_base
  FROM club_rows q LEFT JOIN wins w USING(club_id)
 ) SELECT COALESCE(jsonb_agg(to_jsonb(q)||jsonb_build_object('eco_amount',CASE WHEN v_terms_value->'eco_enabled'='true'::jsonb
  THEN round(-(v_terms_value->>'eco_rate')::numeric*eco_base,2) ELSE 0 END) ORDER BY club_id),'[]'),
  COALESCE(bool_and(cash_reconciled),true),count(*),COALESCE(sum(cash_rake),0),
  COALESCE((SELECT h.hands FROM outcome_pass h WHERE h.kind=0),0),(SELECT COALESCE(sum(h.rake),0) FROM outcome_pass h WHERE h.kind=0)
  INTO v_clubs,v_cash_reconciled,v_rows,v_cash_rake,v_hands,v_accepted_rake FROM complete q;
  IF v_cash_reconciled AND v_accepted_rake IS NOT DISTINCT FROM v_cash_rake THEN
   PERFORM public.fn_accounting_close_certify('pnl_clubs',p_union_id,p_start,p_end,jsonb_build_object('clubs',v_clubs,
    'cash_reconciled',v_cash_reconciled,'rows',v_rows,'cash_rake',v_cash_rake,'hands',v_hands,'accepted_rake',v_accepted_rake));
  ELSE
   PERFORM public.fn_accounting_close_certify('pnl_clubs_problem',p_union_id,p_start,p_end,jsonb_build_object('clubs',v_clubs,
    'cash_reconciled',v_cash_reconciled,'rows',v_rows,'cash_rake',v_cash_rake,'hands',v_hands,'accepted_rake',v_accepted_rake));
  END IF;
 END IF;
 IF v_accepted_rake IS DISTINCT FROM v_cash_rake THEN v_issues:=v_issues||jsonb_build_array('accepted_cash_rake_does_not_match_original_earning_and_bank_basis'); END IF;
 IF NOT v_cash_reconciled THEN v_issues:=v_issues||jsonb_build_array('accepted_cash_deltas_do_not_reconcile_original_flows_and_boundaries'); END IF;
 v_report:=jsonb_build_object('report_version',1,'status',CASE WHEN v_issues='[]'::jsonb THEN 'ready' ELSE 'blocked' END,
  'basis_certified',v_issues='[]'::jsonb,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,
  'issues',v_issues,'clubs',v_clubs,'opening_basis',v_open,'closing_basis',v_close,'eco_commercial_terms_evidence',v_eco,
  'accepted_cash_hands',v_hands,'accepted_cash_hands_resolved',v_resolved,'club_count',v_rows,'current_seats_used',false,'current_membership_used',false,
  'all_players_included',v_issues='[]'::jsonb,'tournament_basis','original_realized_settlement_deferred_while_open');
 IF v_memo_key IS NOT NULL THEN
  PERFORM set_config('app.union_pnl_evidence_memo',(COALESCE(NULLIF(current_setting('app.union_pnl_evidence_memo',true),'')::jsonb,'{}')
   ||jsonb_build_object(v_memo_key,v_report))::text,true);
 END IF;
 RETURN v_report;
END $$;

CREATE FUNCTION public.fn_union_pnl_first_inventory_operation(p_source text, p_row_id uuid, p_projected boolean) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v text;
BEGIN
 IF p_projected AND p_source IN ('tournament_players','tournaments') THEN
  SELECT t.operation INTO v FROM public.union_pnl_inventory_touches t WHERE t.source_name=p_source AND t.row_id=p_row_id ORDER BY t.event_id LIMIT 1;
 ELSE
  SELECT e.operation INTO v FROM public.union_pnl_inventory_events e WHERE e.source_name=p_source AND e.row_id=p_row_id ORDER BY e.event_id LIMIT 1;
 END IF;
 RETURN v;
END $$;

CREATE FUNCTION public.fn_union_pnl_inventory_as_of(p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE origin public.union_pnl_inventory_capture%ROWTYPE; book timestamptz; v_base timestamptz; v_projection jsonb; v_result jsonb;
BEGIN
 SELECT * INTO origin FROM public.union_pnl_inventory_capture WHERE singleton;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','blocked','reason','inventory_capture_missing'); END IF;
 IF p_at IS NULL OR NOT isfinite(p_at) OR p_at<>public.fn_union_week_start(p_at) OR p_at>clock_timestamp() THEN
  RETURN jsonb_build_object('status','blocked','reason','closed_original_week_boundary_required'); END IF;
 IF p_at<=origin.captured_at THEN RETURN jsonb_build_object('status','blocked','reason','boundary_precedes_original_inventory_capture','capture_started_at',origin.captured_at); END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RETURN jsonb_build_object('status','blocked','reason','inventory_requires_fresh_read_committed_snapshot'); END IF;
 book:=public.fn_union_week_start(origin.captured_at);
 WHILE book<p_at LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('union-pnl-inventory:'||extract(epoch FROM book)::bigint::text,0));
  book:=public.fn_union_week_start(book+interval '8 days');
 END LOOP;
 -- Every writer that could precede p_at has committed (the locks above), so
 -- the result is final: one transaction computes it once.
 IF to_regclass('pg_temp.union_pnl_inventory_as_of_cache') IS NOT NULL THEN
  EXECUTE 'SELECT result FROM pg_temp.union_pnl_inventory_as_of_cache WHERE boundary=$1' INTO v_result USING p_at;
  IF v_result IS NOT NULL THEN RETURN v_result; END IF;
 END IF;
 -- VOLATILE intentionally obtains a fresh snapshot after the old-book writers
 -- have committed. A stable/snapshot reader could omit those committed events.
 SELECT c.boundary INTO v_base FROM public.union_pnl_inventory_checkpoints c WHERE c.boundary<=p_at ORDER BY c.boundary DESC LIMIT 1;
 v_projection:=public.fn_union_pnl_inventory_population(v_base,p_at);
 v_result:=jsonb_build_object('status',CASE WHEN v_projection->'issues'='[]'::jsonb THEN 'observed' ELSE 'blocked' END,
  'inventory_version',1,'capture_started_at',origin.captured_at,'boundary',p_at,'population',v_projection->'population','issues',v_projection->'issues',
  'current_state_used',false,'financial_basis_certified',false,
  'coverage','Original active population and later captured transitions; monetary funding and obligation receipts must independently certify equity.');
 BEGIN
  IF to_regclass('pg_temp.union_pnl_inventory_as_of_cache') IS NULL THEN
   EXECUTE 'CREATE TEMP TABLE union_pnl_inventory_as_of_cache(boundary timestamptz PRIMARY KEY, result jsonb NOT NULL) ON COMMIT DROP';
  END IF;
  EXECUTE 'INSERT INTO pg_temp.union_pnl_inventory_as_of_cache(boundary,result) VALUES($1,$2) ON CONFLICT (boundary) DO NOTHING' USING p_at,v_result;
 EXCEPTION WHEN read_only_sql_transaction THEN NULL;
 END;
 RETURN v_result;
END $_$;

CREATE FUNCTION public.fn_union_pnl_inventory_population(p_base timestamp with time zone, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE population jsonb; gaps jsonb;
BEGIN
 WITH s AS MATERIALIZED (
  SELECT * FROM public.fn_union_pnl_inventory_state(p_base,p_at)
 ), current_rows AS MATERIALIZED (
  SELECT s.o_source_name source_name,s.o_row_id row_id,s.o_event_id event_id,s.o_after_row after_row,s.o_first_operation first_operation
  FROM s WHERE s.o_kind='row' AND s.o_after_row IS NOT NULL
 ), active AS MATERIALIZED (
  SELECT * FROM current_rows r WHERE source_name='union_clubs'
   OR (source_name='tables' AND after_row->'tournament_id'='null'::jsonb)
   OR (source_name='table_seats' AND after_row->'left_at'='null'::jsonb)
   OR (source_name='tournaments' AND after_row->>'status' NOT IN ('COMPLETED','CANCELLED'))
   OR (source_name='tournament_players' AND EXISTS(SELECT 1 FROM current_rows t WHERE t.source_name='tournaments'
    AND t.row_id::text=r.after_row->>'tournament_id' AND t.after_row->>'status' NOT IN ('COMPLETED','CANCELLED')))
 ), grouped AS (
  SELECT source_name,jsonb_agg(jsonb_build_object('source_event_id',event_id,'row',after_row) ORDER BY row_id) rows FROM active GROUP BY source_name
 ) SELECT COALESCE((SELECT jsonb_object_agg(source_name,rows) FROM grouped),'{}'),
  COALESCE((SELECT jsonb_agg(jsonb_build_object('source_name',source_name,'row_id',row_id,'reason','active_row_original_population_missing') ORDER BY source_name,row_id)
   FROM active WHERE first_operation NOT IN ('baseline','INSERT')
    -- A seat vacated before capture began and re-opened afterwards: its first
    -- captured event is the UPDATE that opened this occupancy (see 20260928153000).
    AND NOT (source_name='table_seats' AND first_operation='UPDATE' AND EXISTS(
     SELECT 1 FROM (SELECT e.before_row FROM public.union_pnl_inventory_events e
       WHERE e.source_name='table_seats' AND e.row_id=active.row_id ORDER BY e.event_id LIMIT 1) f
     WHERE f.before_row->>'left_at' IS NOT NULL
      AND (f.before_row->>'left_at')::timestamptz<=(SELECT c.captured_at FROM public.union_pnl_inventory_capture c WHERE c.singleton)))),'[]')
  ||COALESCE((SELECT jsonb_agg(jsonb_build_object('source_name',s.o_source_name,'row_id',s.o_row_id,'source_event_id',s.o_event_id,'reason','original_inventory_chain_disagrees') ORDER BY s.o_source_name,s.o_row_id,s.o_event_id)
   FROM s WHERE s.o_kind='issue'),'[]') INTO population,gaps;
 RETURN jsonb_build_object('population',population,'issues',gaps);
END $$;

CREATE FUNCTION public.fn_union_pnl_inventory_state(p_base timestamp with time zone, p_at timestamp with time zone) RETURNS TABLE(o_kind text, o_source_name text, o_row_id uuid, o_event_id bigint, o_first_operation text, o_after_row jsonb)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    SET work_mem TO '64MB'
    SET enable_indexscan TO 'off'
    SET max_parallel_workers_per_gather TO '0'
    AS $$
BEGIN
 -- Plain index scans are off: measured on production 2026-09-28, a cold week
 -- range read through the boundary index one heap page at a time costs
 -- ~235us an event (7.8M events: ~30 min); the same range as a bitmap heap
 -- scan, pages in physical order, ~45us (~6 min), less in parallel.
 IF p_at IS NULL OR NOT isfinite(p_at) OR (p_base IS NOT NULL AND (NOT isfinite(p_base) OR p_base>p_at)) THEN
  RAISE EXCEPTION 'invalid_inventory_state_window' USING ERRCODE='22023'; END IF;
 RETURN QUERY
 WITH d AS MATERIALIZED (
  SELECT e.source_name sn,e.row_id rid,e.event_id eid,e.operation op,
   jsonb_hash_extended(e.before_row,0) b0,jsonb_hash_extended(e.before_row,1) b1,
   jsonb_hash_extended(e.after_row,0) a0,jsonb_hash_extended(e.after_row,1) a1
  FROM public.union_pnl_inventory_events e
  WHERE e.observed_at>=COALESCE(p_base,'-infinity'::timestamptz) AND e.observed_at<p_at
 ), b AS MATERIALIZED (
  SELECT r.source_name sn,r.row_id rid,r.latest_event_id eid,r.first_operation fop,r.after_row,
   jsonb_hash_extended(r.after_row,0) a0,jsonb_hash_extended(r.after_row,1) a1
  FROM public.union_pnl_inventory_checkpoint_rows r WHERE r.boundary=p_base
 ), t AS MATERIALIZED (
  SELECT d.sn,d.rid,min(d.eid) min_id,max(d.eid) max_id FROM d GROUP BY d.sn,d.rid
 ), x AS MATERIALIZED (
  -- A delta event ordered (by event_id) before the row's last pre-base event:
  -- that row's whole chain is re-read below instead of continued.
  SELECT t.sn,t.rid FROM t JOIN b ON b.sn=t.sn AND b.rid=t.rid WHERE t.min_id<b.eid
 ), w AS MATERIALIZED (
  SELECT d.sn,d.rid,d.eid,d.b0,d.b1,
   row_number() OVER p k,lag(d.a0) OVER p pa0,lag(d.a1) OVER p pa1,first_value(d.op) OVER p fop
  FROM d WHERE NOT EXISTS(SELECT 1 FROM x WHERE x.sn=d.sn AND x.rid=d.rid)
  WINDOW p AS (PARTITION BY d.sn,d.rid ORDER BY d.eid)
 ), tl AS MATERIALIZED (
  -- The latest row image of each continued row, fetched in one pass in
  -- physical order rather than one random heap read per row.
  SELECT e.event_id eid,e.after_row FROM public.union_pnl_inventory_events e
  WHERE e.event_id=ANY(ARRAY(SELECT t.max_id FROM t WHERE NOT EXISTS(SELECT 1 FROM x WHERE x.sn=t.sn AND x.rid=t.rid)))
 ), xh AS MATERIALIZED (
  -- LATERAL: always one identity-index read per interleaved row, never a join
  -- plan that scans the history.
  SELECT e.sn,e.rid,e.eid,e.before_row,e.after_row,
   row_number() OVER p k,row_number() OVER (PARTITION BY e.sn,e.rid ORDER BY e.eid DESC) latest,
   lag(e.after_row) OVER p prior_after,first_value(e.op) OVER p fop
  FROM x CROSS JOIN LATERAL (
   SELECT h.source_name sn,h.row_id rid,h.event_id eid,h.operation op,h.before_row,h.after_row
   FROM public.union_pnl_inventory_events h WHERE h.source_name=x.sn AND h.row_id=x.rid AND h.observed_at<p_at) e
  WINDOW p AS (PARTITION BY e.sn,e.rid ORDER BY e.eid)
 )
 SELECT 'row'::text,b.sn,b.rid,b.eid,b.fop,b.after_row FROM b
  WHERE NOT EXISTS(SELECT 1 FROM t WHERE t.sn=b.sn AND t.rid=b.rid)
 UNION ALL
 SELECT 'row',t.sn,t.rid,t.max_id,COALESCE(b.fop,w.fop),tl.after_row
  FROM t JOIN w ON w.sn=t.sn AND w.rid=t.rid AND w.k=1
  JOIN tl ON tl.eid=t.max_id
  LEFT JOIN b ON b.sn=t.sn AND b.rid=t.rid
 UNION ALL
 SELECT 'row',xh.sn,xh.rid,xh.eid,xh.fop,xh.after_row FROM xh WHERE xh.latest=1
 UNION ALL
 SELECT 'issue',i.source_name,i.row_id,i.event_id,NULL::text,NULL::jsonb FROM public.union_pnl_inventory_checkpoint_issues i
  WHERE i.boundary=p_base AND NOT EXISTS(SELECT 1 FROM x WHERE x.sn=i.source_name AND x.rid=i.row_id)
 UNION ALL
 SELECT 'issue',w.sn,w.rid,w.eid,NULL,NULL FROM w WHERE w.k>1 AND (w.pa0,w.pa1) IS DISTINCT FROM (w.b0,w.b1)
 UNION ALL
 SELECT 'issue',w.sn,w.rid,w.eid,NULL,NULL FROM w JOIN b ON b.sn=w.sn AND b.rid=w.rid
  WHERE w.k=1 AND (b.a0,b.a1) IS DISTINCT FROM (w.b0,w.b1)
 UNION ALL
 SELECT 'issue',xh.sn,xh.rid,xh.eid,NULL,NULL FROM xh WHERE xh.k>1 AND xh.prior_after IS DISTINCT FROM xh.before_row;
END $$;

CREATE FUNCTION public.fn_union_pnl_linked_cash_outcomes(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS TABLE(table_id uuid, hand_number bigint, game_scope jsonb, evidence jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT r.table_id,r.hand_number,r.game_scope,r.evidence
 FROM public.union_pnl_cash_outcome_link_resolutions r
 JOIN public.union_pnl_cash_outcomes o ON o.table_id=r.table_id AND o.hand_number=r.hand_number
 WHERE r.game_scope->>'game_union_id'=p_union_id::text AND o.recognized_at>=p_start AND o.recognized_at<p_end
  AND r.hand_id=o.hand_id AND r.outcome_payload_hash=o.payload_hash AND r.outcome_evidence_md5=md5(o.evidence::text)
  AND r.proof_md5=md5(r.proof::text)
$$;

CREATE FUNCTION public.fn_union_pnl_opening_registration_resolution(p_union_id uuid, p_at timestamp with time zone, p_tournament jsonb, p_registration jsonb) RETURNS SETOF public.union_pnl_opening_registration_resolutions
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT r.* FROM public.union_pnl_opening_registration_resolutions r
 WHERE r.boundary=p_at AND r.registration_id::text=p_registration->>'id' AND r.union_id=p_union_id
  AND p_tournament->>'union_id'=p_union_id::text AND p_registration->>'tournament_id'=p_tournament->>'id'
  AND r.tournament_id::text=p_tournament->>'id' AND r.user_id::text=p_registration->>'user_id'
  AND r.registration_row_md5=md5(p_registration::text) AND r.tournament_row_md5=md5(p_tournament::text)
  AND r.proof_md5=md5(r.proof::text) AND r.proof->>'status'='proven'
$$;

CREATE FUNCTION public.fn_union_pnl_original_flow_evidence(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS TABLE(ledger_id uuid, club_id uuid, user_id uuid, buyins numeric, cashouts numeric, kind text, valid boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 WITH originals AS MATERIALIZED (
  SELECT q.*,q.ledger_snapshot l,(q.game_scope->>'tournament_id')::uuid tournament_id
  FROM public.union_pnl_original_flows q WHERE q.game_scope->>'game_union_id'=p_union_id::text
   AND q.recognized_at>=p_start AND q.recognized_at<p_end
 ), matched AS (
  SELECT q.*,f.id cash_funding_id,f.funding_club_id cash_club,f.user_id cash_user,f.amount cash_amount,
   e.id entry_id,e.funding_club_id entry_club,e.user_id entry_user,e.amount entry_amount,
   c.ledger_id credit_id,c.credited_club_id credit_club,c.user_id credit_user,c.amount credit_amount,
   ret.owners,ret.funding_club_id return_club,ret.user_id return_user,mv.moved_club,mv.moved_user,
   rf.refunds,rf.club refund_club,rf.player refund_user,te.refund_ent,te.refund_ent_user,te.refund_ent_club
  FROM originals q
  -- One-time filter (20261001): a probe only for the flows that can match.
  LEFT JOIN LATERAL (SELECT f.* FROM public.cash_participant_funding_receipts f
   WHERE q.tournament_id IS NULL AND f.source_ledger_id=q.ledger_id OFFSET 0) f ON true
  LEFT JOIN LATERAL (SELECT e.* FROM public.tournament_participant_funding_receipts e
   WHERE q.tournament_id IS NOT NULL AND e.ledger_id=q.ledger_id AND e.asset='chips' AND q.tournament_id=e.tournament_id OFFSET 0) e ON true
  -- fn_union_pnl_tournament_returns(q.tournament_id,NULL,p_start,p_end) for
  -- this flow's ledger only: its two branches verbatim, keyed by the ledger.
  LEFT JOIN LATERAL (
   SELECT c.ledger_id,c.tournament_id,c.user_id,c.credited_club_id,c.amount
   FROM public.tournament_accounting_credit_receipts c
   JOIN public.union_pnl_transaction_frames b ON b.transaction_id=c.transaction_id
   WHERE q.tournament_id IS NOT NULL AND c.ledger_id=q.ledger_id AND c.tournament_id=q.tournament_id
    AND b.observed_at>=p_start AND b.observed_at<p_end
   UNION ALL
   SELECT t.credit_ledger_id,t.tournament_id,t.user_id,t.source_wallet_club_id,t.amount_paid_now
   FROM public.tournament_refund_tranches t
   JOIN public.tournament_participant_funding_receipts r ON r.entitlement_id=t.entitlement_id
   JOIN public.union_pnl_transaction_frames b ON b.transaction_id=t.transaction_id
   WHERE q.tournament_id IS NOT NULL AND t.credit_ledger_id=q.ledger_id AND t.tournament_id=q.tournament_id
    AND b.observed_at>=p_start AND b.observed_at<p_end
    AND NOT EXISTS(SELECT 1 FROM public.tournament_accounting_credit_receipts c2 WHERE c2.ledger_id=t.credit_ledger_id)
  ) c ON true
  LEFT JOIN LATERAL (
   SELECT count(DISTINCT (r.funding_club_id,r.user_id)) owners,min(r.funding_club_id::text)::uuid funding_club_id,min(r.user_id::text)::uuid user_id
   FROM public.cash_participant_funding_receipts r
   WHERE r.table_id=(q.l->>'table_id')::uuid AND r.operation_kind='buyin'
    AND q.tournament_id IS NULL AND q.l->>'from_type'='table_stack'
    AND r.account_type=q.l->>'to_type' AND r.account_entity_id=(q.l->>'to_entity_id')::uuid
    AND r.funding_club_id=(q.l->>'club_id')::uuid
    AND (EXISTS(SELECT 1 FROM public.union_pnl_inventory_events i WHERE i.transaction_id=q.transaction_id AND i.source_name='table_seats'
      AND COALESCE(i.after_row,i.before_row)->>'occupancy_id'=r.occupancy_id::text
      AND COALESCE(i.after_row,i.before_row)->>'table_id'=r.table_id::text)
     OR EXISTS(SELECT 1 FROM public.cash_funding_application_receipts a JOIN public.cash_participant_funding_receipts original ON original.id=a.funding_receipt_id
       WHERE a.transaction_id=q.transaction_id AND original.occupancy_id=r.occupancy_id AND a.refunded=(q.l->>'amount')::numeric))
  ) ret ON true
  -- A seat cashed out after it arrived by a table move holds chips whose
  -- original buy-in is on the source occupancy, not this one. The occupancy
  -- the cash-out vacated (its seat row in the same original transaction,
  -- carrying exactly the cashed-out stack) is traced through its move receipts
  -- by fn_cash_original_funding_lineage, the proof the boundaries and hands
  -- already use; the owner is its one original buy-in's club and player.
  LEFT JOIN LATERAL (
   SELECT CASE WHEN lin.v->'issues'='[]'::jsonb AND jsonb_array_length(lin.v->'moves')>0 AND own.receipts>0 AND own.buyins=1
     AND own.clubs=1 AND own.users=1 AND own.club::text=q.l->>'club_id' AND own.player::text=q.l->>'to_entity_id'
     THEN own.club END moved_club,
    CASE WHEN lin.v->'issues'='[]'::jsonb AND jsonb_array_length(lin.v->'moves')>0 AND own.receipts>0 AND own.buyins=1
     AND own.clubs=1 AND own.users=1 AND own.club::text=q.l->>'club_id' AND own.player::text=q.l->>'to_entity_id'
     THEN own.player END moved_user
   FROM (SELECT min(i.before_row::text)::jsonb seat,count(*) n FROM public.union_pnl_inventory_events i
     WHERE q.tournament_id IS NULL AND q.l->>'from_type'='table_stack' AND q.l->>'to_type'='player_wallet'
      AND ret.owners IS DISTINCT FROM 1
      AND i.transaction_id=q.transaction_id AND i.source_name='table_seats' AND i.before_row->>'table_id'=q.l->>'table_id'
      AND i.before_row->>'user_id'=q.l->>'to_entity_id' AND i.before_row->'left_at'='null'::jsonb
      AND i.after_row->>'left_at' IS NOT NULL) s
   CROSS JOIN LATERAL (SELECT public.fn_cash_original_funding_lineage((s.seat->>'user_id')::uuid,(s.seat->>'table_id')::uuid,(s.seat->>'id')::uuid,
     (s.seat->>'occupancy_id')::uuid,(s.seat->>'joined_at')::timestamptz,q.recognized_at,false) v) lin
   CROSS JOIN LATERAL (SELECT count(*) receipts,count(*) FILTER(WHERE r.operation_kind='buyin') buyins,count(DISTINCT r.funding_club_id) clubs,
     count(DISTINCT r.user_id) users,min(r.funding_club_id::text)::uuid club,min(r.user_id::text)::uuid player
    FROM jsonb_array_elements(lin.v->'funding_receipts') ref JOIN public.cash_participant_funding_receipts r ON r.id=(ref->>'id')::uuid) own
   WHERE q.tournament_id IS NULL AND q.l->>'from_type'='table_stack' AND q.l->>'to_type'='player_wallet' AND ret.owners IS DISTINCT FROM 1
    AND s.n=1 AND public.fn_pnl_evidence_cents(s.seat->'stack') IS NOT DISTINCT FROM (q.l->>'amount')::numeric
  ) mv ON true
  -- A pending add-on returned unapplied is a refund of this player's own
  -- escrowed chips. Its wallet credit can carry no refund category: it runs
  -- inside the hand's post-commit obligations, after atomic_distribute_rake
  -- has declared that transaction's ledger context, so the audit labels it
  -- player_funding under the rake settlement. The application receipt
  -- written in the same transaction proves it: exactly one refund of this
  -- amount from a funding receipt of this player, club and table.
  LEFT JOIN LATERAL (
   SELECT count(*) refunds,min(o.funding_club_id::text)::uuid club,min(o.user_id::text)::uuid player
   FROM public.cash_funding_application_receipts a JOIN public.cash_participant_funding_receipts o ON o.id=a.funding_receipt_id
   WHERE a.transaction_id=q.transaction_id AND a.refunded>0 AND a.refunded=(q.l->>'amount')::numeric
    AND a.pending_addon_id IS NOT DISTINCT FROM o.pending_addon_id AND a.original_occupancy_id=o.occupancy_id
    AND o.table_id=(q.l->>'table_id')::uuid AND o.account_type='player_wallet' AND o.account_entity_id=(q.l->>'to_entity_id')::uuid
    AND o.funding_club_id=(q.l->>'club_id')::uuid AND o.user_id=(q.l->>'to_entity_id')::uuid
    AND q.tournament_id IS NULL AND q.l->>'from_type'='table_stack' AND q.l->>'to_type'='player_wallet'
    AND q.l->>'category'='player_funding'
  ) rf ON true
  -- A seat won in a satellite and later refunded by the target tournament
  -- (cancelled, or the seat released) pays the seat's value back to the
  -- player's wallet from the target's prize liability. That seat was never a
  -- wallet-funded entry of the target, so no tournament credit receipt exists
  -- for it; its proof is the refund entitlement the payout is keyed by: same
  -- tournament, player, wallet club and gross, and the seat's owning club as
  -- resolved from its satellite registration.
  LEFT JOIN LATERAL (
   SELECT t.id refund_ent,t.user_id refund_ent_user,t.refund_wallet_club_id refund_ent_club
   FROM public.tournament_refund_entitlements t
   WHERE q.tournament_id IS NOT NULL AND t.tournament_id=q.tournament_id
    AND q.l->>'idempotency_key'='tourney:'||t.tournament_id::text||':refund-entitlement:'||t.id::text
    AND t.entitlement_kind IN('satellite_seat','wallet_charge') AND t.gross=(q.l->>'amount')::numeric
    AND t.user_id::text=q.l->>'to_entity_id' AND t.refund_wallet_club_id::text=q.l->>'club_id'
    AND q.l->>'from_type'='prize_liability' AND q.l->>'to_type'='player_wallet' AND q.l->>'category'='refund'
    AND CASE t.entitlement_kind
     WHEN 'satellite_seat' THEN public.fn_union_pnl_satellite_seat_owner(t.registration_id,NULL)=t.refund_wallet_club_id
     -- A pre-capture wallet entry refunded by cancellation (20261006154000):
     -- its entitlement's source ledger is the entry proven at the opening
     -- boundary of the refund's own week, for this exact registration, club
     -- and gross.
     WHEN 'wallet_charge' THEN t.source_ledger_id IS NOT NULL AND (SELECT count(*) FROM public.union_pnl_opening_registration_resolutions r
       WHERE r.boundary=public.fn_union_week_start(q.recognized_at) AND r.union_id=p_union_id AND r.tournament_id=t.tournament_id AND r.user_id=t.user_id
        AND r.owning_club_id=t.refund_wallet_club_id AND r.entries=1 AND r.entry_amount=t.gross AND r.returned=0
        AND r.proof_md5=md5(r.proof::text)
        AND r.proof->'entry_ledger' @> jsonb_build_array(jsonb_build_object('ledger_id',t.source_ledger_id::text)))=1
     ELSE false END
  ) te ON true
 ), projected AS (
  SELECT *,CASE WHEN cash_funding_id IS NOT NULL THEN 'cash_funding' WHEN owners=1 OR moved_club IS NOT NULL OR refunds=1 THEN 'cash_return'
    WHEN entry_id IS NOT NULL THEN 'tournament_funding' WHEN credit_id IS NOT NULL OR refund_ent IS NOT NULL THEN 'tournament_return' ELSE 'unsupported' END k,
   COALESCE(cash_club,CASE WHEN moved_club IS NOT NULL THEN moved_club WHEN owners=1 THEN return_club ELSE refund_club END,entry_club,credit_club,refund_ent_club) owner_club,
   COALESCE(cash_user,CASE WHEN moved_club IS NOT NULL THEN moved_user WHEN owners=1 THEN return_user ELSE refund_user END,entry_user,credit_user,refund_ent_user) owner_user
  FROM matched
 ) SELECT ledger_id,owner_club,owner_user,
  CASE WHEN k IN('cash_funding','tournament_funding') THEN (l->>'amount')::numeric ELSE 0 END,
  CASE WHEN k IN('cash_return','tournament_return') THEN (l->>'amount')::numeric ELSE 0 END,k,
  (l->>'status'='posted' AND public.fn_pnl_evidence_cents(l->'amount')>0 AND owner_club IS NOT NULL AND owner_user IS NOT NULL
   AND owner_club::text=l->>'club_id' AND game_scope->>'asset'='chips' AND game_scope->'unit_scale'='2'::jsonb
   AND CASE k
    WHEN 'cash_funding' THEN cash_amount=(l->>'amount')::numeric AND l->>'to_type'='table_stack' AND l->>'category' IN('buyin','rebuy','addon','horse_funding')
    WHEN 'cash_return' THEN (owners=1 OR moved_club IS NOT NULL OR (refunds=1 AND l->>'category'='player_funding')) AND l->>'from_type'='table_stack' AND (l->>'category' IN('cashout','table_cashout','refund')
     OR (l->>'category'='player_funding' AND refunds=1 AND refund_club=owner_club AND refund_user=owner_user))
    WHEN 'tournament_funding' THEN entry_amount=(l->>'amount')::numeric AND l->>'to_type'='prize_liability' AND l->>'category' IN('tournament_buyin','rebuy','addon')
    WHEN 'tournament_return' THEN (credit_amount=(l->>'amount')::numeric OR (credit_id IS NULL AND refund_ent IS NOT NULL)) AND l->>'from_type'='prize_liability' AND l->>'category' IN('tournament_prize','prize','bounty','refund','tournament_refund')
    ELSE false END) IS TRUE
 FROM projected;
$$;

CREATE FUNCTION public.fn_union_pnl_projection_ready(p_projection text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT COALESCE((SELECT b.completed_at IS NOT NULL FROM public.union_pnl_projection_build b WHERE b.projection=p_projection),false)
$$;

CREATE FUNCTION public.fn_union_pnl_qualified_clubs(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE proof jsonb;
BEGIN
 proof:=public.fn_union_pnl_evidence_report(p_union_id,p_start,p_end);
 IF proof->'report_version' IS DISTINCT FROM '1'::jsonb OR proof->>'status' IS DISTINCT FROM 'ready'
  OR proof->'basis_certified' IS DISTINCT FROM 'true'::jsonb OR proof->'issues' IS DISTINCT FROM '[]'::jsonb THEN
  RAISE EXCEPTION 'union_pnl_basis_uncertified' USING ERRCODE='55000',DETAIL=COALESCE((proof->'issues')::text,'missing proof');
 END IF;
 RETURN proof;
END $$;

CREATE FUNCTION public.fn_union_pnl_satellite_seat_owner(p_registration_id uuid, p_tournament_id uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
 WITH reg AS (
  SELECT e.after_row r FROM public.union_pnl_inventory_events e
  WHERE e.source_name='tournament_players' AND e.row_id=p_registration_id ORDER BY e.event_id LIMIT 1
 ), who AS (
  SELECT (r->>'user_id')::uuid user_id,(r->>'source_satellite_id')::uuid satellite_id,(r->>'registered_at')::timestamptz registered_at,
   (r->>'tournament_id')::uuid target_id
  FROM reg WHERE (p_tournament_id IS NULL OR r->>'tournament_id'=p_tournament_id::text)
   AND r->>'source_satellite_id' IS NOT NULL AND r->>'user_id' IS NOT NULL AND r->>'tournament_id' IS NOT NULL
 ), award AS (
  SELECT a.tournament_id,a.user_id FROM who w
  JOIN public.tournament_satellite_awards a ON a.tournament_id=w.satellite_id AND a.user_id=w.user_id
  JOIN public.tournament_satellite_settlements s ON s.tournament_id=a.tournament_id AND s.target_id=w.target_id
  WHERE (a.delivery_kind='seat' AND a.registration_id=p_registration_id)
   OR (a.delivery_kind='ticket' AND a.registration_id IS NULL AND EXISTS(SELECT 1 FROM public.tournament_tickets t WHERE t.id=a.ticket_id
     AND t.holder_id=w.user_id AND t.source_satellite_id=w.satellite_id AND t.source_tournament_id=w.target_id
     AND t.status='redeemed' AND t.redemption_mode='tournament_entry_only' AND t.redeemed_at=w.registered_at))
 ), entry AS (
  SELECT count(*) n,count(DISTINCT r.funding_club_id) clubs,min(r.funding_club_id::text)::uuid club,
   count(*) FILTER(WHERE r.operation='entry') entries,
   count(*) FILTER(WHERE r.asset IS DISTINCT FROM 'chips' OR r.amount IS NULL OR r.amount<=0 OR r.funding_club_id IS NULL OR NOT EXISTS(
    SELECT 1 FROM public.chip_ledger l WHERE l.id=r.ledger_id AND l.status='posted' AND l.from_type='player_wallet' AND l.from_entity_id=r.user_id
     AND l.to_type='prize_liability' AND l.to_entity_id=r.tournament_id AND l.tournament_id=r.tournament_id AND l.amount=r.amount
     AND l.club_id=r.funding_club_id AND l.category IN ('tournament_buyin','rebuy','addon') AND l.row_hash IS NOT NULL)) bad
  FROM award a JOIN public.tournament_participant_funding_receipts r ON r.tournament_id=a.tournament_id AND r.user_id=a.user_id
 )
 SELECT CASE WHEN (SELECT count(*) FROM award)=1 AND e.n>0 AND e.entries>=1 AND e.clubs=1 AND e.bad=0 THEN e.club END FROM entry e
$$;

CREATE FUNCTION public.fn_union_pnl_touched_registrations(p_start timestamp with time zone, p_end timestamp with time zone, p_projected boolean) RETURNS TABLE(registration_id uuid, touched_tournament_id text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF p_projected THEN
  RETURN QUERY SELECT i.row_id,i.tournament_id FROM public.union_pnl_inventory_touches i
   WHERE i.source_name='tournament_players' AND i.frame_observed_at>=p_start AND i.frame_observed_at<p_end
    AND i.observed_at>=p_start AND i.observed_at<p_end;
 ELSE
  RETURN QUERY SELECT i.row_id,COALESCE(i.after_row,i.before_row)->>'tournament_id' FROM public.union_pnl_inventory_events i
   JOIN public.union_pnl_transaction_frames b ON b.transaction_id=i.transaction_id
   WHERE i.source_name='tournament_players' AND b.observed_at>=p_start AND b.observed_at<p_end
    AND i.observed_at>=p_start AND i.observed_at<p_end;
 END IF;
END $$;

CREATE FUNCTION public.fn_union_pnl_tournament_entry_club_of(p_asset text, p_amount numeric, p_funding_club_id uuid, p_ledger_id uuid, p_entitlement_id uuid, p_registration_snapshot jsonb) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT CASE WHEN p_asset='chips' AND p_amount>0 THEN p_funding_club_id
  WHEN p_asset='chips' AND p_amount=0 AND p_ledger_id IS NULL AND p_entitlement_id IS NULL
   AND p_registration_snapshot->>'source_satellite_id' IS NULL
   AND p_registration_snapshot->'is_satellite_qualifier'='false'::jsonb
   THEN (p_registration_snapshot->>'club_id')::uuid END;
$$;

CREATE FUNCTION public.fn_union_pnl_tournament_in_union(p_tournament_id text, p_union_id uuid, p_projected boolean) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
BEGIN
 IF p_projected THEN
  RETURN EXISTS(SELECT 1 FROM public.union_pnl_inventory_touches t WHERE t.source_name='tournaments'
   AND t.row_id=CASE WHEN p_tournament_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN p_tournament_id::uuid END
   AND t.row_id::text=p_tournament_id
   AND t.union_id=p_union_id::text);
 END IF;
 RETURN EXISTS(SELECT 1 FROM public.union_pnl_inventory_events t WHERE t.source_name='tournaments'
  AND t.row_id=CASE WHEN p_tournament_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN p_tournament_id::uuid END
  AND t.row_id::text=p_tournament_id
  AND COALESCE(t.after_row,t.before_row)->>'union_id'=p_union_id::text);
END $_$;

CREATE FUNCTION public.fn_union_pnl_week_bbj_stack_awards(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS TABLE(club_id uuid, user_id uuid, amount numeric, payout_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT (pp.p->>'earning_club_id')::uuid, r.user_id, r.amount, r.payout_id
 FROM public.bbj_payout_recipients r
 JOIN public.bbj_payouts b ON b.id=r.payout_id
 JOIN public.union_pnl_cash_outcomes o ON o.table_id=b.table_id AND o.hand_number=b.hand_number
 CROSS JOIN LATERAL (SELECT p FROM jsonb_array_elements(COALESCE(o.evidence->'participants','[]')) p
  WHERE p->>'user_id'=r.user_id::text LIMIT 1) pp
 WHERE r.created_at>=p_start AND r.created_at<p_end AND r.amount>0
  AND o.game_scope->>'game_union_id'=p_union_id::text
  -- a share paid to the wallet of a departed recipient never reached the felt
  AND NOT EXISTS(SELECT 1 FROM public.wallet_credit_idempotency w
   WHERE w.key='bbj:'||r.payout_id::text||':'||r.user_id::text)
$$;

CREATE FUNCTION public.fn_union_pnl_week_hand_lines(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_projected boolean) RETURNS TABLE(hand_accepted_rake text, hand_participants jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF p_projected THEN
  RETURN QUERY SELECT h.accepted_rake,h.participants FROM public.union_pnl_cash_outcome_touches h
   WHERE h.game_union_id=p_union_id::text AND h.recognized_at>=p_start AND h.recognized_at<p_end;
 ELSE
  RETURN QUERY SELECT o.evidence->>'accepted_rake',o.evidence->'participants' FROM public.union_pnl_cash_outcomes o
   WHERE o.game_scope->>'game_union_id'=p_union_id::text AND o.recognized_at>=p_start AND o.recognized_at<p_end;
 END IF;
END $$;

CREATE FUNCTION public.fn_union_pnl_week_shaped_hands(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_projected boolean) RETURNS SETOF public.union_pnl_cash_outcomes
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF p_projected THEN
  RETURN QUERY SELECT o.* FROM public.union_pnl_cash_outcome_touches h
   CROSS JOIN LATERAL (SELECT q.* FROM public.union_pnl_cash_outcomes q WHERE q.table_id=h.table_id AND q.hand_number=h.hand_number) o
   WHERE h.game_union_id=p_union_id::text AND h.recognized_at>=p_start AND h.recognized_at<p_end AND h.shaped
    AND o.game_scope->>'game_union_id'=p_union_id::text AND o.recognized_at>=p_start AND o.recognized_at<p_end
    AND (o.evidence->>'status' IS DISTINCT FROM 'ready' OR o.evidence->'basis_certified' IS DISTINCT FROM 'true'::jsonb
     OR o.evidence->'all_players_included' IS DISTINCT FROM 'true'::jsonb OR o.evidence->'game_scope' IS DISTINCT FROM o.game_scope);
 ELSE
  RETURN QUERY SELECT o.* FROM public.union_pnl_cash_outcomes o WHERE o.game_scope->>'game_union_id'=p_union_id::text AND o.recognized_at>=p_start AND o.recognized_at<p_end
   AND (o.evidence->>'status' IS DISTINCT FROM 'ready' OR o.evidence->'basis_certified' IS DISTINCT FROM 'true'::jsonb
    OR o.evidence->'all_players_included' IS DISTINCT FROM 'true'::jsonb OR o.evidence->'game_scope' IS DISTINCT FROM o.game_scope);
 END IF;
END $$;

CREATE FUNCTION public.fn_union_pnl_week_union_credits(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_projected boolean) RETURNS TABLE(credit_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF p_projected THEN
  RETURN QUERY SELECT t.id FROM public.union_pnl_credit_touches t
   WHERE t.union_id=p_union_id::text AND t.frame_observed_at>=p_start AND t.frame_observed_at<p_end;
 ELSE
  RETURN QUERY SELECT c.id FROM public.tournament_accounting_credit_receipts c
   JOIN public.union_pnl_transaction_frames b ON b.transaction_id=c.transaction_id
   WHERE c.tournament_snapshot->>'union_id'=p_union_id::text AND b.observed_at>=p_start AND b.observed_at<p_end;
 END IF;
END $$;

CREATE FUNCTION public.fn_union_prev_week_start(p_at timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT (date_trunc('week', (p_at AT TIME ZONE 'America/Los_Angeles')) - interval '7 days')
           AT TIME ZONE 'America/Los_Angeles';
$$;

CREATE FUNCTION public.fn_union_rake_rollup_refresh_day(p_union_id uuid, p_day date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start timestamptz := (p_day::timestamp AT TIME ZONE 'UTC');
  v_end   timestamptz := ((p_day + 1)::timestamp AT TIME ZONE 'UTC');
  v_records integer;
BEGIN
  IF v_end > now() THEN
    RAISE EXCEPTION 'union rake rollup: day % is not complete (UTC); refusing to finalize', p_day;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('union_rake_rollup:' || p_union_id::text || ':' || p_day::text, 42));

  DELETE FROM union_rake_rollup_days
   WHERE union_id = p_union_id AND day = p_day;  -- cascades to detail

  -- counts BOTH legs, so the freshness test below can detect a cash-only day
  SELECT (SELECT count(*)
            FROM rake_records r
            JOIN tables t ON t.id = r.table_id AND t.union_id = p_union_id
           WHERE r.created_at >= v_start AND r.created_at < v_end
             AND r.player_contributions IS NOT NULL AND r.rake_amount > 0)
       + (SELECT count(*)
            FROM rake_records r
           WHERE r.is_tournament
             AND r.created_at >= v_start AND r.created_at < v_end
             AND r.rake_amount <> 0
             AND (r.club_id = p_union_id
                  OR EXISTS (SELECT 1 FROM union_clubs uc
                              WHERE uc.union_id = p_union_id AND uc.club_id = r.club_id)))
    INTO v_records;

  INSERT INTO union_rake_rollup_days (union_id, day, records_seen)
  VALUES (p_union_id, p_day, v_records);

  INSERT INTO union_rake_paid_daily_user (union_id, day, user_id, rake_amount)
  WITH expanded AS (
    /* ONE DAY, NOT EVERY RAKE RECORD (2026-09-30). The hand's total comes
       from a LATERAL SUM over the same contribution rows. It used to be
       a window partitioned by the rake record id, and to feed it in id order
       the planner walked rake_records_pkey across the whole table with
       created_at as a filter: > 55 s for one day, and the hourly job died at
       its 2-minute limit for 54 runs. Same number, no ordering, 1.1 s. */
    SELECT (e.key)::uuid AS user_id,
           r.rake_amount * (e.value)::numeric / NULLIF(hand.total, 0) AS share
      FROM rake_records r
      JOIN tables t ON t.id = r.table_id AND t.union_id = p_union_id
      CROSS JOIN LATERAL (SELECT SUM((x.value)::numeric) AS total
                            FROM jsonb_each_text(r.player_contributions) x) hand
      CROSS JOIN LATERAL jsonb_each_text(r.player_contributions) e(key, value)
     WHERE r.created_at >= v_start AND r.created_at < v_end
       AND r.player_contributions IS NOT NULL AND r.rake_amount > 0
  ),
  all_legs AS (
    SELECT expanded.user_id, expanded.share FROM expanded WHERE expanded.share IS NOT NULL
    UNION ALL
    SELECT u.user_id, u.rake_amount
      FROM fn_union_tournament_rake_by_user(p_union_id, v_start, v_end) u
  )
  ,
  per_user AS (
    SELECT all_legs.user_id, SUM(all_legs.share) AS exact
      FROM all_legs GROUP BY all_legs.user_id
  ),
  /* WHOLE CENTS, AND THE DAY STILL ADDS UP (2026-09-09). A share is a
     quotient and carries twenty decimal places; the table takes two. Each
     user is rounded and the rounding residue is given to the largest share,
     so no user holds a fraction of a cent and the day's total is still the
     rake that was taken. */
  ranked AS (
    SELECT pu.user_id, pu.exact, round(pu.exact, 2) AS cents,
           row_number() OVER (ORDER BY pu.exact DESC, pu.user_id) AS rn
      FROM per_user pu
  ),
  day_total AS (
    SELECT round(sum(exact), 2) AS exact_total, sum(cents) AS cents_total FROM ranked
  )
  SELECT p_union_id, p_day, k.user_id,
         k.cents + CASE WHEN k.rn = 1 THEN (t.exact_total - t.cents_total) ELSE 0 END
    FROM ranked k CROSS JOIN day_total t;
END;
$$;

CREATE FUNCTION public.fn_union_setting(p_union_id uuid, p_key text, p_default numeric) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE((settings ->> p_key)::numeric, p_default)
    FROM unions WHERE id = p_union_id;
$$;

CREATE FUNCTION public.fn_union_settle_player_pnl(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_dry_run boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_settlement_id uuid; v_prev jsonb; r record;
  v_results jsonb := '[]'::jsonb;
  v_collect_total numeric := 0; v_pay_total numeric := 0; v_unpaid_total numeric := 0;
  v_treasury numeric; v_take numeric; v_union_balance numeric; v_pay numeric; v_owed numeric;
  v_period_id uuid; v_scale numeric := 1; v_winners_total numeric := 0; v_residual numeric := 0;
  v_ca_id uuid; v_ca_state text; v_walk boolean := false;
  v_expected_balance numeric; v_err text;
  v_existing record; v_floor timestamptz; v_needed numeric; v_initial_union numeric;
  v_prior_ledger jsonb; v_receipt_count int;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
  IF p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'missing_arguments');
  END IF;
  IF NOT isfinite(p_start) OR NOT isfinite(p_end) OR p_end <= p_start OR p_end>now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_period');
  END IF;

  SELECT earliest_period_start INTO v_floor FROM public.union_settlement_floor WHERE union_id=p_union_id;
  IF v_floor IS NOT NULL AND p_start<v_floor THEN
    RETURN jsonb_build_object('success',false,'error','before_settlement_floor','settlement_floor',v_floor);
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.unions WHERE id=p_union_id) THEN
    RETURN jsonb_build_object('success',false,'error','unknown_union');
  END IF;
  PERFORM public.fn_union_pnl_closed_book_barrier(p_end);
  -- Share the weekly scope lock, then serialize overlapping P&L callers for this union.
  PERFORM pg_advisory_xact_lock(hashtextextended('union-accounting:'||p_union_id::text||':'||extract(epoch FROM p_start)::text||':'||extract(epoch FROM p_end)::text,0));
  PERFORM pg_advisory_xact_lock(hashtextextended('union-player-pnl:'||p_union_id::text,0));
  -- Preview, replay and payment share one quality gate after original auth,
  -- window/floor validation and scope locks. No historical record is changed.
  PERFORM public.fn_require_union_pnl_evidence(p_union_id,p_start,p_end);
  SELECT * INTO v_existing FROM public.union_pnl_settlements
   WHERE union_id=p_union_id AND status IN('settled','in_progress')
    AND period_start<p_end AND period_end>p_start
   ORDER BY period_start,id LIMIT 1 FOR UPDATE;
  IF FOUND AND NOT p_dry_run THEN
    IF v_existing.period_start=p_start AND v_existing.period_end=p_end
      AND v_existing.status='settled' AND v_existing.total_unpaid=0
      AND v_existing.total_collected>=0 AND v_existing.total_paid>=0 THEN
      RETURN jsonb_build_object('success',true,'already_settled',true,'settlement_id',v_existing.id,
       'union_id',p_union_id,'period_start',p_start,'period_end',p_end,
       'total_collected',v_existing.total_collected,'total_paid',v_existing.total_paid,'total_unpaid',0);
    END IF;
    RETURN jsonb_build_object('success',false,'error',CASE
      WHEN v_existing.status='settled' AND v_existing.total_unpaid IS DISTINCT FROM 0 THEN 'legacy_partial_pnl_requires_reconciliation'
      WHEN v_existing.status='in_progress' THEN 'pnl_claim_requires_reconciliation'
      ELSE 'pnl_period_overlap' END,'settlement_id',v_existing.id,
      'existing_period_start',v_existing.period_start,'existing_period_end',v_existing.period_end,
      'total_unpaid',v_existing.total_unpaid);
  END IF;

  -- These rows already reconcile accepted outcomes, original cash flows,
  -- exact boundary holdings, tournament deferral and the one rake basis.
  v_prev:=public.fn_union_pnl_qualified_clubs(p_union_id,p_start,p_end);
  CREATE TEMP TABLE IF NOT EXISTS _pnl_tmp (
    club_id uuid PRIMARY KEY,net numeric,seated numeric,detail jsonb,opening_treasury numeric) ON COMMIT DROP;
  DELETE FROM pg_temp._pnl_tmp WHERE true;
  INSERT INTO pg_temp._pnl_tmp(club_id,net,seated,detail)
  SELECT (x->>'club_id')::uuid,(x->>'net')::numeric,(x->>'seated_end')::numeric,x
  FROM jsonb_array_elements(v_prev->'clubs') x;

  SELECT COALESCE(round(SUM(net), 2), 0) INTO v_residual FROM pg_temp._pnl_tmp;

  IF p_dry_run THEN
    SELECT jsonb_agg(detail ORDER BY club_id) INTO v_results FROM pg_temp._pnl_tmp;
    RETURN jsonb_build_object('success', true, 'dry_run', true, 'union_id', p_union_id,
      'house_residual', v_residual, 'imbalance', v_residual,
      'clubs', COALESCE(v_results, '[]'::jsonb));
  END IF;

  IF NOT EXISTS(SELECT 1 FROM pg_temp._pnl_tmp) THEN
    RETURN jsonb_build_object('success',false,'error','pnl_no_club_basis');
  END IF;
  IF EXISTS(SELECT 1 FROM pg_temp._pnl_tmp WHERE net IS NULL OR net::text IN('NaN','Infinity','-Infinity') OR net<>round(net,2)) THEN
    RETURN jsonb_build_object('success',false,'error','pnl_invalid_basis');
  END IF;
  -- A final or advanced state with no matching fully-paid claim cannot be replayed.
  SELECT id,state INTO v_ca_id,v_ca_state FROM public.ca_settlements
   WHERE settlement_type='union_player_pnl'
    AND (idempotency_key='pnl:'||p_union_id::text||':'||extract(epoch FROM p_start)::bigint
      OR external_ref=p_union_id::text||':'||to_char(p_start,'YYYY-MM-DD"T"HH24:MI:SSOF'))
   ORDER BY id LIMIT 1 FOR UPDATE;
  IF FOUND AND v_ca_state NOT IN('failed','open') THEN
    RETURN jsonb_build_object('success',false,'error','pnl_journal_requires_reconciliation','journal_id',v_ca_id,'state',v_ca_state);
  END IF;
  v_ca_id:=NULL; v_ca_state:=NULL;
  UPDATE union_pnl_settlements SET status = 'superseded' 
   WHERE union_id = p_union_id AND period_start = p_start AND status = 'needs_review';

  BEGIN
    INSERT INTO union_pnl_settlements (union_id, period_start, period_end, status)
    VALUES (p_union_id, p_start, p_end, 'in_progress') RETURNING id INTO v_settlement_id;
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('success',false,'error','pnl_claim_conflict','union_id',p_union_id,'period_start',p_start);
  END;

  -- ZERO-DRIFT phase 3: register on the settlement state machine (resume a
  -- prior failed run; leave an unexpected 'final' row untouched).
  INSERT INTO public.ca_settlements (settlement_type, external_ref, state, union_id, idempotency_key)
  VALUES ('union_player_pnl', p_union_id::text || ':' || to_char(p_start, 'YYYY-MM-DD"T"HH24:MI:SSOF'),
          'open', p_union_id, 'pnl:' || p_union_id::text || ':' || extract(epoch from p_start)::bigint)
  ON CONFLICT (settlement_type, external_ref) DO NOTHING
  RETURNING id INTO v_ca_id;
  IF v_ca_id IS NULL THEN
    SELECT id, state INTO v_ca_id, v_ca_state FROM public.ca_settlements
     WHERE settlement_type = 'union_player_pnl'
       AND external_ref = p_union_id::text || ':' || to_char(p_start, 'YYYY-MM-DD"T"HH24:MI:SSOF');
    IF v_ca_state = 'failed' THEN
      UPDATE public.ca_settlements SET state = 'open', error_detail = NULL WHERE id = v_ca_id;
      v_walk := true;
    ELSIF v_ca_state = 'open' THEN
      v_walk := true;
    END IF; -- any later state: leave the machine alone, evidence stands
  ELSE
    v_walk := true;
  END IF;

  -- A failed attempt preserves only the claim and incident; period/invoice/ledger writes roll back.
  BEGIN
  -- (C) FIX: every club in the settlement gets a period row for THIS window.
  INSERT INTO settlement_periods (club_id, union_id, period_number, year, start_at, end_at, status)
  SELECT t.club_id, p_union_id,
         EXTRACT(week FROM p_start)::int, EXTRACT(isoyear FROM p_start)::int,
         p_start, p_end, 'processing'
    FROM pg_temp._pnl_tmp t
   WHERE NOT EXISTS (
     SELECT 1 FROM settlement_periods sp
      WHERE sp.club_id = t.club_id AND sp.union_id = p_union_id
        AND sp.start_at = p_start AND sp.end_at = p_end);

    IF v_walk THEN
      UPDATE public.ca_settlements SET state = 'locked_for_calculation' WHERE id = v_ca_id;
      UPDATE public.ca_settlements SET state = 'calculated',
        totals = jsonb_build_object('house_residual', v_residual,
                                    'clubs', (SELECT count(*) FROM pg_temp._pnl_tmp))
        WHERE id = v_ca_id;
    END IF;

    SELECT chip_balance INTO v_union_balance FROM union_wallets WHERE union_id = p_union_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'pnl_union_wallet_missing'; END IF;

    -- Freeze every participating treasury in stable order before the first leg.
    PERFORM c.id FROM public.clubs c JOIN pg_temp._pnl_tmp t ON t.club_id=c.id ORDER BY c.id FOR UPDATE OF c;
    UPDATE pg_temp._pnl_tmp t SET opening_treasury=c.chip_treasury FROM public.clubs c WHERE c.id=t.club_id;
    IF EXISTS(SELECT 1 FROM pg_temp._pnl_tmp WHERE opening_treasury IS NULL
      OR opening_treasury::text IN('NaN','Infinity','-Infinity') OR opening_treasury<0
      OR opening_treasury<>round(opening_treasury,2))
      OR v_union_balance IS NULL OR v_union_balance::text IN('NaN','Infinity','-Infinity')
      OR v_union_balance<0 OR v_union_balance<>round(v_union_balance,2) THEN
      RAISE EXCEPTION 'pnl_invalid_funding_balance' USING ERRCODE='23514';
    END IF;
    SELECT COALESCE(sum(-net),0) INTO v_needed FROM pg_temp._pnl_tmp WHERE net<0;
    IF EXISTS(SELECT 1 FROM pg_temp._pnl_tmp WHERE net<0 AND opening_treasury < -net) THEN
      RAISE EXCEPTION 'pnl_club_funding_shortfall' USING DETAIL=(
        SELECT jsonb_agg(jsonb_build_object('club_id',club_id,'owed',-net,'available',opening_treasury) ORDER BY club_id)::text
         FROM pg_temp._pnl_tmp WHERE net<0 AND opening_treasury < -net);
    END IF;
    v_initial_union:=v_union_balance;
    -- ZERO-DRIFT phase 3 validation before any chips move.
    SELECT COALESCE(SUM(net), 0) INTO v_winners_total FROM pg_temp._pnl_tmp WHERE net > 0;
    IF v_union_balance+v_needed<v_winners_total THEN
      RAISE EXCEPTION 'pnl_union_funding_shortfall' USING DETAIL=jsonb_build_object('owed',v_winners_total,'available_after_collection',v_union_balance+v_needed)::text;
    END IF;
    IF v_walk THEN
      UPDATE public.ca_settlements SET state = 'validated' WHERE id = v_ca_id;
    END IF;

    -- ZERO-DRIFT phase 3: P&L legs journal as pnl_settlement vs the union
    -- wallet, single-posted from the club-treasury side.
    v_prior_ledger:=jsonb_build_object('category',current_setting('app.ledger_category',true),'counterparty',current_setting('app.ledger_counterparty',true),'entity',current_setting('app.ledger_counterparty_entity',true),'settlement',current_setting('app.ledger_settlement',true),'autoskip',current_setting('app.ledger_autoskip_union_wallets',true));
    PERFORM set_config('app.ledger_category', 'pnl_settlement', true);
    PERFORM set_config('app.ledger_counterparty', 'union_wallet', true);
    PERFORM set_config('app.ledger_counterparty_entity', p_union_id::text, true);
    PERFORM set_config('app.ledger_counterparty_label', 'union_wallets.chip_balance', true);
    PERFORM set_config('app.ledger_settlement', COALESCE(v_ca_id::text, ''), true);
    PERFORM set_config('app.ledger_autoskip_union_wallets', '1', true);

    FOR r IN SELECT * FROM pg_temp._pnl_tmp WHERE net < 0 ORDER BY club_id LOOP
      v_owed := round(-r.net, 2);
      SELECT chip_treasury INTO v_treasury FROM clubs WHERE id = r.club_id FOR UPDATE;
      v_take := v_owed;
      IF v_take > v_owed OR v_take < 0 THEN
        RAISE EXCEPTION 'pnl validation: collect leg out of bounds (take % owed %)', v_take, v_owed;
      END IF;
      IF v_take > 0 THEN
        UPDATE clubs SET chip_treasury = chip_treasury - v_take WHERE id = r.club_id;
        v_union_balance := v_union_balance + v_take;
        UPDATE union_wallets SET chip_balance = v_union_balance WHERE union_id = p_union_id;
        v_collect_total := v_collect_total + v_take;
        INSERT INTO union_wallet_transactions (union_id, wallet, direction, amount, balance_after, tx_type, club_id, notes)
        VALUES (p_union_id, 'chip_balance', 'credit', v_take, v_union_balance, 'player_pnl_collect', r.club_id,
                'Weekly player P&L: collected from club (owed ' || v_owed || ')');
        INSERT INTO chip_transactions (club_id, amount, transaction_type, notes, metadata)
        VALUES (r.club_id, v_take, 'union_pnl_collect',
                'Weekly union player P&L settlement: club owed ' || v_owed,
                jsonb_build_object('union_id', p_union_id, 'settlement_id', v_settlement_id,
                                   'period_start', p_start, 'net', r.net));
      END IF;

      SELECT id INTO v_period_id FROM settlement_periods
        WHERE club_id = r.club_id AND union_id = p_union_id
          AND start_at = p_start AND end_at = p_end
        ORDER BY created_at DESC LIMIT 1;
      IF v_period_id IS NULL THEN
        RAISE EXCEPTION 'settlement period row missing for club % in window % .. %', r.club_id, p_start, p_end;
      END IF;
      SELECT count(*) INTO v_receipt_count FROM public.chip_ledger l
       JOIN public.settlement_invoices i ON i.source_ledger_id=l.id
       WHERE l.settlement_id=v_ca_id::text AND l.club_id=r.club_id AND l.category='pnl_settlement'
        AND l.from_type='club_treasury' AND l.from_entity_id=r.club_id
        AND l.to_type='union_wallet' AND l.to_entity_id=p_union_id AND l.status='posted' AND l.amount=v_owed
        AND i.status='paid' AND i.chips_transferred AND i.message_sent
        AND i.gross_amount=v_owed AND i.net_amount=v_owed AND i.deductions=0;
      IF v_receipt_count<>1 THEN RAISE EXCEPTION 'pnl_posted_receipt_missing_or_ambiguous'; END IF;
      v_unpaid_total := v_unpaid_total + round(v_owed - v_take, 2);
    END LOOP;

    FOR r IN SELECT * FROM pg_temp._pnl_tmp WHERE net > 0 ORDER BY club_id LOOP
      v_owed := round(r.net, 2);
      v_pay := v_owed;
      IF v_pay > v_owed OR v_pay < 0 THEN
        RAISE EXCEPTION 'pnl validation: pay leg out of bounds (pay % owed %)', v_pay, v_owed;
      END IF;
      IF v_pay > 0 THEN
        UPDATE clubs SET chip_treasury = COALESCE(chip_treasury, 0) + v_pay WHERE id = r.club_id;
        v_union_balance := v_union_balance - v_pay;
        UPDATE union_wallets SET chip_balance = v_union_balance WHERE union_id = p_union_id;
        v_pay_total := v_pay_total + v_pay;
        INSERT INTO union_wallet_transactions (union_id, wallet, direction, amount, balance_after, tx_type, club_id, notes)
        VALUES (p_union_id, 'chip_balance', 'debit', v_pay, v_union_balance, 'player_pnl_pay', r.club_id,
                'Weekly player P&L: paid to club (owed ' || v_owed || ')');
        INSERT INTO chip_transactions (club_id, amount, transaction_type, notes, metadata)
        VALUES (r.club_id, v_pay, 'union_pnl_payout',
                'Weekly union player P&L settlement: union owed ' || v_owed,
                jsonb_build_object('union_id', p_union_id, 'settlement_id', v_settlement_id,
                                   'period_start', p_start, 'net', r.net));
      END IF;

      SELECT id INTO v_period_id FROM settlement_periods
        WHERE club_id = r.club_id AND union_id = p_union_id
          AND start_at = p_start AND end_at = p_end
        ORDER BY created_at DESC LIMIT 1;
      IF v_period_id IS NULL THEN
        RAISE EXCEPTION 'settlement period row missing for club % in window % .. %', r.club_id, p_start, p_end;
      END IF;
      SELECT count(*) INTO v_receipt_count FROM public.chip_ledger l
       JOIN public.settlement_invoices i ON i.source_ledger_id=l.id
       WHERE l.settlement_id=v_ca_id::text AND l.club_id=r.club_id AND l.category='pnl_settlement'
        AND l.from_type='union_wallet' AND l.from_entity_id=p_union_id
        AND l.to_type='club_treasury' AND l.to_entity_id=r.club_id AND l.status='posted' AND l.amount=v_owed
        AND i.status='paid' AND i.chips_transferred AND i.message_sent
        AND i.gross_amount=v_owed AND i.net_amount=v_owed AND i.deductions=0;
      IF v_receipt_count<>1 THEN RAISE EXCEPTION 'pnl_posted_receipt_missing_or_ambiguous'; END IF;
      v_unpaid_total := v_unpaid_total + round(v_owed - v_pay, 2);
    END LOOP;

    IF v_unpaid_total<>0 OR v_collect_total<>v_needed OR v_pay_total<>v_winners_total THEN
      RAISE EXCEPTION 'pnl_obligations_not_fully_settled' USING ERRCODE='23514';
    END IF;
    IF EXISTS(SELECT 1 FROM pg_temp._pnl_tmp t JOIN public.clubs c ON c.id=t.club_id
       WHERE c.chip_treasury IS DISTINCT FROM t.opening_treasury+t.net)
      OR v_union_balance<>v_initial_union+v_collect_total-v_pay_total THEN
      RAISE EXCEPTION 'pnl_balance_conservation_failed' USING ERRCODE='23514';
    END IF;
    PERFORM set_config('app.ledger_category',COALESCE(v_prior_ledger->>'category',''),true);
    PERFORM set_config('app.ledger_counterparty',COALESCE(v_prior_ledger->>'counterparty',''),true);
    PERFORM set_config('app.ledger_counterparty_entity',COALESCE(v_prior_ledger->>'entity',''),true);
    PERFORM set_config('app.ledger_settlement',COALESCE(v_prior_ledger->>'settlement',''),true);
    PERFORM set_config('app.ledger_autoskip_union_wallets',COALESCE(v_prior_ledger->>'autoskip',''),true);
    PERFORM set_config('app.ledger_counterparty_label','',true);

    IF abs(v_residual) >= 0.01 THEN
      INSERT INTO union_wallet_transactions (union_id, wallet, direction, amount, balance_after, tx_type, notes)
      VALUES (p_union_id, 'chip_balance',
              CASE WHEN v_residual < 0 THEN 'credit' ELSE 'debit' END,
              abs(v_residual), v_union_balance, 'player_pnl_house_residual',
              'Net player clearing residual for the period, including all players, absorbed by the union '
              || 'as clearing house (settlement ' || v_settlement_id || ')');
    END IF;

    IF v_walk THEN
      UPDATE public.ca_settlements SET state = 'ledger_posted' WHERE id = v_ca_id;
    END IF;

    UPDATE settlement_periods sp
       SET total_player_winnings = COALESCE((t.detail->>'winnings')::numeric, 0),
           total_player_losses   = COALESCE((t.detail->>'losses')::numeric, 0),
           seated_stack_snapshot = t.seated,
           status = 'settled',
           settled_at = now()
      FROM pg_temp._pnl_tmp t
     WHERE sp.club_id = t.club_id AND sp.union_id = p_union_id
       AND sp.start_at = p_start AND sp.end_at = p_end;

    -- Post-commit verification: the wallet must hold exactly what the legs say.
    SELECT chip_balance INTO v_expected_balance FROM union_wallets WHERE union_id = p_union_id;
    IF round(COALESCE(v_expected_balance, 0), 2) <> round(v_union_balance, 2) THEN
      RAISE EXCEPTION 'pnl post-commit verify: wallet % but legs say %', v_expected_balance, v_union_balance;
    END IF;
    IF v_walk THEN
      UPDATE public.ca_settlements SET state = 'post_commit_verified' WHERE id = v_ca_id;
      UPDATE public.ca_settlements SET state = 'final',
        totals = COALESCE(totals, '{}'::jsonb) || jsonb_build_object(
          'collected', v_collect_total, 'paid', v_pay_total,
          'unpaid', v_unpaid_total, 'house_residual', v_residual)
        WHERE id = v_ca_id;
    END IF;

    SELECT jsonb_agg(detail ORDER BY club_id) INTO v_results FROM pg_temp._pnl_tmp;
    UPDATE union_pnl_settlements
       SET status='settled', total_collected=v_collect_total, total_paid=v_pay_total,
           total_unpaid=v_unpaid_total, house_residual=v_residual,
           club_results=COALESCE(v_results,'[]'::jsonb), settled_at=now()
     WHERE id = v_settlement_id;

  EXCEPTION WHEN OTHERS THEN
    -- Every chip movement above is rolled back to the block savepoint here.
    v_err := SQLERRM;
    UPDATE union_pnl_settlements SET status = 'failed' WHERE id = v_settlement_id;
    UPDATE public.ca_settlements SET state = 'failed', error_detail = left(v_err, 2000)
     WHERE id = v_ca_id;
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_union_settle_player_pnl', 'settlement_error', 'critical',
      'pnl-settle-failed:' || p_union_id::text || ':' || extract(epoch from p_start)::bigint,
      0, NULL, NULL, 'settlement', 'union_pnl_settlements',
      v_settlement_id, NULL, p_union_id, NULL, NULL, NULL, v_ca_id::text, NULL, NULL,
      'Weekly player P&L settlement failed and was fully rolled back (no chips moved): ' || left(v_err, 300)
        || ' - fix the cause and re-run; the failed claim does not block a retry',
      false, jsonb_build_object('period_start', p_start, 'period_end', p_end, 'error', left(v_err, 500)));
    RETURN jsonb_build_object('success', false, 'error', v_err, 'rolled_back', true,
      'settlement_id', v_settlement_id, 'union_id', p_union_id, 'period_start', p_start);
  END;

  RETURN jsonb_build_object('success', true, 'settlement_id', v_settlement_id, 'union_id', p_union_id,
    'period_start', p_start, 'period_end', p_end, 'house_residual', v_residual,
    'total_collected', v_collect_total, 'total_paid', v_pay_total, 'total_unpaid', v_unpaid_total,
    'union_balance_after', v_union_balance, 'clubs', COALESCE(v_results, '[]'::jsonb));
END $$;

CREATE FUNCTION public.fn_union_settlement_cascade(p_union_id uuid DEFAULT 'fade0000-0000-0000-0000-000000000001'::uuid, p_period_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_period_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_preparation jsonb; v_credit_club record;
  v_from timestamptz := COALESCE(p_period_start, public.fn_union_prev_week_start(now()));
  v_to   timestamptz := COALESCE(p_period_end,   public.fn_union_week_start(now()));
  v_r1 jsonb; v_r2 jsonb; v_r3 jsonb; v_eco jsonb; v_inv jsonb;
  v_floor timestamptz;
  v_club_statements jsonb; v_previous_validated text;
  v_sqlstate text; v_msg text; v_detail text; v_context text;
  v_pending jsonb; v_posted record;
  -- CHUNKED CLOSE (20261003): set by job 272's tick; see
  -- fn_process_weekly_accounting_scope. Off, this function is unchanged.
  v_chunked boolean := COALESCE(current_setting('app.weekly_accounting_chunked', true), '') = 'on';

BEGIN
  IF EXISTS (SELECT 1 FROM settlement_locks WHERE lock_type = 'GLOBAL_SETTLEMENT_FREEZE' AND is_active = true) THEN
    RAISE EXCEPTION 'EMERGENCY_PROFIT_DRIFT_LOCK';
  END IF;

  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_union_overseer(p_union_id, auth.uid()))) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  -- THE FLOOR, checked before anything moves. Round 1 has always honoured it;
  -- nothing above round 1 did, so three further rounds ran on a floored week.
  SELECT f.earliest_period_start INTO v_floor
    FROM union_settlement_floor f WHERE f.union_id = p_union_id;

  IF v_floor IS NOT NULL AND v_from < v_floor THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'union_settlement_incomplete', DETAIL = (jsonb_build_object('success', false, 'union_id', p_union_id,
      'error', 'before_settlement_floor',
      'period_start', v_from, 'period_end', v_to,
      'settlement_floor', v_floor,
      'note', 'This period is below the union settlement floor and must not be '
              || 'settled. No round was run.'))::text;
  END IF;

  /* WARM THE CACHE BEFORE THE FIRST LOCK (2026-09-09). union_rake_rollup_days
     is a speed cache: a day that is missing is recomputed live and correct,
     but it is recomputed INSIDE the settlement, while it holds treasury rows -
     which is where this union has been deadlocking. Doing it here costs the
     same work at a moment when nothing is locked. A failure is not fatal:
     the live path still answers, just more slowly. */
  BEGIN
    PERFORM public.fn_union_rake_rollup_refresh_day(p_union_id, g.d::date)
       FROM generate_series(v_from::date, (v_to - interval '1 day')::date, interval '1 day') g(d)
      WHERE NOT EXISTS (SELECT 1 FROM public.union_rake_rollup_days rd
                         WHERE rd.union_id = p_union_id AND rd.day = g.d::date)
        AND g.d::date < (now() AT TIME ZONE 'UTC')::date;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'settlement could not warm the rake rollup (%); the live path will answer instead', SQLERRM;
  END;

  IF v_from IS NULL OR NOT isfinite(v_from) OR v_from<>public.fn_union_week_start(v_from)
   OR v_to IS DISTINCT FROM public.fn_union_week_start(v_from+interval '8 days') THEN
   RAISE EXCEPTION 'accounting_preparation_requires_closed_week' USING ERRCODE='22023';
  END IF;
  PERFORM public.fn_union_pnl_closed_book_barrier(v_to);
  -- Serialize every entry point for this union/period. A replay must read
  -- the receipts after the competing transaction commits, before moving chips.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'union-accounting:' || p_union_id::text || ':' || extract(epoch FROM v_from)::text || ':' || extract(epoch FROM v_to)::text, 0));

  -- A union-owned table is not a player's earning club. These outstanding
  -- records are invisible to the member-club join in Round 3. Never certify
  -- completion while they exist, and never guess a replacement beneficiary.
  IF EXISTS (SELECT 1 FROM public.rakeback_periods rp
       WHERE rp.club_id = p_union_id AND rp.status = 'pending'
         AND rp.rakeback_amount > 0
         AND (rp.period_start::timestamp AT TIME ZONE 'UTC') < v_to
         AND ((rp.period_end + 1)::timestamp AT TIME ZONE 'UTC') > v_from) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'union_rakeback_wrong_club',
      DETAIL = 'Pending player rakeback is booked under the union ID. Reconcile the earning-club evidence before settlement.';
  END IF;

  -- THE UNION WALLET IS DEBITED LAST (20260929): round 1 leaves its rake
  -- wallet debit pending for this exact book; it is posted below, after the
  -- statements, so live hands are never queued behind the close.
  -- CHUNKED CLOSE (20261003): a round that commits in its own transaction
  -- posts its own union wallet debit (round 1's original undeferred path):
  -- a pending debit is a transaction-local setting and cannot outlive it.
  PERFORM set_config('app.union_close_defer_rake_debit', CASE WHEN v_chunked THEN '' ELSE p_union_id::text || ':'
    || to_char(v_from AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') || '..'
    || to_char(v_to AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') END, true);
  PERFORM set_config('app.union_close_pending_rake_debit', '', true);

  -- ROUND 1 - union rake treasury pays the clubs their 90%.
  PERFORM public.fn_assert_cash_commission_period(p_union_id,NULL,v_from,v_to);
  v_preparation:=public.fn_prepare_accounting_week(p_union_id,NULL,v_from,v_to);
  IF v_preparation->>'success' IS DISTINCT FROM 'true' THEN
    RAISE EXCEPTION 'weekly_accounting_calculation_incomplete' USING DETAIL=v_preparation::text;
  END IF;
  PERFORM public.fn_weekly_accounting_deadline_check();
  v_r1 := public.fn_union_weekly_rakeback_close(p_union_id, v_from, v_to);
  INSERT INTO union_settlement_rounds (union_id, period_start, period_end, round_no, round_name,
                                       payers, payees, amount, detail)
  VALUES (p_union_id, v_from, v_to, 1, 'union_to_clubs', 1,
          COALESCE((v_r1->>'clubs_paid')::int,0),
          COALESCE((v_r1->>'total_rakeback')::numeric,0), v_r1)
  ON CONFLICT (union_id, period_start, period_end, round_no) DO NOTHING;

  IF COALESCE((v_r1->>'success')::boolean, false) IS NOT TRUE
     AND COALESCE(v_r1->>'error','') <> 'already_executed' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'union_settlement_incomplete', DETAIL = (jsonb_build_object('success', false, 'union_id', p_union_id,
      'error', 'round1_failed: ' || COALESCE(v_r1->>'error','unknown'),
      'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1,
      'note', 'Rounds 2, 3 and 4 were not run. A club is not asked to pay its '
              || 'agents out of a treasury the union has not funded.'))::text;
  END IF;

  -- CHUNKED CLOSE (20261003): a round that moved money ends this attempt
  -- here; it commits with its receipts (union_rakeback_log, the final
  -- ca_settlements row, union_settlement_rounds round 1) and the next attempt
  -- skips it by them ('already_executed'). Nothing after this point - no
  -- period is marked settled, no statement or square-up is issued - until
  -- the attempt that finds every round committed.
  IF v_chunked AND v_r1->>'success' = 'true' THEN
    RETURN jsonb_build_object('success', false, 'chunk_committed', true, 'committed_round', 1,
      'union_id', p_union_id, 'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1);
  END IF;

  -- ROUND 2 - clubs pay their super agents and agents.
  PERFORM public.fn_weekly_accounting_deadline_check();
  -- CHUNKED CLOSE (20261003): a round 2 an earlier attempt committed is
  -- answered from its own receipt - exactly what the stage returns for it
  -- as a duplicate - instead of reading the whole week again to prove it.
  -- Every attempt has first re-run the book's barrier, accrual, refusal and
  -- preparation checks, under which no source of this closed week can change.
  IF v_chunked THEN
    SELECT r.result||jsonb_build_object('duplicate',true) INTO v_r2 FROM public.accounting_routed_settlement_runs r
     WHERE r.scope_kind='union' AND r.scope_id=p_union_id AND r.period_start=v_from AND r.period_end=v_to AND r.round_no=2;
  END IF;
  IF v_r2 IS NULL THEN
  v_r2 := public.fn_settle_round2_club_to_agents(p_union_id, v_from, v_to);
  END IF;
  IF v_r2->>'routing_version' IS DISTINCT FROM '3'
    OR v_r2->>'source_version' IS DISTINCT FROM '2'
    OR NOT EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r
      WHERE r.union_id=p_union_id AND r.period_start=v_from AND r.period_end=v_to AND r.round_no=2
       AND r.result=(v_r2-'duplicate')) THEN
    RAISE EXCEPTION 'weekly_routing_receipt_not_confirmed' USING ERRCODE='23514';
  END IF;
  INSERT INTO union_settlement_rounds (union_id, period_start, period_end, round_no, round_name,
                                       payees, amount, shortfalls, detail)
  VALUES (p_union_id, v_from, v_to, 2, 'club_to_agents',
          COALESCE((v_r2->>'payees')::int,0), COALESCE((v_r2->>'amount')::numeric,0),
          COALESCE((v_r2->>'shortfalls')::int,0), v_r2)
  ON CONFLICT (union_id, period_start, period_end, round_no) DO UPDATE
    SET detail=union_settlement_rounds.detail || jsonb_build_object('latest_attempt',EXCLUDED.detail);

  -- Round 2 carries no 'success' key: it raises on error and returns
  -- {round,name,payees,amount,shortfalls,detail} otherwise, so a test for
  -- 'success' would be unreachable. Assert the CONTRACT instead - a round that
  -- stops reporting an amount must stop the cascade, not record 0 and carry on.
  IF (v_r2->>'amount') IS NULL OR (v_r2->>'payees') IS NULL
     OR (v_r2->>'shortfalls') IS NULL
     OR jsonb_typeof(v_r2->'shortfalls') IS DISTINCT FROM 'number'
     OR (v_r2 ? 'success' AND COALESCE((v_r2->>'success')::boolean, true) IS FALSE
         AND COALESCE(v_r2->>'error','') <> 'already_executed') THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'union_settlement_incomplete', DETAIL = (jsonb_build_object('success', false, 'union_id', p_union_id,
      'error', 'round2_contract_violated_or_failed: ' || COALESCE(v_r2->>'error','unknown'),
      'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1, 'round2_club_to_agents', v_r2,
      'note', 'Rounds 3 and 4 were not run.'))::text;
  END IF;

  -- CHUNKED CLOSE (20261003): round 2 commits on its own only with no
  -- shortfall, exactly what the unchunked close would have kept; the next
  -- attempt finds its receipt (accounting_routed_settlement_runs round 2)
  -- and the stage returns it as a duplicate.
  IF v_chunked AND v_r2->>'duplicate' IS DISTINCT FROM 'true' THEN
    IF (v_r2->>'shortfalls')::numeric <> 0 THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'union_settlement_incomplete', DETAIL = (jsonb_build_object('success',false,'union_id',p_union_id,
        'error','recipient_shortfalls_remaining','period_start',v_from,'period_end',v_to,
        'round1_union_to_clubs',v_r1,'round2_club_to_agents',v_r2))::text;
    END IF;
    RETURN jsonb_build_object('success', false, 'chunk_committed', true, 'committed_round', 2,
      'union_id', p_union_id, 'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1, 'round2_club_to_agents', v_r2);
  END IF;

  -- ROUND 3 - agents pay their players.
  PERFORM public.fn_weekly_accounting_deadline_check();
  -- CHUNKED CLOSE (20261003): the same for a committed round 3.
  IF v_chunked THEN
    SELECT r.result||jsonb_build_object('duplicate',true) INTO v_r3 FROM public.accounting_routed_settlement_runs r
     WHERE r.scope_kind='union' AND r.scope_id=p_union_id AND r.period_start=v_from AND r.period_end=v_to AND r.round_no=3;
  END IF;
  IF v_r3 IS NULL THEN
  v_r3 := public.fn_settle_round3_agents_to_players(p_union_id, v_from, v_to);
  END IF;
  -- CHUNKED CLOSE (20261003, round 3 in batches): a batch that paid part of
  -- round 3 ends this attempt as a committed step; the next attempt pays on.
  IF v_chunked AND v_r3->>'batch_committed' = 'true' THEN
    RETURN jsonb_build_object('success', false, 'chunk_committed', true, 'committed_round', 3, 'stage', 'round3_batch',
      'union_id', p_union_id, 'period_start', v_from, 'period_end', v_to, 'round3_batch', v_r3);
  END IF;
  IF v_r3->>'routing_version' IS DISTINCT FROM '3'
    OR v_r3->>'source_version' IS DISTINCT FROM '2'
    OR NOT EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r
      WHERE r.union_id=p_union_id AND r.period_start=v_from AND r.period_end=v_to AND r.round_no=3
       AND r.result=(v_r3-'duplicate')) THEN
    RAISE EXCEPTION 'weekly_routing_receipt_not_confirmed' USING ERRCODE='23514';
  END IF;
  INSERT INTO union_settlement_rounds (union_id, period_start, period_end, round_no, round_name,
                                       payees, amount, shortfalls, detail)
  VALUES (p_union_id, v_from, v_to, 3, 'agents_to_players',
          COALESCE((v_r3->>'payees')::int,0), COALESCE((v_r3->>'amount')::numeric,0),
          COALESCE((v_r3->>'shortfalls')::int,0), v_r3)
  ON CONFLICT (union_id, period_start, period_end, round_no) DO UPDATE
    SET detail=union_settlement_rounds.detail || jsonb_build_object('latest_attempt',EXCLUDED.detail);

  -- Same contract assertion for round 3.
  IF (v_r3->>'amount') IS NULL OR (v_r3->>'payees') IS NULL
     OR (v_r3->>'shortfalls') IS NULL
     OR jsonb_typeof(v_r3->'shortfalls') IS DISTINCT FROM 'number'
     OR (v_r3 ? 'success' AND COALESCE((v_r3->>'success')::boolean, true) IS FALSE
         AND COALESCE(v_r3->>'error','') <> 'already_executed') THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'union_settlement_incomplete', DETAIL = (jsonb_build_object('success', false, 'union_id', p_union_id,
      'error', 'round3_contract_violated_or_failed: ' || COALESCE(v_r3->>'error','unknown'),
      'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1, 'round2_club_to_agents', v_r2,
      'round3_agents_to_players', v_r3,
      'note', 'Round 4 was not run; no statement is issued for a settlement '
              || 'that did not complete.'))::text;
  END IF;

  -- A round can post funded recipients while reporting others still unpaid.
  -- Keep that durable progress, but do not mark the period settled or issue
  -- completion statements until every reported shortfall is zero.
  IF (v_r2->>'shortfalls')::numeric <> 0
     OR (v_r3->>'shortfalls')::numeric <> 0 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'union_settlement_incomplete', DETAIL = (jsonb_build_object('success',false,'union_id',p_union_id,
      'error','recipient_shortfalls_remaining','period_start',v_from,'period_end',v_to,
      'round1_union_to_clubs',v_r1,'round2_club_to_agents',v_r2,
      'round3_agents_to_players',v_r3))::text;
  END IF;

  IF EXISTS (SELECT 1 FROM public.rakeback_periods rp
      JOIN public.fn_accounting_week_clubs(p_union_id,NULL,v_from,v_to) uc ON uc.club_id=rp.club_id
      WHERE rp.status='pending' AND rp.rakeback_amount>0
        AND rp.period_start >= (v_from AT TIME ZONE 'UTC')::date
        AND ((rp.period_end+1)::timestamp AT TIME ZONE 'UTC') <= v_to) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='union_player_obligations_remaining';
  END IF;

  -- CONSERVATION, asserted before anything else is written. Raises on a
  -- breach, which rolls this union's whole settlement back.
  PERFORM public.fn_union_settlement_conservation_assert(
            p_union_id, v_from, v_to, v_r1, v_r2, v_r3);

  -- CHUNKED CLOSE (20261003): round 3 commits on its own only after every
  -- test the unchunked close applies to it - no shortfall, no pending player
  -- period, conservation asserted - and the attempt that finds all three
  -- rounds committed repeats those tests before it settles the period.
  IF v_chunked AND v_r3->>'duplicate' IS DISTINCT FROM 'true' THEN
    RETURN jsonb_build_object('success', false, 'chunk_committed', true, 'committed_round', 3,
      'union_id', p_union_id, 'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1, 'round2_club_to_agents', v_r2,
      'round3_agents_to_players', v_r3);
  END IF;

  -- The period is an accounting object, not a by-product of invoicing.
  PERFORM public.fn_mark_scope_accounting_settled('union',p_union_id,v_from,v_to);

  IF public.fn_union_pnl_qualified_clubs(p_union_id,v_from,v_to)#>>'{eco_commercial_terms_evidence,segments,0,terms,eco_enabled}'='true' THEN
    BEGIN
      v_eco := public.fn_union_eco_record(p_union_id, v_from, v_to, NULL);
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT,
                              v_detail = PG_EXCEPTION_DETAIL, v_context = PG_EXCEPTION_CONTEXT;
      v_eco := jsonb_build_object('success', false, 'error', v_msg, 'sqlstate', v_sqlstate,
                                  'exception_detail', v_detail, 'exception_context', v_context);
    END;
  ELSE
    v_eco := jsonb_build_object('skipped', true, 'reason', 'eco_disabled');
  END IF;

  IF v_eco->>'success' = 'false' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'union_eco_record_failed', DETAIL = v_eco::text;
  END IF;

  PERFORM public.fn_weekly_accounting_deadline_check();
  IF public.fn_union_setting(p_union_id, 'weekly_invoices_enabled', 1) <> 1 THEN
    v_inv := jsonb_build_object(
      'success', true, 'skipped', true, 'invoices', 0,
      'reason', 'weekly_invoices_disabled: the union setting weekly_invoices_enabled is 0. '
                || 'Since Phase 6 (20260907) the statement reads the same fn_union_club_rake_basis '
                || 'rows round 1 pays on; switching statements back on is a setting, not a fix.');
  ELSE
    BEGIN
      v_inv := public.fn_union_issue_weekly_invoices(p_union_id, v_from, v_to, true);
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT,
                              v_detail = PG_EXCEPTION_DETAIL, v_context = PG_EXCEPTION_CONTEXT;
      v_inv := jsonb_build_object('success', false, 'error', v_msg, 'sqlstate', v_sqlstate,
                                  'exception_detail', v_detail, 'exception_context', v_context);
    END;
  END IF;

  INSERT INTO union_settlement_rounds (union_id, period_start, period_end, round_no, round_name,
                                       payees, amount, detail)
  VALUES (p_union_id, v_from, v_to, 4, 'union_invoices_issued',
          COALESCE((v_inv->>'invoices')::int, 0), 0, v_inv)
  ON CONFLICT (union_id, period_start, period_end, round_no) DO UPDATE
    SET detail=EXCLUDED.detail,payees=EXCLUDED.payees;

  IF COALESCE((v_inv->>'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'union_settlement_incomplete', DETAIL = (jsonb_build_object('success', false, 'union_id', p_union_id,
      'error', 'round4_invoices_failed: ' || COALESCE(v_inv->>'error','unknown'),
      'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1, 'round2_club_to_agents', v_r2,
      'round3_agents_to_players', v_r3, 'eco_recorded', v_eco,
      'round4_invoices', v_inv))::text;
  END IF;

  IF COALESCE((v_inv->>'skipped')::boolean, false) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'union_invoices_not_issued', DETAIL = v_inv::text;
  END IF;

  IF EXISTS (SELECT 1 FROM public.fn_accounting_week_clubs(p_union_id,NULL,v_from,v_to) uc
    WHERE uc.club_id<>p_union_id
      AND NOT EXISTS (SELECT 1 FROM public.settlement_invoices si
        WHERE si.club_id=uc.club_id AND si.invoice_type='union_weekly_squareup'
          AND si.breakdown->>'union_id'=p_union_id::text
          AND (si.breakdown->>'period_start')::timestamptz=v_from
          AND (si.breakdown->>'period_end')::timestamptz=v_to
          AND si.message_sent=true AND si.status<>'cancelled')) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='union_invoice_delivery_incomplete';
  END IF;

  -- THE SQUARE-UP'S OWN PERIOD SETTLES WITH ITS WEEK (2026-10-08). The
  -- settler above ran before round 4, and the square-up then opened the
  -- union's own club row (clubs.id = union id) as 'processing', so that one
  -- period never settled (cc6c056b, week of 2026-09-28). Settle every period
  -- this week opened once more, now that the last opener has run, and prove it.
  PERFORM public.fn_mark_scope_accounting_settled('union',p_union_id,v_from,v_to);
  IF EXISTS (SELECT 1 FROM public.settlement_periods sp
              WHERE sp.union_id=p_union_id AND sp.start_at=v_from AND sp.end_at=v_to
                AND sp.status NOT IN ('settled','closed')) THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='union_week_period_left_unsettled';
  END IF;

  PERFORM public.fn_weekly_accounting_deadline_check();
  FOR v_credit_club IN SELECT club_id FROM public.fn_accounting_week_clubs(p_union_id,NULL,v_from,v_to) ORDER BY club_id LOOP
    PERFORM public.fn_generate_scope_credit_invoices(v_credit_club.club_id,v_from,v_to);
  END LOOP;
  v_previous_validated:=current_setting('app.union_accounting_validated_period',true);
  PERFORM set_config('app.union_accounting_validated_period',p_union_id::text||':'||v_from::text||':'||v_to::text,true);
  v_club_statements:=public.fn_issue_club_weekly_accounting(p_union_id,v_from,v_to);
  PERFORM public.fn_weekly_accounting_deadline_check();
  PERFORM set_config('app.union_accounting_validated_period',COALESCE(v_previous_validated,''),true);
  v_pending := NULLIF(current_setting('app.union_close_pending_rake_debit', true), '')::jsonb;
  PERFORM set_config('app.union_close_defer_rake_debit', '', true);
  PERFORM set_config('app.union_close_pending_rake_debit', '', true);
  IF v_r1->>'success' = 'true' AND COALESCE((v_r1->>'period_rake')::numeric, 0) > 0 AND (v_pending IS NULL OR v_pending->>'settlement_id' IS DISTINCT FROM v_r1->>'settlement_id') THEN
    RAISE EXCEPTION 'union_close_rake_debit_not_pending' USING ERRCODE='55000';
  END IF;
  IF v_pending IS NOT NULL THEN
    IF v_r1->>'success' IS DISTINCT FROM 'true' THEN
      RAISE EXCEPTION 'union_close_rake_debit_without_round1' USING ERRCODE='55000';
    END IF;
    SELECT * INTO v_posted FROM public.fn_union_close_post_rake_debit(v_pending);
    v_r1 := v_r1 || jsonb_build_object('rake_wallet_after', v_posted.rw_after, 'chip_balance_after', v_posted.cb_after,
      'rake_debit_posted', 'last_write_of_cascade');
  END IF;
  RETURN jsonb_build_object('success', true, 'union_id', p_union_id, 'club_weekly_statements',v_club_statements,
    'period_start', v_from, 'period_end', v_to,
    'round1_union_to_clubs', v_r1, 'round2_club_to_agents', v_r2,
    'round3_agents_to_players', v_r3, 'eco_recorded', v_eco,
    'round4_invoices', v_inv);
END $$;

CREATE FUNCTION public.fn_union_settlement_conservation_assert(p_union_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_r1 jsonb, p_r2 jsonb, p_r3 jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rake     numeric := (p_r1->>'period_rake')::numeric;
  v_paid     numeric := (p_r1->>'total_rakeback')::numeric;
  v_retained numeric := (p_r1->>'union_retained')::numeric;
  v_r2_amt   numeric := (p_r2->>'amount')::numeric;
  v_r3_amt   numeric := (p_r3->>'amount')::numeric;
  v_neg      text;
  v_checked  int := 0; v_totals jsonb;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
  IF p_union_id IS NULL OR p_from IS NULL OR p_to IS NULL OR p_from IS DISTINCT FROM public.fn_union_week_start(p_from)
   OR p_to IS DISTINCT FROM public.fn_union_week_start(p_from+interval '8 days') THEN
   RAISE EXCEPTION 'invalid_conservation_scope' USING ERRCODE='22023'; END IF;
  SELECT c.totals INTO v_totals FROM public.ca_settlements c
   WHERE c.settlement_type='union_rakeback_close' AND c.union_id=p_union_id AND c.state='final'
    AND c.external_ref=p_union_id::text||':'||to_char(p_from AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
     ||'..'||to_char(p_to AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"');
  IF v_totals IS NULL OR v_totals->>'accounting_version' IS DISTINCT FROM '3' THEN
    RAISE EXCEPTION 'CONSERVATION_UNVERIFIED: exact recorded earning close is missing'; END IF;
  IF p_r1->>'error'='already_executed' THEN
    v_rake:=(v_totals->>'period_rake')::numeric;
    v_paid:=(v_totals->>'payout_total')::numeric;
    v_retained:=(v_totals->>'retained')::numeric;
  ELSIF p_r1->>'success' IS DISTINCT FROM 'true'
   OR (v_totals->>'period_rake')::numeric IS DISTINCT FROM v_rake
   OR (v_totals->>'payout_total')::numeric IS DISTINCT FROM v_paid
   OR (v_totals->>'retained')::numeric IS DISTINCT FROM v_retained THEN
    RAISE EXCEPTION 'CONSERVATION_UNVERIFIED: Round 1 response differs from its posted close'; END IF;
  IF EXISTS(SELECT 1 FROM (VALUES(2,p_r2),(3,p_r3)) input(round_no,receipt)
    WHERE input.receipt->>'success' IS DISTINCT FROM 'true'
     OR input.receipt->>'routing_version' IS DISTINCT FROM '3'
     OR input.receipt->>'source_version' IS DISTINCT FROM '2'
     OR input.receipt->'shortfalls' IS DISTINCT FROM '0'::jsonb
     OR NOT EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r WHERE r.scope_kind='union' AND r.scope_id=p_union_id
      AND r.period_start=p_from AND r.period_end=p_to AND r.round_no=input.round_no AND r.result=(input.receipt-'duplicate'))) THEN
    RAISE EXCEPTION 'CONSERVATION_UNVERIFIED: routed payment receipts do not match the exact union week'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.union_wallets w WHERE w.union_id=p_union_id)
   OR EXISTS(SELECT 1 FROM public.fn_accounting_week_clubs(p_union_id,NULL,p_from,p_to) s
    WHERE NOT EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=s.club_id)) THEN
    RAISE EXCEPTION 'CONSERVATION_UNVERIFIED: an accounting wallet is missing'; END IF;
  IF v_rake IS NULL OR v_paid IS NULL OR v_retained IS NULL OR v_r2_amt IS NULL OR v_r3_amt IS NULL THEN
    RAISE EXCEPTION 'CONSERVATION_UNVERIFIED: settlement totals are missing';
  END IF;
  IF EXISTS(SELECT 1 FROM unnest(ARRAY[v_rake,v_paid,v_retained,v_r2_amt,v_r3_amt]) n
    WHERE n::text IN ('NaN','Infinity','-Infinity') OR n<0 OR n<>round(n,2)) THEN
    RAISE EXCEPTION 'CONSERVATION_BREACH: settlement totals must be finite nonnegative whole cents';
  END IF;
  IF v_rake <> v_paid+v_retained THEN
    RAISE EXCEPTION 'CONSERVATION_BREACH round1_arithmetic: rake % <> paid % + retained %',v_rake,v_paid,v_retained;
  END IF;
  IF v_paid>v_rake THEN RAISE EXCEPTION 'CONSERVATION_BREACH round1_overpay'; END IF;
  v_checked := v_checked+2;

  -- 6. Rounds 2 and 3 never move a negative amount.
  IF COALESCE(v_r2_amt, 0) < 0 THEN
    RAISE EXCEPTION 'CONSERVATION_BREACH round2_negative_amount: %', v_r2_amt;
  END IF;
  IF COALESCE(v_r3_amt, 0) < 0 THEN
    RAISE EXCEPTION 'CONSERVATION_BREACH round3_negative_amount: %', v_r3_amt;
  END IF;
  v_checked := v_checked + 2;

  -- 3 + 4 + 5. Nothing this union touches may be negative afterwards.
  SELECT string_agg(x.pool || ' = ' || COALESCE(x.amt::text,'NULL'), '; ') INTO v_neg
    FROM (
      SELECT 'union chip wallet' AS pool, w.chip_balance AS amt
        FROM union_wallets w
       WHERE w.union_id = p_union_id AND (w.chip_balance < 0 OR w.chip_balance IS NULL OR w.chip_balance::text IN('NaN','Infinity','-Infinity') OR w.chip_balance<>round(w.chip_balance,2))
      UNION ALL
      SELECT 'union rake wallet', w.rake_wallet
        FROM union_wallets w
       WHERE w.union_id = p_union_id AND (w.rake_wallet < 0 OR w.rake_wallet IS NULL OR w.rake_wallet::text IN('NaN','Infinity','-Infinity') OR w.rake_wallet<>round(w.rake_wallet,2))
      UNION ALL
      SELECT 'club treasury ' || c.name, c.chip_treasury
        FROM clubs c
        JOIN public.fn_accounting_week_clubs(p_union_id,NULL,p_from,p_to) uc ON uc.club_id = c.id
       WHERE (c.chip_treasury < 0 OR c.chip_treasury IS NULL OR c.chip_treasury::text IN('NaN','Infinity','-Infinity') OR c.chip_treasury<>round(c.chip_treasury,2))
      UNION ALL
      SELECT 'member wallet ' || cm.user_id::text, cm.chip_balance
        FROM club_members cm
        JOIN public.fn_accounting_week_clubs(p_union_id,NULL,p_from,p_to) uc ON uc.club_id = cm.club_id
       WHERE (cm.chip_balance < 0 OR cm.chip_balance IS NULL OR cm.chip_balance::text IN('NaN','Infinity','-Infinity') OR cm.chip_balance<>round(cm.chip_balance,2))
    ) x;

  IF v_neg IS NOT NULL THEN
    RAISE EXCEPTION 'CONSERVATION_BREACH negative_pool after settlement: %', left(v_neg, 400);
  END IF;
  v_checked := v_checked + 3;

  RETURN jsonb_build_object(
    'conservation', 'asserted',
    'checks', v_checked,
    'period_start', p_from, 'period_end', p_to,
    'round1_rake', v_rake, 'round1_paid', v_paid, 'round1_retained', v_retained,
    'round2_amount', v_r2_amt, 'round3_amount', v_r3_amt);
END $$;

CREATE FUNCTION public.fn_union_week_start(p_at timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT date_trunc('week', (p_at AT TIME ZONE 'America/Los_Angeles'))
           AT TIME ZONE 'America/Los_Angeles';
$$;

CREATE FUNCTION public.fn_union_weekly_rakeback_close(p_union_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_source_plan jsonb; v_ledger_id uuid; v_prior_context jsonb; context_key text;
  v_wallet       public.union_wallets%ROWTYPE;
  v_period_total numeric := 0;
  v_payout_total numeric := 0;
  v_retained     numeric := 0;
  v_clubs_paid   integer := 0;
  v_club         record;
  v_new_rw       numeric;
  v_new_cb       numeric;
  v_rw_before    numeric;
  v_cb_before    numeric;
  v_clubs_before numeric := 0;
  v_clubs_after  numeric := 0;
  v_credit       jsonb;
  v_sref         text;
  v_sid          uuid;
  v_sstate       text;
  v_actor        uuid;
  v_pending      jsonb;
  v_deferred     boolean := false;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
  -- EMERGENCY SETTLEMENT LOCK CHECK
  IF EXISTS (SELECT 1 FROM settlement_locks WHERE lock_type = 'GLOBAL_SETTLEMENT_FREEZE' AND is_active = true) THEN
    RAISE EXCEPTION 'EMERGENCY_PROFIT_DRIFT_LOCK';
  END IF;

  IF p_union_id IS NULL OR p_period_start IS NULL OR p_period_end IS NULL
     OR p_period_end <= p_period_start OR NOT isfinite(p_period_start) OR NOT isfinite(p_period_end) THEN
    RETURN jsonb_build_object('success', false, 'error', 'bad_params');
  END IF;

  IF EXISTS (SELECT 1 FROM public.union_settlement_floor f
              WHERE f.union_id = p_union_id
                AND p_period_start < f.earliest_period_start) THEN
    RETURN jsonb_build_object('success', false, 'error', 'before_settlement_floor');
  END IF;

  -- Every entry point uses the union's calendar, including DST boundaries.
  IF p_period_start <> public.fn_union_week_start(p_period_start)
     OR p_period_end <> public.fn_union_week_start(p_period_end)
     OR p_period_end <> public.fn_union_week_start(p_period_start+interval '8 days')
     OR p_period_end > public.fn_union_week_start(now()) THEN
    RETURN jsonb_build_object('success', false, 'error', 'period_not_closed_union_weeks');
  END IF;

  -- Accrual and bank producers acquire this exact scope before writing.
  PERFORM pg_advisory_xact_lock(hashtextextended('union-accounting:'||p_union_id::text||':'
    ||extract(epoch FROM p_period_start)::text||':'||extract(epoch FROM p_period_end)::text,0));

  IF EXISTS (
    SELECT 1 FROM union_rakeback_log
     WHERE union_id = p_union_id
       AND period_start = p_period_start AND period_end = p_period_end
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'already_executed');
  END IF;

  -- settlement walk: one row per (union, period), resumable after 'failed'
  v_sref := p_union_id::text || ':'
    || to_char(p_period_start at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') || '..'
    || to_char(p_period_end   at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');

  SELECT id, state INTO v_sid, v_sstate
    FROM ca_settlements
   WHERE settlement_type = 'union_rakeback_close' AND external_ref = v_sref
   FOR UPDATE;
  IF v_sid IS NULL THEN
    INSERT INTO ca_settlements (id, settlement_type, external_ref, state, union_id, totals)
    VALUES (gen_random_uuid(), 'union_rakeback_close', v_sref, 'open', p_union_id, '{}'::jsonb)
    RETURNING id INTO v_sid;
  ELSIF v_sstate = 'final' THEN
    RETURN jsonb_build_object('success', false, 'error', 'already_executed', 'settlement_id', v_sid);
  ELSIF v_sstate = 'failed' THEN
    UPDATE ca_settlements SET state = 'open', error_detail = NULL WHERE id = v_sid;  -- resume
  ELSE
    -- intermediate states never persist (single transaction), so anything
    -- else here is a concurrent close of the same period. Refuse loudly.
    RETURN jsonb_build_object('success', false, 'error', 'close_already_in_state_' || v_sstate,
                              'settlement_id', v_sid);
  END IF;

  UPDATE ca_settlements SET state = 'locked_for_calculation' WHERE id = v_sid;

  -- LIVE CONTENTION (20260929): read, never lock. Every hand of this union
  -- credits this row; the debit below takes its lock at the last moment.
  SELECT * INTO v_wallet FROM union_wallets WHERE union_id = p_union_id;
  IF v_wallet.union_id IS NULL THEN
    UPDATE ca_settlements SET state = 'failed', error_detail = 'no_wallet' WHERE id = v_sid;
    RETURN jsonb_build_object('success', false, 'error', 'no_wallet', 'settlement_id', v_sid);
  END IF;

  -- Recheck after the union wallet lock: concurrent overlapping closes cannot
  -- both consume the same rake credits under different period identities.
  IF EXISTS (SELECT 1 FROM public.union_rakeback_log l
              WHERE l.union_id = p_union_id
                AND l.period_start < p_period_end AND l.period_end > p_period_start) THEN
    UPDATE public.ca_settlements SET state = 'failed', error_detail = 'overlapping_closed_period' WHERE id = v_sid;
    RETURN jsonb_build_object('success', false, 'error', 'overlapping_closed_period', 'settlement_id', v_sid);
  END IF;

  BEGIN
    PERFORM 1 FROM public.union_wallet_transactions t WHERE t.union_id=p_union_id
      AND t.wallet='rake_wallet' AND t.direction='credit' AND t.tx_type='rake'
      AND t.created_at>=p_period_start AND t.created_at<p_period_end ORDER BY t.id FOR SHARE;
    v_source_plan:=public.fn_accounting_union_earned_plan(p_union_id,p_period_start,p_period_end);
  EXCEPTION WHEN OTHERS THEN
    UPDATE public.ca_settlements SET state='failed',error_detail=left(SQLERRM,2000) WHERE id=v_sid;
    RETURN jsonb_build_object('success',false,'error','union_earning_source_not_certified','detail',SQLERRM,'settlement_id',v_sid);
  END;

  /* THE PERIOD (unchanged): everything the rake treasury received. Each credit
     now also carries the GAME TYPE it came from: the named tournament's
     tournament_type, or cash when it names none. */
  DROP TABLE IF EXISTS _uwrb_credits;
  CREATE TEMP TABLE _uwrb_credits ON COMMIT DROP AS
  WITH raw AS (
    SELECT t.id, t.amount, t.notes, t.created_at,
           substring(t.notes from '\[tournament ([0-9a-f-]+)\]')::uuid AS tournament_id
      FROM union_wallet_transactions t
     WHERE t.union_id = p_union_id
       AND t.wallet = 'rake_wallet' AND t.direction = 'credit' AND t.tx_type = 'rake'
       AND t.created_at >= p_period_start AND t.created_at < p_period_end
  )
  SELECT r.id, r.amount, r.notes, r.created_at, r.tournament_id,
         CASE WHEN r.tournament_id IS NULL THEN 'cash'
              ELSE COALESCE(lower(tr.tournament_type), 'other') END AS game_type
    FROM raw r
    LEFT JOIN tournaments tr ON tr.id = r.tournament_id;

  DROP TABLE IF EXISTS _uwrb_by_type;
  /* THE BASIS (Dan, 2026-09-03) lives in fn_union_club_rake_basis since
     Phase 6 (20260907): the statement and the reconciliation report read
     the same function, so what is paid and what is described cannot
     diverge. The block that used to be here is that function, verbatim. */
  CREATE TEMP TABLE _uwrb_by_type ON COMMIT DROP AS
  SELECT b.club_id, b.game_type, b.rake_in, b.rate, b.payout
    FROM public.fn_union_club_rake_basis(p_union_id, p_period_start, p_period_end, true) b;

  /* The per-club roll-up the money section pays from. */
  DROP TABLE IF EXISTS _uwrb;
  CREATE TEMP TABLE _uwrb ON COMMIT DROP AS
  SELECT club_id,
         round(sum(rake_in), 2) AS rake_in,
         round(sum(payout), 2)  AS payout
    FROM _uwrb_by_type
   GROUP BY club_id;

  SELECT round(COALESCE(SUM(amount), 0), 2) INTO v_period_total FROM _uwrb_credits;
  SELECT round(COALESCE(SUM(payout), 0), 2) INTO v_payout_total
    FROM _uwrb WHERE club_id IS NOT NULL AND club_id <> p_union_id;
  IF v_period_total IS DISTINCT FROM (v_source_plan->>'period_rake')::numeric THEN
    RAISE EXCEPTION 'union_rake_bank_changed_during_close' USING ERRCODE='55000';
  END IF;
  v_retained := round(v_period_total - v_payout_total, 2);

  /* a share can never exceed what the treasury received: the attribution is
     a view of the same credits, so this only trips on a data fault */
  IF v_payout_total > v_period_total THEN
    UPDATE ca_settlements SET state = 'failed', error_detail = 'attribution_exceeds_treasury' WHERE id = v_sid;
    RETURN jsonb_build_object('success', false, 'error', 'attribution_exceeds_treasury',
      'period_rake', v_period_total, 'payout', v_payout_total, 'settlement_id', v_sid);
  END IF;

  UPDATE ca_settlements
     SET state = 'calculated',
         totals = jsonb_build_object('period_rake', v_period_total, 'payout_total', v_payout_total,
                                     'retained', v_retained,
                                     'basis', 'immutable_earned_sources_matched_to_bank',
                                     'accounting_version',3,
                                     'source_fingerprint',v_source_plan->'source_fingerprint',
                                     'house_rake',v_source_plan->'house_rake',
                                     'rate_model', 'observed_per_source_truncated_per_club_game',
                                     'basis_by_club', (SELECT COALESCE(jsonb_object_agg(club_id::text, rake_in), '{}'::jsonb) FROM _uwrb),
                                     'payout_by_club', (SELECT COALESCE(jsonb_object_agg(club_id::text, payout), '{}'::jsonb) FROM _uwrb),
                                     'basis_detail', (SELECT COALESCE(jsonb_agg(jsonb_build_object('club_id', club_id, 'game_type', game_type, 'rake_in', rake_in, 'rate', rate, 'payout', payout) ORDER BY club_id, game_type), '[]'::jsonb) FROM _uwrb_by_type),
                                     'basis_by_game_type', (SELECT COALESCE(jsonb_object_agg(game_type, x), '{}'::jsonb)
                                                              FROM (SELECT game_type,
                                                                           jsonb_build_object('basis', round(sum(rake_in), 2),
                                                                                              'payout', round(sum(payout), 2)) AS x
                                                                      FROM _uwrb_by_type GROUP BY game_type) g),
                                     'rates', (SELECT COALESCE(jsonb_object_agg(club_id::text || ':' || game_type, rate), '{}'::jsonb)
                                                 FROM _uwrb_by_type))
   WHERE id = v_sid;

  IF v_period_total <= 0 THEN
    INSERT INTO union_rakeback_log (union_id, period_start, period_end, total_rakeback, executed_at)
    VALUES (p_union_id, p_period_start, p_period_end, 0, now());
    UPDATE ca_settlements SET state = 'validated' WHERE id = v_sid;
    UPDATE ca_settlements SET state = 'ledger_posted' WHERE id = v_sid;
    UPDATE ca_settlements SET state = 'post_commit_verified' WHERE id = v_sid;
    UPDATE ca_settlements SET state = 'final' WHERE id = v_sid;
    RETURN jsonb_build_object('success', true, 'clubs_paid', 0,
      'period_rake', 0, 'total_rakeback', 0, 'union_retained', 0, 'note', 'no_rake',
      'settlement_id', v_sid);
  END IF;

  /* SEPARATE POTS (Phase 2.1). The rake treasury owes the whole period: the
     clubs' share leaves it as rakeback, the union's share leaves it for the
     general bank. The general bank is never a source. A treasury that cannot
     cover the period refuses the close whole - never partial, never from the
     bank - and says so. Who eats a short treasury is Dan's ruling
     (roadmap decision 4). */
  IF v_period_total > COALESCE(v_wallet.rake_wallet, 0) THEN
    UPDATE ca_settlements SET state = 'failed', error_detail = 'insufficient_rake_treasury' WHERE id = v_sid;
    PERFORM public.fn_ca_raise_drift_incident(
      'rakeback_close', 'incorrect_rakeback', 'critical',
      'rakeback-insufficient:' || p_union_id::text || ':' || to_char(p_period_start, 'YYYY-MM-DD'),
      v_period_total - COALESCE(v_wallet.rake_wallet, 0),
      v_period_total,
      COALESCE(v_wallet.rake_wallet, 0),
      'settlement', 'union', p_union_id, NULL, p_union_id,
      NULL, NULL, NULL, v_sid::text, NULL, NULL,
      'union rake treasury cannot cover the period it owes; close refused before any movement (the general bank is never a source)',
      true,
      jsonb_build_object('rake_wallet', v_wallet.rake_wallet,
                         'chip_balance', v_wallet.chip_balance,
                         'period_total', v_period_total,
                         'payout', v_payout_total, 'retained', v_retained,
                         'period_start', p_period_start, 'period_end', p_period_end));
    RETURN jsonb_build_object('success', false, 'error', 'insufficient_rake_treasury', 'retryable', true,
      'period_rake', v_period_total, 'payout', v_payout_total,
      'rake_wallet', v_wallet.rake_wallet, 'chip_balance', v_wallet.chip_balance,
      'settlement_id', v_sid);
  END IF;

  UPDATE ca_settlements SET state = 'validated' WHERE id = v_sid;

  SELECT jsonb_object_agg(k,current_setting(k,true)) INTO v_prior_context FROM unnest(ARRAY[
    'app.ledger_autoskip_clubs','app.ledger_autoskip_union_wallets','app.ledger_category',
    'app.ledger_counterparty','app.ledger_counterparty_entity','app.ledger_settlement'])k;
  -- guarded money section: all of it lands, or none of it does
  BEGIN
    /* One declaration for every balance write below. The union_wallets
       auto-ledger is skipped: the union side of each club credit is the
       from-leg of the club's own row, and the retained share is written
       explicitly. */
    PERFORM public.fn_ca_declare_ledger('rakeback', 'union_wallet', p_union_id, v_sid, NULL,
                                        ARRAY['union_wallets','clubs']);
    v_actor := COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);

    v_rw_before := round(COALESCE(v_wallet.rake_wallet, 0), 2);
    v_cb_before := round(COALESCE(v_wallet.chip_balance, 0), 2);
    SELECT round(COALESCE(SUM(c.chip_treasury), 0), 2) INTO v_clubs_before
      FROM clubs c
     WHERE c.id IN (SELECT club_id FROM _uwrb
                     WHERE club_id IS NOT NULL AND club_id <> p_union_id AND payout > 0);

    FOR v_club IN
      SELECT club_id, rake_in, payout FROM _uwrb
       WHERE club_id IS NOT NULL AND club_id <> p_union_id AND payout > 0 ORDER BY club_id
    LOOP
      v_credit := fn_credit_treasury(
        v_club.club_id, v_club.payout,
        'Union weekly rakeback ' || to_char(p_period_start, 'YYYY-MM-DD')
          || '..' || to_char(p_period_end, 'YYYY-MM-DD'),
        jsonb_build_object('union_id', p_union_id,
                           'period_start', p_period_start, 'period_end', p_period_end,
                           'rake_basis', v_club.rake_in, 'rate', 'per_game_type',
                           'by_game_type', (SELECT COALESCE(jsonb_object_agg(game_type,
                                                     jsonb_build_object('basis', rake_in, 'rate', rate, 'payout', payout)), '{}'::jsonb)
                                              FROM _uwrb_by_type g WHERE g.club_id = v_club.club_id),
                           'settlement_id', v_sid),
        'union_close:' || v_sid::text || ':' || v_club.club_id::text
      );
      IF COALESCE((v_credit->>'success')::boolean, false) IS NOT TRUE THEN
        RAISE EXCEPTION 'treasury credit failed for club %: %', v_club.club_id, v_credit;
      END IF;
      -- The earning union is explicit even if the club has since left or
      -- joined another union. Do not derive this journal scope from the club's
      -- current union_id via its generic balance trigger.
      INSERT INTO public.chip_ledger(performed_by,from_type,from_entity_id,to_type,to_entity_id,amount,category,
        club_id,union_id,description,idempotency_key,metadata,pre_to_balance,post_to_balance,from_label)
      VALUES(v_actor,'union_wallet',p_union_id,'club_treasury',v_club.club_id,v_club.payout,'rakeback',
        v_club.club_id,p_union_id,'Union weekly rakeback from recorded earnings',
        'union_close:'||v_sid::text||':'||v_club.club_id::text,
        jsonb_build_object('settlement_id',v_sid,'period_start',p_period_start,'period_end',p_period_end,
          'rake_basis',v_club.rake_in,'accounting_version',3,'source_fingerprint',v_source_plan->'source_fingerprint'),
        (v_credit->>'balance_before')::numeric,(v_credit->>'balance_after')::numeric,'union_wallets.rake_wallet') RETURNING id INTO v_ledger_id;
      IF NOT EXISTS(SELECT 1 FROM public.settlement_invoices i WHERE i.source_ledger_id=v_ledger_id AND i.status='paid'
        AND i.net_amount=v_club.payout AND i.chips_transferred AND i.message_sent
        AND EXISTS(SELECT 1 FROM public.accounting_invoice_deliveries d WHERE d.invoice_id=i.id)) THEN
        RAISE EXCEPTION 'union_close_invoice_receipt_missing' USING ERRCODE='23514';
      END IF;
      v_clubs_paid := v_clubs_paid + 1;
    END LOOP;

    -- THE UNION WALLET DEBIT (20260929): one guarded update in
    -- fn_union_close_post_rake_debit. Inside the weekly cascade it is posted as
    -- the cascade's last write, so the row every hand credits is held only
    -- from then to commit; called on its own, it is posted here, as before.
    v_pending := jsonb_build_object('union_id', p_union_id, 'settlement_id', v_sid,
      'period_start', p_period_start, 'period_end', p_period_end,
      'period_total', v_period_total, 'payout_total', v_payout_total, 'retained', v_retained,
      'clubs_paid', v_clubs_paid, 'actor', v_actor,
      'clubs', (SELECT COALESCE(jsonb_agg(jsonb_build_object('club_id', club_id, 'payout', payout) ORDER BY club_id), '[]'::jsonb)
                  FROM _uwrb WHERE club_id IS NOT NULL AND club_id <> p_union_id AND payout > 0));
    IF current_setting('app.union_close_defer_rake_debit', true) = v_sref THEN
      IF NULLIF(current_setting('app.union_close_pending_rake_debit', true), '') IS NOT NULL THEN
        RAISE EXCEPTION 'union_close_rake_debit_already_pending' USING ERRCODE='55000';
      END IF;
      PERFORM set_config('app.union_close_pending_rake_debit', v_pending::text, true);
      v_deferred := true;
      -- the union side is proved when it posts; the clubs side is proved below
      v_rw_before := 0; v_new_rw := -v_period_total; v_cb_before := 0; v_new_cb := v_retained;
    ELSE
      SELECT d.rw_before, d.rw_after, d.cb_before, d.cb_after INTO v_rw_before, v_new_rw, v_cb_before, v_new_cb
        FROM public.fn_union_close_post_rake_debit(v_pending) d;
    END IF;

    /* CONSERVATION, ASSERTED ON THE BALANCES THEMSELVES (not on the plan).
       What left the treasury must equal what the clubs and the bank received,
       to the cent, or none of it lands. */
    SELECT round(COALESCE(SUM(c.chip_treasury), 0), 2) INTO v_clubs_after
      FROM clubs c
     WHERE c.id IN (SELECT club_id FROM _uwrb
                     WHERE club_id IS NOT NULL AND club_id <> p_union_id AND payout > 0);

    IF round((v_new_rw - v_rw_before) + (v_new_cb - v_cb_before) + (v_clubs_after - v_clubs_before), 2) <> 0
       OR round(v_new_rw - v_rw_before, 2) <> round(-v_period_total, 2)
       OR round(v_clubs_after - v_clubs_before, 2) <> round(v_payout_total, 2)
       OR round(v_new_cb - v_cb_before, 2) <> round(v_retained, 2) THEN
      RAISE EXCEPTION 'conservation violation in the weekly union close: treasury % -> %, bank % -> %, clubs % -> %, period % payout % retained %',
        v_rw_before, v_new_rw, v_cb_before, v_new_cb, v_clubs_before, v_clubs_after,
        v_period_total, v_payout_total, v_retained;
    END IF;

    IF v_deferred THEN v_new_rw := NULL; v_new_cb := NULL; END IF;
    UPDATE ca_settlements
       SET state = 'ledger_posted',
           totals = totals || jsonb_build_object('clubs_paid', v_clubs_paid,
                                                 'retained', v_retained,
                                                 'rw_debit', v_period_total,
                                                 'conservation', 'asserted')
     WHERE id = v_sid;

    INSERT INTO union_rakeback_log (union_id, period_start, period_end, total_rakeback, executed_at)
    VALUES (p_union_id, p_period_start, p_period_end, v_payout_total, now());

  EXCEPTION WHEN OTHERS THEN
    -- every money movement above just rolled back to the section start
    UPDATE ca_settlements
       SET state = 'failed', error_detail = left(SQLERRM, 2000)
     WHERE id = v_sid;
    PERFORM public.fn_ca_raise_drift_incident(
      'rakeback_close', 'incorrect_rakeback', 'critical',
      'rakeback-close-failed:' || p_union_id::text || ':' || to_char(p_period_start, 'YYYY-MM-DD'),
      0, NULL, NULL,
      'settlement', 'union', p_union_id, NULL, p_union_id,
      NULL, NULL, NULL, v_sid::text, NULL, NULL,
      left('weekly rakeback close aborted mid-flight and rolled back cleanly: ' || SQLERRM, 500),
      true,
      jsonb_build_object('sqlstate', SQLSTATE,
                         'period_start', p_period_start, 'period_end', p_period_end,
                         'clubs_paid_before_abort', v_clubs_paid));
    RETURN jsonb_build_object('success', false, 'error', 'close_failed', 'retryable', true,
      'detail', SQLERRM, 'settlement_id', v_sid);
  END;

  FOR context_key IN SELECT jsonb_object_keys(v_prior_context) LOOP
    PERFORM set_config(context_key,COALESCE(v_prior_context->>context_key,''),true);
  END LOOP;
  UPDATE ca_settlements SET state = 'post_commit_verified' WHERE id = v_sid;
  UPDATE ca_settlements SET state = 'final' WHERE id = v_sid;

  RETURN jsonb_build_object('success', true,
    'clubs_paid', v_clubs_paid,
    'period_rake', v_period_total,
    'total_rakeback', v_payout_total,
    'union_retained', v_retained,
    'retained_to_bank', v_retained,
    'rake_wallet_after', v_new_rw,
    'chip_balance_after', v_new_cb,
    'conservation', 'asserted',
    'settlement_id', v_sid);
END
$$;

CREATE FUNCTION public.fn_weekly_accounting_deadline_check() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE deadline text:=current_setting('app.weekly_accounting_scope_deadline',true);
BEGIN
 IF deadline IS NOT NULL AND deadline<>'' AND clock_timestamp()>deadline::timestamptz THEN
  RAISE EXCEPTION 'weekly_scope_time_budget_exhausted' USING DETAIL=jsonb_build_object('deadline',deadline,
   'budget',COALESCE(NULLIF(current_setting('app.weekly_accounting_scope_budget',true),''),'8 minutes'),'at',clock_timestamp())::text;
 END IF;
END $$;

CREATE FUNCTION public.guard_agent_wallet_direct_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if current_user in ('authenticated','anon') then
    if tg_op='INSERT' and (
      coalesce(new.agent_wallet_balance,0)<>0 or coalesce(new.business_balance,0)<>0 or
      coalesce(new.player_wallet_balance,0)<>0 or coalesce(new.player_balance,0)<>0 or
      coalesce(new.promo_wallet_balance,0)<>0 or coalesce(new.promo_balance,0)<>0 or
      coalesce(new.credit_limit,0)<>0 or coalesce(new.credit_used,0)<>0 or
      coalesce(new.commission_rate,0)<>0 or coalesce(new.player_rakeback_rate,0)<>0
    ) then
      raise exception 'Agent financial accounts may only be created through authorized operations';
    elsif tg_op='UPDATE' and (
      new.agent_wallet_balance is distinct from old.agent_wallet_balance or
      new.business_balance is distinct from old.business_balance or
      new.player_wallet_balance is distinct from old.player_wallet_balance or
      new.player_balance is distinct from old.player_balance or
      new.promo_wallet_balance is distinct from old.promo_wallet_balance or
      new.promo_balance is distinct from old.promo_balance or
      new.credit_limit is distinct from old.credit_limit or
      new.credit_used is distinct from old.credit_used or
      new.commission_rate is distinct from old.commission_rate or
      new.player_rakeback_rate is distinct from old.player_rakeback_rate
    ) then
      raise exception 'Agent financial accounts may only change through authorized operations';
    end if;
  end if;
  return new;
end
$$;

CREATE FUNCTION public.refresh_player_stats() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
    DECLARE v_count INTEGER := 0;
    BEGIN
      INSERT INTO player_stats (user_id, club_id, hands_played, total_winnings, total_losses)
      SELECT hp.user_id, t.club_id, COUNT(*)::INTEGER as hands_played,
        COALESCE(SUM(hp.chips_won), 0) as total_winnings, COALESCE(SUM(hp.chips_lost), 0) as total_losses
      FROM hand_players hp JOIN hands h ON h.id = hp.hand_id JOIN tables t ON t.id = h.table_id
      WHERE t.club_id IS NOT NULL GROUP BY hp.user_id, t.club_id
      ON CONFLICT (user_id, club_id) DO UPDATE SET
        hands_played = EXCLUDED.hands_played, total_winnings = EXCLUDED.total_winnings,
        total_losses = EXCLUDED.total_losses, updated_at = NOW();
      GET DIAGNOSTICS v_count = ROW_COUNT;
      RETURN v_count;
    END; $$;

CREATE FUNCTION public.sync_agent_wallet_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$ BEGIN IF NEW.agent_wallet_balance IS DISTINCT FROM OLD.agent_wallet_balance THEN NEW.business_balance := NEW.agent_wallet_balance; ELSIF NEW.business_balance IS DISTINCT FROM OLD.business_balance THEN NEW.agent_wallet_balance := NEW.business_balance; END IF; IF NEW.player_wallet_balance IS DISTINCT FROM OLD.player_wallet_balance THEN NEW.player_balance := NEW.player_wallet_balance; ELSIF NEW.player_balance IS DISTINCT FROM OLD.player_balance THEN NEW.player_wallet_balance := NEW.player_balance; END IF; IF NEW.promo_wallet_balance IS DISTINCT FROM OLD.promo_wallet_balance THEN NEW.promo_balance := NEW.promo_wallet_balance; ELSIF NEW.promo_balance IS DISTINCT FROM OLD.promo_balance THEN NEW.promo_wallet_balance := NEW.promo_balance; END IF; RETURN NEW; END; $$;

CREATE FUNCTION public.trg_ca_reporting_rake_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_day date; r record;
BEGIN
  IF NOT NEW.is_tournament OR NEW.tournament_id IS NULL OR NEW.rake_amount=0
    THEN RETURN NULL; END IF;
  /* SHARED, not exclusive - see trg_ca_reporting_wallet_insert and
     20260906152215. */
  PERFORM pg_advisory_xact_lock_shared(918273645);
  v_day:=(NEW.created_at AT TIME ZONE 'UTC')::date;
  IF NEW.metadata ? 'user_id' THEN
    FOR r IN
      SELECT c.club_id FROM public.tournament_players tp
      CROSS JOIN LATERAL public.ca_reporting_tournament_clubs_for_user(tp.user_id) c
      WHERE tp.tournament_id=NEW.tournament_id
        AND tp.user_id::text=NEW.metadata->>'user_id'
      ORDER BY c.club_id
    LOOP
      INSERT INTO public.ca_club_tournament_daily AS d
        (club_id,tournament_id,stat_date,fee,updated_at)
      VALUES(r.club_id,NEW.tournament_id,v_day,NEW.rake_amount,now())
      ON CONFLICT(club_id,tournament_id,stat_date) DO UPDATE
       SET fee=d.fee+EXCLUDED.fee,updated_at=now();
    END LOOP;
  ELSE
    FOR r IN
      WITH total AS (SELECT count(*)::numeric n FROM public.tournament_players
                      WHERE tournament_id=NEW.tournament_id), mapped AS (
        SELECT c.club_id FROM public.tournament_players tp
        CROSS JOIN LATERAL public.ca_reporting_tournament_clubs_for_user(tp.user_id) c
        WHERE tp.tournament_id=NEW.tournament_id)
      SELECT m.club_id,count(*)::numeric AS club_players,t.n AS total_players
        FROM mapped m CROSS JOIN total t GROUP BY m.club_id,t.n
       ORDER BY m.club_id
    LOOP
      INSERT INTO public.ca_club_tournament_daily AS d
        (club_id,tournament_id,stat_date,fee,updated_at)
      VALUES(r.club_id,NEW.tournament_id,v_day,
             NEW.rake_amount*r.club_players/NULLIF(r.total_players,0),now())
      ON CONFLICT(club_id,tournament_id,stat_date) DO UPDATE
       SET fee=d.fee+EXCLUDED.fee,updated_at=now();
    END LOOP;
  END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Club Data rake rollup failed for row %: %',NEW.id,SQLERRM;
  RETURN NULL;
END;
$$;CREATE FUNCTION public.trg_ca_reporting_wallet_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_club uuid; v_union uuid; v_table_club uuid; v_is_tournament_table boolean; v_day date;
  v_cash numeric:=0; v_tournament numeric:=0; r record;
BEGIN
  -- 2026-09-04: a table add-on (top-up), a rebuy and a refund move cash-table
  -- money too, and a tournament add-on, rebuy, refund or prize reversal moves
  -- tournament money; this knew buy-in, cash-out, tournament buy-in, prize
  -- and bounty alone. A row with a table is cash; a row with a tournament and
  -- no table is tournament. The sign is the row's own type, never its name.
  IF NOT ((NEW.category IN('buyin','cashout','addon','rebuy','refund') AND NEW.table_id IS NOT NULL)
    OR (NEW.category IN('tournament_buyin','prize','bounty','addon','rebuy','refund','prize_reversal')
        AND NEW.related_entity_id IS NOT NULL AND NEW.table_id IS NULL))
    THEN RETURN NULL; END IF;
  /* SHARED, not exclusive (20260906152215). The exclusive form serialised
     every chip movement on the platform behind one lock and held it to
     commit: 2,731 waits over a second in one day, 2,916 statement timeouts,
     and the deadlock cycles that failed prize credits. Shared holders never
     block each other; only the range rebuilds take the exclusive lock, and
     they still wait for every in-flight trigger before they delete a day. */
  PERFORM pg_advisory_xact_lock_shared(918273645);
  v_day:=(NEW.created_at AT TIME ZONE 'UTC')::date;
  IF NEW.table_id IS NOT NULL THEN
    SELECT t.union_id,t.club_id,(t.tournament_id IS NOT NULL)
      INTO v_union,v_table_club,v_is_tournament_table
      FROM public.tables t WHERE t.id=NEW.table_id;
    IF v_is_tournament_table THEN RETURN NULL; END IF;
    IF v_union IS NULL THEN
      -- A standalone table: the club is the table's club.
      v_club:=v_table_club;
    ELSE
      SELECT cm.club_id INTO v_club FROM public.club_members cm
        JOIN public.union_clubs uc ON uc.club_id=cm.club_id AND uc.union_id=v_union
       WHERE cm.user_id=NEW.user_id
       ORDER BY cm.joined_at ASC NULLS LAST,cm.club_id LIMIT 1;
    END IF;
    v_cash:=CASE WHEN NEW.type='credit' THEN NEW.amount
                 WHEN NEW.type='debit' THEN -NEW.amount ELSE 0 END;
    IF v_club IS NOT NULL THEN
      INSERT INTO public.ca_club_player_daily AS d
        (club_id,user_id,stat_date,cash_net,tournament_net,updated_at)
      VALUES(v_club,NEW.user_id,v_day,v_cash,0,now())
      ON CONFLICT(club_id,user_id,stat_date) DO UPDATE
       SET cash_net=d.cash_net+EXCLUDED.cash_net,updated_at=now();
    END IF;
  ELSE
    v_tournament:=CASE WHEN NEW.type='credit' THEN NEW.amount
                       WHEN NEW.type='debit' THEN -NEW.amount ELSE 0 END;
    /* ORDER BY club_id: two credits to players of the same event upsert the
       shared ca_club_tournament_daily rows in one order, so they wait on each
       other instead of cycling. */
    FOR r IN SELECT c.club_id FROM public.ca_reporting_tournament_clubs_for_user(NEW.user_id) c
              ORDER BY c.club_id LOOP
      INSERT INTO public.ca_club_player_daily AS d
        (club_id,user_id,stat_date,cash_net,tournament_net,updated_at)
      VALUES(r.club_id,NEW.user_id,v_day,0,v_tournament,now())
      ON CONFLICT(club_id,user_id,stat_date) DO UPDATE
       SET tournament_net=d.tournament_net+EXCLUDED.tournament_net,updated_at=now();
      INSERT INTO public.ca_club_tournament_daily AS d
        (club_id,tournament_id,stat_date,winnings,updated_at)
      VALUES(r.club_id,NEW.related_entity_id,v_day,v_tournament,now())
      ON CONFLICT(club_id,tournament_id,stat_date) DO UPDATE
       SET winnings=d.winnings+EXCLUDED.winnings,updated_at=now();
      INSERT INTO public.ca_club_tournament_player_daily
        (club_id,tournament_id,user_id,stat_date,updated_at)
      VALUES(r.club_id,NEW.related_entity_id,NEW.user_id,v_day,now())
      ON CONFLICT(club_id,tournament_id,user_id,stat_date) DO UPDATE SET updated_at=now();
    END LOOP;
  END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Club Data wallet rollup failed for tx %: %',NEW.id,SQLERRM;
  RETURN NULL;
END;
$$;CREATE FUNCTION public.trg_hand_history_club_member_stats() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE v_club uuid; v_date date; v_tourney boolean;
BEGIN
  IF coalesce(current_setting('app.atomic_hand_commit',true),'')='on' THEN RETURN NEW; END IF;
  SELECT t.club_id,(t.tournament_id IS NOT NULL)
    INTO v_club,v_tourney FROM public.tables t WHERE t.id=NEW.table_id;
  IF v_club IS NULL THEN RETURN NEW; END IF;
  v_tourney := coalesce(v_tourney,false) OR (NEW.tournament_id IS NOT NULL);
  v_date := (NEW.created_at AT TIME ZONE 'UTC')::date;
  WITH pl AS (
    SELECT DISTINCT ON (p->>'userId') (p->>'userId')::uuid AS uid,
           (p->>'stack')::numeric AS stack
      FROM jsonb_array_elements(coalesce(NEW.players,'[]'::jsonb)) p
     WHERE (p->>'userId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       AND (p->>'stack') IS NOT NULL
  ), wn AS (
    SELECT (w->>'userId')::uuid AS uid,sum((w->>'amount')::numeric) AS won
      FROM jsonb_array_elements(coalesce(NEW.winners,'[]'::jsonb)) w
     WHERE (w->>'userId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     GROUP BY 1
  ), base AS (
    SELECT pl.uid,pl.stack,coalesce(wn.won,0) AS won,st.last_stack,
      (st.last_stack IS NOT NULL AND st.last_hand_number IS NOT NULL
       AND NEW.hand_number IS NOT NULL AND NOT EXISTS (
         SELECT 1 FROM public.hand_history h2 WHERE h2.table_id=NEW.table_id
          AND h2.hand_number>st.last_hand_number AND h2.hand_number<NEW.hand_number)) AS adjacent
      FROM pl LEFT JOIN wn ON wn.uid=pl.uid
      LEFT JOIN public.club_member_table_state st
        ON st.table_id=NEW.table_id AND st.user_id=pl.uid
  ), agg AS (
    SELECT count(*) AS seated,count(*) FILTER (WHERE last_stack IS NOT NULL) AS with_prior,
           coalesce(sum(stack-last_stack) FILTER (WHERE last_stack IS NOT NULL),0) AS dsum
      FROM base
  ), calc AS (
    SELECT b.uid,b.won,
      CASE WHEN b.last_stack IS NOT NULL THEN b.stack-b.last_stack ELSE 0 END AS delta,
      CASE WHEN a.seated=a.with_prior
        THEN abs(a.dsum+coalesce(NEW.rake_amount,0)+coalesce(NEW.bbj_amount,0))<0.005
        ELSE b.adjacent AND (b.stack-b.last_stack)<=b.won+0.001 END AS attributable
      FROM base b CROSS JOIN agg a
  )
  INSERT INTO public.club_member_daily_stats AS s(
    club_id,table_id,user_id,stat_date,hands_played,hands_attributed,hands_won,
    total_won,profit,biggest_pot_won,biggest_pot,topup_total)
  SELECT v_club,NEW.table_id,calc.uid,v_date,1,
    CASE WHEN v_tourney THEN 0 WHEN calc.attributable THEN 1 ELSE 0 END,
    CASE WHEN calc.won>0 THEN 1 ELSE 0 END,
    CASE WHEN v_tourney THEN 0 ELSE calc.won END,
    CASE WHEN v_tourney THEN 0 WHEN calc.attributable THEN calc.delta ELSE 0 END,
    CASE WHEN v_tourney THEN 0 ELSE calc.won END,
    CASE WHEN v_tourney THEN 0 ELSE coalesce(NEW.pot_size,0) END,
    CASE WHEN v_tourney THEN 0 WHEN NOT calc.attributable AND calc.delta>calc.won
      THEN calc.delta-calc.won ELSE 0 END
    FROM calc
  ON CONFLICT (club_id,table_id,user_id,stat_date) DO UPDATE SET
    hands_played=s.hands_played+1,
    hands_attributed=s.hands_attributed+EXCLUDED.hands_attributed,
    hands_won=s.hands_won+EXCLUDED.hands_won,
    total_won=s.total_won+EXCLUDED.total_won,
    profit=s.profit+EXCLUDED.profit,
    biggest_pot_won=greatest(s.biggest_pot_won,EXCLUDED.biggest_pot_won),
    biggest_pot=greatest(s.biggest_pot,EXCLUDED.biggest_pot),
    topup_total=s.topup_total+EXCLUDED.topup_total,
    updated_at=now();
  INSERT INTO public.club_member_table_state AS st(
    table_id,user_id,last_stack,last_hand_number)
  SELECT DISTINCT ON (p->>'userId') NEW.table_id,(p->>'userId')::uuid,
         (p->>'stack')::numeric,NEW.hand_number
    FROM jsonb_array_elements(coalesce(NEW.players,'[]'::jsonb)) p
   WHERE (p->>'userId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     AND (p->>'stack') IS NOT NULL
  ON CONFLICT (table_id,user_id) DO UPDATE SET
    last_stack=EXCLUDED.last_stack,last_hand_number=EXCLUDED.last_hand_number,
    updated_at=now();
  INSERT INTO public.club_hand_daily_shard AS d(
    club_id,stat_date,shard,hands,rake,bbj,pot_total)
  VALUES (v_club,v_date,(pg_backend_pid()%16)::smallint,1,
    coalesce(NEW.rake_amount,0),coalesce(NEW.bbj_amount,0),coalesce(NEW.pot_size,0))
  ON CONFLICT (club_id,stat_date,shard) DO UPDATE SET
    hands=d.hands+1,rake=d.rake+EXCLUDED.rake,bbj=d.bbj+EXCLUDED.bbj,
    pot_total=d.pot_total+EXCLUDED.pot_total,updated_at=now();
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'trg_hand_history_club_member_stats failed: %',SQLERRM;
  RETURN NEW;
END;
$_$;

CREATE FUNCTION public.trg_tournament_completed_stats() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status <> 'COMPLETED' OR COALESCE(OLD.status,'') = 'COMPLETED' THEN
    RETURN NEW;
  END IF;

  INSERT INTO player_stats (user_id, club_id, tournaments_played, tournaments_won, updated_at)
  SELECT tp.user_id,
         NEW.club_id,
         1,
         CASE WHEN tp.position = 1 OR tp.status = 'winner' THEN 1 ELSE 0 END,
         now()
    FROM tournament_players tp
   WHERE tp.tournament_id = NEW.id
     AND tp.user_id IS NOT NULL
  ON CONFLICT (user_id, club_id) DO UPDATE
     SET tournaments_played = COALESCE(player_stats.tournaments_played,0)
                            + EXCLUDED.tournaments_played,
         tournaments_won    = COALESCE(player_stats.tournaments_won,0)
                            + EXCLUDED.tournaments_won,
         updated_at = now();
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.trg_union_rake_weekly() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.union_id IS NOT NULL
     AND NEW.wallet = 'rake_wallet'
     AND NEW.direction = 'credit'
     AND NEW.tx_type = 'rake' THEN
    INSERT INTO public.union_rake_weekly (union_id, club_id, week_start, rake_total, updated_at)
    VALUES (NEW.union_id, NEW.club_id, date_trunc('week', NEW.created_at)::date,
            COALESCE(NEW.amount, 0), now())
    ON CONFLICT ON CONSTRAINT union_rake_weekly_key DO UPDATE
      SET rake_total = public.union_rake_weekly.rake_total + EXCLUDED.rake_total,
          updated_at = now();
  END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  -- Never let a display rollup block the engine banking rake. A failure here
  -- costs a stale panel; the function's fallback still reads the ledger.
  RAISE WARNING 'union_rake_weekly maintenance failed for tx %: %', NEW.id, SQLERRM;
  RETURN NULL;
END
$$;CREATE FUNCTION public.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;

