n) FROM PUBLIC;GRANT ALL ON FUNCTION public.fn_union_settle_player_pnl(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_dry_run boolean) TO service_role;REVOKE ALL ON FUNCTION public.fn_union_settlement_cascade(p_union_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) FROM PUBLIC;REVOKE ALL ON FUNCTION public.fn_union_settlement_conservation_assert(p_union_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_r1 jsonb, p_r2 jsonb, p_r3 jsonb) FROM PUBLIC;REVOKE ALL ON FUNCTION public.fn_union_week_start(p_at timestamp with time zone) FROM PUBLIC;GRANT ALL ON FUNCTION public.fn_union_week_start(p_at timestamp with time zone) TO authenticated;GRANT ALL ON FUNCTION public.fn_union_week_start(p_at timestamp with time zone) TO service_role;REVOKE ALL ON FUNCTION public.fn_union_weekly_rakeback_close(p_union_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) FROM PUBLIC;REVOKE ALL ON FUNCTION public.fn_weekly_accounting_deadline_check() FROM PUBLIC;REVOKE ALL ON FUNCTION public.guard_agent_wallet_direct_update() FROM PUBLIC;GRANT ALL ON FUNCTION public.guard_agent_wallet_direct_update() TO service_role;REVOKE ALL ON FUNCTION public.refresh_player_stats() FROM PUBLIC;GRANT ALL ON FUNCTION public.refresh_player_stats() TO service_role;REVOKE ALL ON FUNCTION public.sync_agent_wallet_columns() FROM PUBLIC;GRANT ALL ON FUNCTION public.sync_agent_wallet_columns() TO service_role;REVOKE ALL ON FUNCTION public.trg_ca_reporting_rake_insert() FROM PUBLIC;GRANT ALL ON FUNCTION public.trg_ca_reporting_rake_insert() TO service_role;REVOKE ALL ON FUNCTION public.trg_ca_reporting_wallet_insert() FROM PUBLIC;GRANT ALL ON FUNCTION public.trg_ca_reporting_wallet_insert() TO service_role;REVOKE ALL ON FUNCTION public.trg_hand_history_club_member_stats() FROM PUBLIC;REVOKE ALL ON FUNCTION public.trg_tournament_completed_stats() FROM PUBLIC;GRANT ALL ON FUNCTION public.trg_tournament_completed_stats() TO service_role;REVOKE ALL ON FUNCTION public.trg_union_rake_weekly() FROM PUBLIC;GRANT ALL ON FUNCTION public.trg_union_rake_weekly() TO service_role;REVOKE ALL ON FUNCTION public.update_updated_at_column() FROM PUBLIC;GRANT ALL ON FUNCTION public.update_updated_at_column() TO service_role;

CREATE TABLE public.bbj_stakes_tiers (
    id text NOT NULL,
    label text NOT NULL,
    blind_range text NOT NULL,
    min_bb numeric(10,2),
    max_bb numeric(10,2),
    rake_percent numeric(5,2) NOT NULL,
    rake_cap_bb numeric(5,2) NOT NULL,
    bbj_fee_bb numeric(5,2) NOT NULL,
    payout_total_pct numeric(5,2) NOT NULL,
    payout_loser_pct numeric(5,2) NOT NULL,
    payout_winner_pct numeric(5,2) NOT NULL,
    payout_table_pct numeric(5,2) NOT NULL
);
CREATE TABLE public.bbj_unclaimed_shares (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    payout_id uuid NOT NULL,
    pool_id uuid,
    table_id uuid,
    user_id uuid NOT NULL,
    amount numeric(14,2) NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    paid_at timestamp with time zone,
    paid_note text,
    CONSTRAINT bbj_unclaimed_shares_amount_check CHECK ((amount > (0)::numeric))
);ALTER TABLE ONLY public.bbj_stakes_tiers
    ADD CONSTRAINT bbj_stakes_tiers_pkey PRIMARY KEY (id);ALTER TABLE ONLY public.bbj_unclaimed_shares
    ADD CONSTRAINT bbj_unclaimed_shares_pkey PRIMARY KEY (id);CREATE FUNCTION public.fn_anon_exposure_check() RETURNS TABLE(invariant text, severity text, offenders bigint, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 'money_fn_exposed_to_anon', 'critical', count(*),
         'Financial functions callable by anon (no login). Postgres grants '
         || 'EXECUTE to PUBLIC by default and Supabase publishes every public '
         || 'function, so each of these is one REVOKE away from safe: '
         || COALESCE(string_agg(x.proname, ', ' ORDER BY x.proname), '')
    FROM (
      SELECT p.proname
        FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace AND n.nspname = 'public'
       WHERE has_function_privilege('anon', p.oid, 'EXECUTE')
         AND (p.proname LIKE 'fn_union_%'
              OR p.proname LIKE '%settle%'
              OR p.proname LIKE '%treasury%'
              OR p.proname LIKE '%rakeback%'
              OR p.proname LIKE '%agent_commission%'
              OR p.proname LIKE 'fn_union_rake%')
         AND p.proname NOT IN (
           -- see header for why each of these is intentionally reachable
           'fn_union_oversees_club',
           'fn_tournament_entry_split',
           'fn_union_week_start',
           -- IMMUTABLE date arithmetic, the sibling of fn_union_week_start
           'fn_union_prev_week_start',
           -- IMMUTABLE string transformation, reads nothing
           'fn_union_slugify',
           -- STABLE lobby headcount, not SECURITY DEFINER; the same numbers
           -- the signed-out lobby already shows
           'fn_union_active_player_counts')
    ) x
  HAVING count(*) > 0;
$$;


CREATE FUNCTION public.fn_bbj_analytics(p_pool_id uuid) RETURNS TABLE(main_balance numeric, backup_balance numeric, promo_balance numeric, contributions_24h numeric, contributions_7d numeric, contributions_30d numeric, hands_24h bigint, hands_7d bigint, total_contributed_all_time numeric, hit_count bigint, total_paid_all_time numeric, biggest_hit numeric, last_hit_at timestamp with time zone, avg_days_between_hits numeric, days_since_last_hit numeric, net_pool_position numeric, mini_enabled boolean, mini_hit_count bigint, mini_paid_all_time numeric, mini_hits_30d bigint, mini_paid_30d numeric, mini_last_hit_at timestamp with time zone, mini_reserve_floor numeric, mini_parked numeric, mini_available numeric, hands_30d bigint, main_hit_count bigint, main_paid_all_time numeric, main_avg_days_between_hits numeric, main_last_hit_at timestamp with time zone, main_days_since_last_hit numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_club_id uuid;
  v_union_id uuid;
  v_allowed boolean := false;
BEGIN
  SELECT bp.club_id, bp.union_id INTO v_club_id, v_union_id
  FROM public.bbj_pools bp WHERE bp.id = p_pool_id;

  IF v_club_id IS NULL AND v_union_id IS NULL THEN
    RAISE EXCEPTION 'BBJ pool not found';
  END IF;

  IF v_club_id IS NOT NULL THEN
    v_allowed := public.fn_is_club_admin_uid(v_club_id);
  ELSE
    SELECT EXISTS (
      SELECT 1 FROM public.clubs c
      WHERE c.union_id = v_union_id
        AND public.fn_is_club_admin_uid(c.id)
    ) INTO v_allowed;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'Not authorized: club admin role required for this jackpot pool';
  END IF;

  RETURN QUERY
  WITH pool AS (
    SELECT bp.main_balance, bp.backup_balance, bp.promo_balance,
           COALESCE(bp.mini_reserve_floor, 0) AS reserve_floor
    FROM public.bbj_pools bp WHERE bp.id = p_pool_id
  ),
  contrib AS (
    SELECT
      COALESCE(SUM(amount) FILTER (WHERE created_at > now() - interval '24 hours'), 0) AS c24,
      COALESCE(SUM(amount) FILTER (WHERE created_at > now() - interval '7 days'), 0) AS c7,
      COALESCE(SUM(amount) FILTER (WHERE created_at > now() - interval '30 days'), 0) AS c30,
      COUNT(*) FILTER (WHERE created_at > now() - interval '24 hours') AS h24,
      COUNT(*) FILTER (WHERE created_at > now() - interval '7 days') AS h7,
      COUNT(*) FILTER (WHERE created_at > now() - interval '30 days') AS h30,
      COALESCE(SUM(amount), 0) AS call_time
    FROM public.bbj_contributions WHERE pool_id = p_pool_id
  ),
  hits AS (
    SELECT
      COUNT(*) AS n,
      COALESCE(SUM(total_payout), 0) AS paid,
      COALESCE(MAX(total_payout), 0) AS biggest,
      MAX(awarded_at) AS last_at,
      MIN(awarded_at) AS first_at
    FROM public.bbj_winners WHERE pool_id = p_pool_id
  ),
  main_only AS (
    SELECT
      COUNT(*) AS n,
      COALESCE(SUM(total_payout), 0) AS paid,
      MAX(awarded_at) AS last_at,
      MIN(awarded_at) AS first_at
    FROM public.bbj_winners
    WHERE pool_id = p_pool_id AND COALESCE(kind, 'main') = 'main'
  ),
  mini AS (
    SELECT
      COUNT(*) AS n,
      COALESCE(SUM(total_payout), 0) AS paid,
      COUNT(*) FILTER (WHERE awarded_at > now() - interval '30 days') AS n30,
      COALESCE(SUM(total_payout) FILTER (WHERE awarded_at > now() - interval '30 days'), 0) AS paid30,
      MAX(awarded_at) AS last_at
    FROM public.bbj_winners WHERE pool_id = p_pool_id AND kind = 'mini'
  ),
  parked AS (
    SELECT public.fn_bbj_parked_reserve(p_pool_id, 'backup') AS amt
  )
  SELECT
    p.main_balance,
    p.backup_balance,
    p.promo_balance,
    c.c24, c.c7, c.c30,
    c.h24, c.h7,
    c.call_time,
    h.n, h.paid, h.biggest, h.last_at,
    CASE WHEN h.n > 1
      THEN ROUND(EXTRACT(EPOCH FROM (h.last_at - h.first_at)) / 86400.0 / (h.n - 1), 2)
      ELSE NULL END,
    CASE WHEN h.last_at IS NOT NULL
      THEN ROUND(EXTRACT(EPOCH FROM (now() - h.last_at)) / 86400.0, 2)
      ELSE NULL END,
    ROUND(c.call_time - h.paid, 2),
    EXISTS (SELECT 1 FROM public.bbj_mini_tiers t WHERE t.enabled),
    m.n, m.paid, m.n30, m.paid30, m.last_at,
    p.reserve_floor,
    pk.amt,
    GREATEST(0, COALESCE(p.backup_balance, 0) - pk.amt - p.reserve_floor),
    c.h30,
    mo.n,
    mo.paid,
    CASE WHEN mo.n > 1
      THEN ROUND(EXTRACT(EPOCH FROM (mo.last_at - mo.first_at)) / 86400.0 / (mo.n - 1), 2)
      ELSE NULL END,
    mo.last_at,
    CASE WHEN mo.last_at IS NOT NULL
      THEN ROUND(EXTRACT(EPOCH FROM (now() - mo.last_at)) / 86400.0, 2)
      ELSE NULL END
  FROM pool p, contrib c, hits h, mini m, main_only mo, parked pk;
END;
$$;


CREATE FUNCTION public.fn_bbj_mini_for_club(p_club_id uuid) RETURNS TABLE(pool_id uuid, enabled boolean, backup_balance numeric, reserve_floor numeric, parked numeric, available numeric, tiers jsonb, hits_30d bigint, paid_30d numeric, last_hit_at timestamp with time zone, club_switch boolean, can_toggle boolean, is_union_pool boolean, in_per_day numeric, out_per_day numeric, net_per_day numeric, days_to_floor numeric, floor_minimum numeric, window_days numeric, is_operator boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH caller AS (
    /* The function names its own actor rather than deriving it a call down.
       auth.uid() IS NULL is a service-role or pre-login caller; neither is
       club staff, and neither sees the rates. */
    SELECT auth.uid() AS uid,
           (auth.uid() IS NOT NULL AND public.fn_is_club_admin_uid(p_club_id)) AS is_operator
  ),
  club AS (
    SELECT c.id, c.union_id FROM public.clubs c WHERE c.id = p_club_id
  ),
  pool AS (
    SELECT p.pool_id, p.backup_balance, p.is_union_pool
      FROM public.fn_bbj_pool_for_club(p_club_id) p
  ),
  pool_row AS (
    SELECT bp.id, COALESCE(bp.mini_reserve_floor, 0) AS reserve_floor,
           COALESCE(bp.mini_enabled, true) AS mini_enabled
      FROM public.bbj_pools bp JOIN pool ON pool.pool_id = bp.id
  ),
  parked_row AS (
    SELECT public.fn_bbj_parked_reserve(pool.pool_id, 'backup') AS parked FROM pool
  ),
  tier_rows AS (
    SELECT st.id AS tier_id, st.label, st.blind_range, st.min_bb, st.max_bb,
           mt.amount, mt.enabled,
           (pool_row.mini_enabled
            AND mt.enabled
            AND COALESCE(pool.backup_balance, 0) - parked_row.parked - mt.amount
                >= pool_row.reserve_floor) AS payable
      FROM public.bbj_stakes_tiers st
      JOIN public.bbj_mini_tiers mt ON mt.tier_id = st.id
      CROSS JOIN pool CROSS JOIN pool_row CROSS JOIN parked_row
  ),
  hits AS (
    SELECT count(*) AS n,
           COALESCE(sum(w.total_payout), 0) AS paid,
           max(w.awarded_at) AS last_at
      FROM public.bbj_winners w JOIN pool ON w.pool_id = pool.pool_id
     WHERE w.kind = 'mini' AND w.awarded_at > now() - interval '30 days'
  ),
  win AS (
    SELECT GREATEST(0.5, LEAST(7.0, COALESCE(
             extract(epoch FROM (now() - (SELECT min(w.awarded_at)
                                            FROM public.bbj_winners w
                                           WHERE w.kind = 'mini'))) / 86400.0,
             7.0))) AS days
  ),
  flow AS (
    SELECT
      COALESCE((SELECT sum(x.backup_portion) FROM public.bbj_contributions x
                 JOIN pool ON x.pool_id = pool.pool_id
                WHERE x.created_at > now() - (win.days * interval '1 day')), 0)
        / win.days AS in_day,
      COALESCE((SELECT sum(w.total_payout) FROM public.bbj_winners w
                 JOIN pool ON w.pool_id = pool.pool_id
                WHERE w.kind = 'mini'
                  AND w.awarded_at > now() - (win.days * interval '1 day')), 0)
        / win.days AS out_day,
      win.days
      FROM win
  ),
  bound AS (
    SELECT COALESCE(max(mt.amount) FILTER (WHERE mt.enabled), 0) AS floor_min
      FROM public.bbj_mini_tiers mt
  )
  SELECT pool.pool_id,
         (pool_row.mini_enabled
          AND EXISTS (SELECT 1 FROM public.bbj_mini_tiers t WHERE t.enabled)) AS enabled,
         /* The reserve is part of what the jackpot IS, and players are already
            told about it (BBJRulesPanel, BadBeatJackpotPage). */
         COALESCE(pool.backup_balance, 0) AS backup_balance,
         pool_row.reserve_floor,
         parked_row.parked,
         GREATEST(0, COALESCE(pool.backup_balance, 0) - parked_row.parked - pool_row.reserve_floor)
           AS available,
         COALESCE((SELECT jsonb_agg(jsonb_build_object(
                     'tierId', tr.tier_id,
                     'label', tr.label,
                     'blindRange', tr.blind_range,
                     'minBB', tr.min_bb,
                     'maxBB', tr.max_bb,
                     'amount', tr.amount,
                     'enabled', tr.enabled,
                     'payable', tr.payable) ORDER BY tr.min_bb)
                   FROM tier_rows tr), '[]'::jsonb) AS tiers,
         hits.n AS hits_30d,
         hits.paid AS paid_30d,
         (SELECT max(w.awarded_at) FROM public.bbj_winners w
           WHERE w.pool_id = pool.pool_id AND w.kind = 'mini') AS last_hit_at,
         pool_row.mini_enabled AS club_switch,
         (club.union_id IS NULL AND COALESCE(pool.is_union_pool, false) IS NOT TRUE) AS can_toggle,
         COALESCE(pool.is_union_pool, false) AS is_union_pool,
         /* THE RATES ARE THE BUSINESS. in_per_day is a club's daily jackpot
            rake income. NULL, never zero, for anyone who may not see it. */
         CASE WHEN caller.is_operator THEN ROUND(flow.in_day, 2) END  AS in_per_day,
         CASE WHEN caller.is_operator THEN ROUND(flow.out_day, 2) END AS out_per_day,
         CASE WHEN caller.is_operator THEN ROUND(flow.in_day - flow.out_day, 2) END AS net_per_day,
         CASE WHEN caller.is_operator AND flow.out_day > flow.in_day
              THEN ROUND(
                     GREATEST(0, COALESCE(pool.backup_balance,0) - parked_row.parked
                                 - pool_row.reserve_floor)
                     / (flow.out_day - flow.in_day), 1)
              ELSE NULL END AS days_to_floor,
         CASE WHEN caller.is_operator THEN bound.floor_min END AS floor_minimum,
         CASE WHEN caller.is_operator THEN ROUND(flow.days, 2) END AS window_days,
         caller.is_operator
    FROM pool, pool_row, parked_row, hits, club, flow, bound, caller;
$$;


CREATE FUNCTION public.fn_bbj_parked_reserve(p_pool_id uuid, p_bank text) RETURNS numeric
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  -- A parked refund remains in this bank but is already owed, not spendable.
  -- Financial callers must hold bbj_pools FOR UPDATE before reading it.
  SELECT COALESCE(sum(u.amount),0) FROM public.bbj_unclaimed_shares u
  JOIN public.bbj_payouts p ON p.id=u.payout_id
  WHERE u.pool_id=p_pool_id AND u.paid_at IS NULL
    AND (CASE WHEN p.kind='mini' THEN 'backup' ELSE 'main' END)=p_bank;
$$;


CREATE FUNCTION public.fn_bbj_pool_for_club(p_club_id uuid) RETURNS TABLE(pool_id uuid, main_balance numeric, backup_balance numeric, promo_balance numeric, is_union_pool boolean, union_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH club AS (
    SELECT c.id, c.union_id FROM public.clubs c WHERE c.id = p_club_id
  )
  SELECT bp.id,
         bp.main_balance,
         bp.backup_balance,
         bp.promo_balance,
         bp.union_id IS NOT NULL,
         bp.union_id
  FROM public.bbj_pools bp, club
  WHERE bp.status = 'active'
    AND (
      (club.union_id IS NOT NULL AND bp.union_id = club.union_id)
      OR (club.union_id IS NULL AND bp.club_id = club.id)
    )
  -- Union pool wins if a stale club-level row also exists (matches the server).
  ORDER BY (bp.union_id IS NOT NULL) DESC
  LIMIT 1;
$$;


CREATE FUNCTION public.fn_club_commission_accrued(p_club_id uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_until timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_total numeric;
BEGIN
  IF p_club_id IS NULL THEN
    RETURN 0;
  END IF;

  -- Staff of THIS club, or a service caller. Anybody else gets zero rather than
  -- an error: this feeds a summary card, and a card is not the place to leak
  -- whether a club exists.
  IF NOT (public.fn_is_club_admin_uid(p_club_id)
          OR (auth.uid() IS NULL AND COALESCE(auth.role(), 'service_role') = 'service_role')) THEN
    RETURN 0;
  END IF;

  SELECT COALESCE(SUM(ac.amount), 0) INTO v_total
    FROM public.agent_commissions ac
   WHERE ac.club_id = p_club_id
     AND (p_since IS NULL OR ac.created_at >= p_since)
     AND (p_until IS NULL OR ac.created_at <  p_until);

  RETURN COALESCE(v_total, 0);
END;
$$;


CREATE FUNCTION public.fn_credit_treasury(p_club_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_op_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_prior jsonb;
  v_res jsonb;
BEGIN
  IF p_op_id IS NULL THEN
    RETURN public.fn_credit_treasury_zd4core(p_club_id, p_amount, p_reason, p_metadata);
  END IF;

  SELECT result INTO v_prior
    FROM public.ca_op_claims
   WHERE op_id = p_op_id AND fn_name = 'fn_credit_treasury';
  IF FOUND AND v_prior IS NOT NULL THEN
    RETURN v_prior || jsonb_build_object('replayed', true, 'op_id', p_op_id);
  ELSIF FOUND THEN
    DELETE FROM public.ca_op_claims
     WHERE op_id = p_op_id AND fn_name = 'fn_credit_treasury';
  END IF;

  INSERT INTO public.ca_op_claims (op_id, fn_name, claimed_by)
  VALUES (p_op_id, 'fn_credit_treasury', auth.uid());

  v_res := public.fn_credit_treasury_zd4core(p_club_id, p_amount, p_reason, p_metadata);

  IF COALESCE(v_res->>'success', '') = 'true' THEN
    UPDATE public.ca_op_claims
       SET result = v_res, finalized_at = now()
     WHERE op_id = p_op_id AND fn_name = 'fn_credit_treasury';
  ELSE
    DELETE FROM public.ca_op_claims
     WHERE op_id = p_op_id AND fn_name = 'fn_credit_treasury';
  END IF;

  RETURN v_res;
END;
$$;


CREATE FUNCTION public.fn_credit_treasury_zd4core(p_club_id uuid, p_amount numeric, p_reason text, p_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_before numeric;
  v_after numeric;
BEGIN
  IF p_club_id IS NULL OR p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid parameters');
  END IF;

  /* THE CALLER NAMES WHERE THE CHIPS COME FROM (2026-10-02,
     20261002140203). fn_union_weekly_rakeback_close and
     fn_accounting_legacy_pay_week declare and stand the clubs journal down;
     a caller that does neither would be refused at commit. Say so here, by
     name, before anything moves. */
  IF NULLIF(current_setting('app.ledger_counterparty', true), '') IS NULL
     AND COALESCE(current_setting('app.ledger_autoskip_clubs', true), '') <> '1' THEN
    RAISE EXCEPTION 'fn_credit_treasury_requires_a_declared_counterparty'
      USING ERRCODE = '23514',
            DETAIL  = 'a club treasury credit with no app.ledger_counterparty would be journalled against settlement_suspense',
            HINT    = 'The calling door declares where the chips come from (fn_ca_declare_ledger), or stands the clubs journal down and writes its own leg.';
  END IF;

  SELECT COALESCE(chip_treasury, 0) INTO v_before
  FROM clubs WHERE id = p_club_id FOR NO KEY UPDATE;

  IF v_before IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'club not found');
  END IF;

  UPDATE clubs
  SET chip_treasury = COALESCE(chip_treasury, 0) + p_amount,
      updated_at = NOW()
  WHERE id = p_club_id;
  v_after := v_before + p_amount;

  INSERT INTO chip_transactions (
    id, club_id, amount, transaction_type, notes, metadata, balance_after, created_at
  ) VALUES (
    gen_random_uuid(), p_club_id, p_amount,
    'treasury_credit', COALESCE(p_reason, 'Treasury credit'), p_metadata, v_after, NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'amount', p_amount,
    'balance_before', v_before,
    'balance_after', v_after
  );
END;
$$;


CREATE FUNCTION public.fn_union_accounting_run_at(p_period_end timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT (((p_period_end AT TIME ZONE 'America/Chicago')::date + time '04:00')
           AT TIME ZONE 'America/Chicago');
$$;


CREATE FUNCTION public.fn_union_club_exposure(p_union_id uuid, p_week_start timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(club_id uuid, club_name text, week_start timestamp with time zone, running_net numeric, presettled numeric, exposure numeric, security_deposit numeric, stop_loss_limit numeric, headroom numeric, breached boolean, terms_on_file boolean, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start timestamptz := COALESCE(p_week_start, fn_union_week_start());
BEGIN
  RETURN QUERY
  WITH rep AS (
    -- inherits the reconciliation report's own authorization check
    SELECT r.club_id, r.club_name, r.settle_net
      FROM fn_union_reconciliation_report(p_union_id, v_start, now()) r
  ),
  pre AS (
    -- Unapplied cash the club has already handed over. Closed out by
    -- applied_settlement_id, never by age: money paid during a week that did
    -- not settle still offsets exposure.
    SELECT p.club_id, COALESCE(SUM(p.amount), 0) AS amt
      FROM union_presettlements p
     WHERE p.union_id = p_union_id
       AND p.applied_settlement_id IS NULL
     GROUP BY p.club_id
  )
  SELECT rep.club_id,
         rep.club_name,
         v_start,
         rep.settle_net,
         COALESCE(pre.amt, 0),
         GREATEST(0, round(-rep.settle_net - COALESCE(pre.amt, 0), 2)) AS exposure,
         COALESCE(t.security_deposit, 0),
         t.stop_loss_limit,
         CASE WHEN t.stop_loss_limit IS NULL THEN NULL
              ELSE round(t.stop_loss_limit
                         - GREATEST(0, -rep.settle_net - COALESCE(pre.amt, 0)), 2) END,
         CASE WHEN t.stop_loss_limit IS NULL THEN false
              ELSE GREATEST(0, -rep.settle_net - COALESCE(pre.amt, 0)) > t.stop_loss_limit END,
         (t.club_id IS NOT NULL),
         COALESCE(t.status, 'no_terms')
    FROM rep
    LEFT JOIN pre ON pre.club_id = rep.club_id
    LEFT JOIN union_club_terms t
           ON t.union_id = p_union_id AND t.club_id = rep.club_id
   ORDER BY exposure DESC;
END;
$$;


CREATE FUNCTION public.fn_union_reconciliation_report(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS TABLE(club_id uuid, club_name text, buyins numeric, cashouts numeric, realized_net numeric, seated_start numeric, seated_end numeric, stack_delta numeric, rake_paid numeric, settle_net numeric, direction text, turnover numeric, house_residual numeric, tolerance numeric, within_tolerance boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE proof jsonb;
BEGIN
 IF auth.uid() IS NOT NULL
  AND NOT EXISTS(SELECT 1 FROM unions u WHERE u.id=p_union_id AND u.owner_id=auth.uid())
  AND NOT EXISTS(SELECT 1 FROM union_admins ua WHERE ua.union_id=p_union_id AND ua.user_id=auth.uid())
  AND NOT EXISTS(SELECT 1 FROM union_clubs uc JOIN club_members cm ON cm.club_id=uc.club_id
   WHERE uc.union_id=p_union_id AND cm.user_id=auth.uid() AND cm.role IN('owner','co_owner','admin','super_agent')) THEN
  RAISE EXCEPTION 'not authorized to read union reconciliation' USING ERRCODE='42501'; END IF;
 proof:=public.fn_union_pnl_qualified_clubs(p_union_id,p_start,p_end);
 RETURN QUERY WITH rows AS(SELECT x,(x->>'club_id')::uuid id,(x->>'net')::numeric net,
  (x->>'buyins')::numeric+(x->>'cashouts')::numeric turnover FROM jsonb_array_elements(proof->'clubs') x),
 totals AS(SELECT sum(r.net) residual,greatest(100,round(sum(r.turnover)*0.01,2)) tolerance FROM rows r)
 SELECT r.id,c.name::text,(x->>'buyins')::numeric,(x->>'cashouts')::numeric,(x->>'realized_net')::numeric,
  (x->>'seated_start')::numeric,(x->>'seated_end')::numeric,(x->>'stack_delta')::numeric,(x->>'rake_paid')::numeric,r.net,
  CASE WHEN r.net<0 THEN 'club pays union' WHEN r.net>0 THEN 'union pays club' ELSE 'square' END,
  r.turnover,t.residual,t.tolerance,abs(t.residual)<=t.tolerance
 FROM rows r LEFT JOIN clubs c ON c.id=r.id CROSS JOIN totals t ORDER BY r.net;
END $$;

REVOKE ALL ON FUNCTION public.fn_anon_exposure_check() FROM PUBLIC;GRANT ALL ON FUNCTION public.fn_anon_exposure_check() TO service_role;REVOKE ALL ON FUNCTION public.fn_bbj_analytics(p_pool_id uuid) FROM PUBLIC;GRANT ALL ON FUNCTION public.fn_bbj_analytics(p_pool_id uuid) TO authenticated;GRANT ALL ON FUNCTION public.fn_bbj_analytics(p_pool_id uuid) TO service_role;REVOKE ALL ON FUNCTION public.fn_bbj_mini_for_club(p_club_id uuid) FROM PUBLIC;GRANT ALL ON FUNCTION public.fn_bbj_mini_for_club(p_club_id uuid) TO authenticated;GRANT ALL ON FUNCTION public.fn_bbj_mini_for_club(p_club_id uuid) TO service_role;REVOKE ALL ON FUNCTION public.fn_bbj_parked_reserve(p_pool_id uuid, p_bank text) FROM PUBLIC;GRANT ALL ON FUNCTION public.fn_bbj_parked_reserve(p_pool_id uuid, p_bank text) TO service_role;REVOKE ALL ON FUNCTION public.fn_bbj_pool_for_club(p_club_id uuid) FROM PUBLIC;GRANT ALL ON FUNCTION public.fn_bbj_pool_for_club(p_club_id uuid) TO authenticated;GRANT ALL ON FUNCTION public.fn_bbj_pool_for_club(p_club_id uuid) TO service_role;REVOKE ALL ON FUNCTION public.fn_club_commission_accrued(p_club_id uuid, p_since timestamp with time zone, p_until timestamp with time zone) FROM PUBLIC;GRANT ALL ON FUNCTION public.fn_club_commission_accrued(p_club_id uuid, p_since timestamp with time zone, p_until timestamp with time zone) TO authenticated;GRANT ALL ON FUNCTION public.fn_club_commission_accrued(p_club_id uuid, p_since timestamp with time zone, p_until timestamp with time zone) TO service_role;REVOKE ALL ON FUNCTION public.fn_credit_treasury(p_club_id uuid, p_amount numeric, p_reason text, p_metadata jsonb, p_op_id text) FROM PUBLIC;GRANT ALL ON FUNCTION public.fn_credit_treasury(p_club_id uuid, p_amount numeric, p_reason text, p_metadata jsonb, p_op_id text) TO service_role;REVOKE ALL ON FUNCTION public.fn_credit_treasury_zd4core(p_club_id uuid, p_amount numeric, p_reason text, p_metadata jsonb) FROM PUBLIC;GRANT ALL ON FUNCTION public.fn_credit_treasury_zd4core(p_club_id uuid, p_amount numeric, p_reason text, p_metadata jsonb) TO service_role;REVOKE ALL ON FUNCTION public.fn_union_accounting_run_at(p_period_end timestamp with time zone) FROM PUBLIC;GRANT ALL ON FUNCTION public.fn_union_accounting_run_at(p_period_end timestamp with time zone) TO authenticated;GRANT ALL ON FUNCTION public.fn_union_accounting_run_at(p_period_end timestamp with time zone) TO service_role;REVOKE ALL ON FUNCTION public.fn_union_club_exposure(p_union_id uuid, p_week_start timestamp with time zone) FROM PUBLIC;GRANT ALL ON FUNCTION public.fn_union_club_exposure(p_union_id uuid, p_week_start timestamp with time zone) TO service_role;REVOKE ALL ON FUNCTION public.fn_union_reconciliation_report(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) FROM PUBLIC;GRANT ALL ON FUNCTION public.fn_union_reconciliation_report(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) TO authenticated;GRANT ALL ON FUNCTION public.fn_union_reconciliation_report(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) TO service_role;

